// src/socket.js
import { io } from 'socket.io-client';

const SOCKET_URL = process.env.REACT_APP_API_URL || 'http://localhost:5003';

// دریافت توکن از localStorage
const getToken = () => localStorage.getItem('token');

// ایجاد singleton socket
export const socket = io(SOCKET_URL, {
  autoConnect: false,              // دستی وصل می‌شیم (بعد از لاگین)
  reconnection: true,
  reconnectionAttempts: 5,
  reconnectionDelay: 1000,
  reconnectionDelayMax: 5000,
  transports: ['polling', 'websocket'], // اول polling بعد websocket
  auth: {
    token: getToken() // ارسال توکن JWT
  },
  withCredentials: true
});

// برای دیباگ
socket.on('connect', () => {
  console.log('Socket متصل شد - ID:', socket.id);
});

socket.on('connect_error', (err) => {
  console.error('خطای اتصال socket:', err.message);
});

socket.on('disconnect', (reason) => {
  console.log('Socket قطع شد - دلیل:', reason);
});

// تابع برای آپدیت توکن (وقتی کاربر لاگین می‌کنه یا توکن عوض می‌شه)
export const updateSocketToken = (token) => {
  if (socket.auth) {
    socket.auth.token = token;
  }
  // اگر متصل نیست، توکن رو ذخیره کن برای اتصال بعدی
  if (!socket.connected) {
    localStorage.setItem('token', token);
  }
};
