import React, { useEffect, useState } from 'react';
import { useUser } from '../contexts/UserContext';
import { socket } from '../socket';

// تصاویر
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import cashImage from '../images/cash.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';

const SlamHeader = () => {
  const { user: userFromContext, setUser } = useUser();

  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    console.log('SlamHeader: userFromContext =', userFromContext); // برای دیباگ

    if (userFromContext === undefined) {
      setIsLoading(true);
      setError(null);
      return;
    }

    if (userFromContext === null) {
      setIsLoading(false);
      setError('لطفاً وارد حساب کاربری خود شوید');
      return;
    }

    setIsLoading(false);
    setError(null);
  }, [userFromContext]);

  // گوش دادن به سوکت + fallback اولیه
  useEffect(() => {
    if (!userFromContext) {
      console.log('SlamHeader: منتظر کاربر از context...');
      return;
    }

    const handleUserUpdate = (updatedData) => {
      console.log('آپدیت از سوکت در SlamHeader:', updatedData);
      setUser(prev => {
        const newUser = { ...prev, ...updatedData };
        console.log('کاربر جدید در context:', newUser);
        return newUser;
      });
    };

    socket.on('user:update', handleUserUpdate);

    // fallback: اگر سوکت هنوز داده‌ای نداده، از API بگیر
    const fetchInitial = async () => {
      try {
        const token = localStorage.getItem('token');
        if (!token) throw new Error('توکن وجود ندارد');

        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
        const res = await fetch(`${apiUrl}/api/auth/profile`, {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        });

        if (!res.ok) {
          throw new Error('خطا در گرفتن پروفایل');
        }

        const data = await res.json();
        console.log('داده اولیه از API:', data);
        setUser(data.user || data); // بسته به ساختار پاسخ سرور
      } catch (err) {
        console.error('خطا در fetch اولیه:', err);
        setError('خطا در بارگذاری اطلاعات کاربر');
      } finally {
        setIsLoading(false);
      }
    };

    fetchInitial();

    return () => {
      socket.off('user:update', handleUserUpdate);
    };
  }, [userFromContext, setUser]);

  if (isLoading) {
    return <div className="slam">در حال بارگذاری...</div>;
  }

  if (error) {
    return (
      <div className="slam" style={{ background: '#fee2e2', padding: '16px', textAlign: 'center' }}>
        {error}
        <button onClick={() => window.location.href = '/login'} style={{ marginRight: 12 }}>
          ورود / ثبت‌نام
        </button>
      </div>
    );
  }

  const { username, teamName, coins = 0, banknotes = 0, teamPower = 0 } = userFromContext || {};

  return (
    <div className="slam">
      <div className="left">
        <div className="col1">
          <img src={(userFromContext && userFromContext.teamLogo) || imagePcg} alt="" />
          <span>نام تیم: {teamName || '---'}</span>
        </div>

        <div className="col2">
          <img src={Image200} alt="" />
          <span>{Number(coins).toLocaleString('fa-IR')}</span>
        </div>

        <div className="col3">
          <img src={cashImage} alt="پول" />
          <span>{Number(banknotes)} اسکناس</span>
        </div>

        <div className="col4">
          <img src={Image300} alt="" />
          <span>
            قدرت تیم: <strong>{teamPower}</strong>
          </span>
        </div>

        <div className="col5">
          <img src={Image400} alt="" />
          <span>ثبت‌نام در کاپ حذف</span>
        </div>
      </div>

      <div className="right" style={{ direction: 'rtl', textAlign: 'center' }}>
        {username && (
          <span style={{ marginLeft: 12, fontWeight: 600, color: '#1a1a1a' }}>
            سلام، {username}
          </span>
        )}
        <div className="va" style={{ display: 'inline-block', margin: '0 10px', position: 'relative' }}>
          {/* پیام‌ها */}
          <div style={{ fontSize: 28, marginBottom: 6, color: '#777', position: 'relative' }}>
            <svg /* ... */ />
            <span style={{ /* ... */ }}>3</span>
          </div>
          <h5 style={{ fontSize: '0.7rem', color: '#555' }}>پیام‌ها</h5>
        </div>

        <div className="va" style={{ display: 'inline-block', margin: '0 10px' }}>
          {/* تنظیمات */}
          <div style={{ fontSize: 28, marginBottom: 6, color: '#777' }}>
            <svg /* ... */ />
          </div>
          <h5 style={{ fontSize: '0.7rem', color: '#555' }}>تنظیمات کاربری</h5>
        </div>
      </div>
    </div>
  );
};

export default SlamHeader;