import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { paymentService } from '../services/payment';

const Payment = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [packageItem, setPackageItem] = useState(null);
  const [loading, setLoading] = useState(true);
  const [processing, setProcessing] = useState(false);
  const [userData, setUserData] = useState({
    name: '',
    email: '',
    phone: '',
    description: ''
  });

  useEffect(() => {
    const packageId = searchParams.get('package');
    if (!packageId) {
      navigate('/shop');
      return;
    }
    loadPackage(packageId);
  }, [searchParams, navigate]);

  const loadPackage = async (packageId) => {
    try {
      const response = await paymentService.getPackages();
      const allPackages = [
        ...response.packages.coins,
        ...response.packages.banknotes,
        ...response.packages.special
      ];
      const selected = allPackages.find(pkg => pkg.id === parseInt(packageId));
      
      if (selected) {
        setPackageItem(selected);
      } else {
        navigate('/shop');
      }
    } catch (error) {
      console.error('Error loading package:', error);
      navigate('/shop');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setUserData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handlePayment = async (e) => {
    e.preventDefault();
    if (!packageItem || processing) return;

    // اعتبارسنجی ساده
    if (!userData.name || !userData.phone) {
      alert('لطفا نام و شماره تماس را وارد کنید');
      return;
    }

    setProcessing(true);
    try {
      const response = await paymentService.createPayment(packageItem.id, userData);
      
      if (response.success && response.paymentURL) {
        // هدایت به درگاه پرداخت
        window.location.href = response.paymentURL;
      } else {
        alert('خطا در اتصال به درگاه پرداخت');
      }
    } catch (error) {
      console.error('Payment error:', error);
      alert(error.response?.data?.message || 'خطا در پرداخت');
    } finally {
      setProcessing(false);
    }
  };

  const handleCancel = () => {
    navigate('/shop');
  };

  if (loading) {
    return (
      <div style={{ 
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'center', 
        justifyContent: 'center', 
        height: '50vh',
        textAlign: 'center'
      }}>
        <div style={{ fontSize: '2rem', marginBottom: '1rem' }}>🔄</div>
        <p>در حال بارگذاری...</p>
      </div>
    );
  }

  if (!packageItem) {
    return (
      <div style={{ 
        textAlign: 'center', 
        padding: '2rem',
        direction: 'rtl'
      }}>
        <h2>❌ پکیج مورد نظر یافت نشد</h2>
        <button 
          onClick={() => navigate('/shop')}
          style={{
            padding: '0.5rem 1rem',
            backgroundColor: '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer',
            marginTop: '1rem'
          }}
        >
          بازگشت به فروشگاه
        </button>
      </div>
    );
  }

  return (
    <div style={{ 
      padding: '2rem',
      maxWidth: '800px',
      margin: '0 auto',
      direction: 'rtl'
    }}>
      <div style={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        marginBottom: '2rem',
        borderBottom: '1px solid #ddd',
        paddingBottom: '1rem'
      }}>
        <h1 style={{ margin: 0 }}>💳 پرداخت</h1>
        <button 
          onClick={handleCancel}
          style={{
            padding: '0.5rem 1rem',
            backgroundColor: '#6c757d',
            color: 'white',
            border: 'none',
            borderRadius: '4px',
            cursor: 'pointer'
          }}
        >
          ↩️ بازگشت
        </button>
      </div>

      <div style={{ 
        display: 'grid', 
        gridTemplateColumns: '1fr 1fr', 
        gap: '2rem'
      }}>
        {/* خلاصه سفارش */}
        <div style={{
          backgroundColor: '#f8f9fa',
          padding: '1.5rem',
          borderRadius: '8px',
          border: '1px solid #dee2e6'
        }}>
          <h3 style={{ marginTop: 0 }}>خلاصه سفارش</h3>
          <div style={{ lineHeight: '2' }}>
            <p><strong>پکیج:</strong> {packageItem.description}</p>
            <p><strong>مبلغ:</strong> {packageItem.price.toLocaleString()} تومان</p>
            {packageItem.coins && (
              <p><strong>سکه:</strong> {packageItem.coins.toLocaleString()} 🪙</p>
            )}
            {packageItem.banknotes && (
              <p><strong>اسکناس:</strong> {packageItem.banknotes.toLocaleString()} 🎫</p>
            )}
          </div>
        </div>

        {/* فرم پرداخت */}
        <div style={{
          backgroundColor: 'white',
          padding: '1.5rem',
          borderRadius: '8px',
          border: '1px solid #dee2e6'
        }}>
          <h3 style={{ marginTop: 0 }}>اطلاعات پرداخت</h3>
          <form onSubmit={handlePayment}>
            <div style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', marginBottom: '0.5rem' }}>
                نام و نام خانوادگی *
              </label>
              <input
                type="text"
                name="name"
                value={userData.name}
                onChange={handleInputChange}
                required
                style={{
                  width: '100%',
                  padding: '0.5rem',
                  border: '1px solid #ddd',
                  borderRadius: '4px'
                }}
              />
            </div>

            <div style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', marginBottom: '0.5rem' }}>
                ایمیل
              </label>
              <input
                type="email"
                name="email"
                value={userData.email}
                onChange={handleInputChange}
                style={{
                  width: '100%',
                  padding: '0.5rem',
                  border: '1px solid #ddd',
                  borderRadius: '4px'
                }}
              />
            </div>

            <div style={{ marginBottom: '1rem' }}>
              <label style={{ display: 'block', marginBottom: '0.5rem' }}>
                شماره تماس *
              </label>
              <input
                type="tel"
                name="phone"
                value={userData.phone}
                onChange={handleInputChange}
                required
                style={{
                  width: '100%',
                  padding: '0.5rem',
                  border: '1px solid #ddd',
                  borderRadius: '4px'
                }}
              />
            </div>

            <div style={{ marginBottom: '1.5rem' }}>
              <label style={{ display: 'block', marginBottom: '0.5rem' }}>
                توضیحات (اختیاری)
              </label>
              <textarea
                name="description"
                value={userData.description}
                onChange={handleInputChange}
                rows="3"
                style={{
                  width: '100%',
                  padding: '0.5rem',
                  border: '1px solid #ddd',
                  borderRadius: '4px',
                  resize: 'vertical'
                }}
              />
            </div>

            <div style={{ display: 'flex', gap: '1rem' }}>
              <button
                type="submit"
                disabled={processing}
                style={{
                  flex: 1,
                  padding: '0.75rem',
                  backgroundColor: processing ? '#6c757d' : '#28a745',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: processing ? 'not-allowed' : 'pointer',
                  fontSize: '1rem'
                }}
              >
                {processing ? 'در حال پردازش...' : '💳 پرداخت'}
              </button>
              
              <button
                type="button"
                onClick={handleCancel}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#6c757d',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer'
                }}
              >
                انصراف
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );
};

export default Payment;