import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useUser } from '../contexts/UserContext';
import '../styles/coatch.css';

const SimpleTeamForm = () => {
  const navigate = useNavigate();
  const { setUser: setContextUser } = useUser();

  const [formData, setFormData] = useState({
    teamName: '',
    teamCity: 'تهران',
    selectedLeague: 'لیگ محلات دسته ۳'
  });

  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [user, setUser] = useState(null);

  const [teamLogoFile, setTeamLogoFile] = useState(null);
  const [teamLogoPreview, setTeamLogoPreview] = useState(null);

  // لیگ‌های موجود
  const leagues = [
    { id: 1, name: 'لیگ محلات دسته ۳', level: 'آسان', prize: '۱,۰۰۰ سکه' },
    { id: 2, name: 'لیگ محلات دسته ۲', level: 'متوسط', prize: '۳,۰۰۰ سکه' },
    { id: 3, name: 'لیگ محلات دسته ۱', level: 'سخت', prize: '۵,۰۰۰ سکه' }
  ];

  // شهرهای موجود
  const cities = ['تهران', 'مشهد', 'اصفهان', 'شیراز', 'تبریز', 'اهواز', 'رشت', 'کرج'];

  // چک کردن وضعیت ورود کاربر موقع لود صفحه
  useEffect(() => {
    const token = localStorage.getItem('token');
    const storedUser = localStorage.getItem('user');

    if (!token || !storedUser) {
      setError('لطفاً ابتدا وارد حساب کاربری شوید');
      setTimeout(() => navigate('/login'), 2000);
      return;
    }

    try {
      const parsedUser = JSON.parse(storedUser);
      if (!parsedUser._id && !parsedUser.id) {
        throw new Error('اطلاعات کاربر نامعتبر است');
      }
      setUser(parsedUser);
    } catch (err) {
      setError('خطا در خواندن اطلاعات ورود. لطفاً دوباره وارد شوید.');
      localStorage.removeItem('token');
      localStorage.removeItem('user');
      setTimeout(() => navigate('/login'), 2000);
    }
  }, [navigate]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    setError(''); // پاک کردن خطا موقع تایپ
  };

  const handleFileChange = (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setTeamLogoFile(file);
    const reader = new FileReader();
    reader.onload = () => setTeamLogoPreview(reader.result);
    reader.readAsDataURL(file);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    // چک دوباره (برای اطمینان)
    const token = localStorage.getItem('token');
    const storedUser = JSON.parse(localStorage.getItem('user') || '{}');

    if (!token || !(storedUser._id || storedUser.id)) {
      setError('لطفاً ابتدا وارد حساب کاربری شوید');
      navigate('/login');
      return;
    }

    if (!formData.teamName.trim()) {
      setError('نام تیم نمی‌تواند خالی باشد');
      return;
    }

    setLoading(true);
    setError('');
    setSuccess('');

    try {
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const defaults = {
        stadiumLevel: 3,
        sponsorLevel: 3,
        tvLevel: 3,
        campLevel: 3,
        teamPower: 0,
        rank: 0,
        lineup: [],
        manager: '',
        description: ''
      };

      let response;
      let data;

      // اگر لوگو انتخاب شده، از FormData استفاده کن
      if (teamLogoFile) {
        const fd = new FormData();
        fd.append('teamLogo', teamLogoFile);
        fd.append('userId', storedUser._id || storedUser.id);
        fd.append('teamName', formData.teamName.trim());
        fd.append('teamCity', formData.teamCity);
        fd.append('league', formData.selectedLeague);
        fd.append('stadiumLevel', defaults.stadiumLevel);
        fd.append('sponsorLevel', defaults.sponsorLevel);
        fd.append('tvLevel', defaults.tvLevel);
        fd.append('campLevel', defaults.campLevel);
        fd.append('teamPower', defaults.teamPower);
        fd.append('rank', defaults.rank);
        fd.append('lineup', JSON.stringify(defaults.lineup));
        fd.append('manager', defaults.manager);
        fd.append('description', defaults.description);

        response = await fetch(`${apiUrl}/api/team/create`, {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`
          },
          body: fd
        });
        data = await response.json();
      } else {
        response = await fetch(`${apiUrl}/api/team/create`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify({
              userId: storedUser._id || storedUser.id, // سازگار با هر دو حالت
              teamName: formData.teamName.trim(),
              teamCity: formData.teamCity,
              league: formData.selectedLeague,
              stadiumLevel: defaults.stadiumLevel,
              sponsorLevel: defaults.sponsorLevel,
              tvLevel: defaults.tvLevel,
              campLevel: defaults.campLevel,
              teamPower: defaults.teamPower,
              rank: defaults.rank,
              lineup: defaults.lineup,
              manager: defaults.manager,
              description: defaults.description
            })
        });
        data = await response.json();
      }

      if (!response.ok) {
        throw new Error(data.message || 'خطا در ثبت تیم');
      }

      // موفقیت: بروزرسانی از سرور (تیم + بازیکنان) و ذخیره
      const updatedUser = data.user
        ? { ...storedUser, ...data.user, teamName: data.user.teamName || formData.teamName.trim() }
        : { ...storedUser, teamName: formData.teamName.trim(), teamCity: formData.teamCity, league: formData.selectedLeague };

      // اضافه کردن فیلدهای پیش‌فرض/دریافتی از سرور
      updatedUser.teamLogo = data.teamLogo || (data.user && data.user.teamLogo) || teamLogoPreview || updatedUser.teamLogo;
      updatedUser.stadiumLevel = data.stadiumLevel || (data.user && data.user.stadiumLevel) || defaults.stadiumLevel;
      updatedUser.sponsorLevel = data.sponsorLevel || (data.user && data.user.sponsorLevel) || defaults.sponsorLevel;
      updatedUser.tvLevel = data.tvLevel || (data.user && data.user.tvLevel) || defaults.tvLevel;
      updatedUser.campLevel = data.campLevel || (data.user && data.user.campLevel) || defaults.campLevel;
      updatedUser.teamPower = data.teamPower || (data.user && data.user.teamPower) || defaults.teamPower;
      updatedUser.rank = data.rank || (data.user && data.user.rank) || defaults.rank;
      updatedUser.lineup = data.lineup || (data.user && data.user.lineup) || defaults.lineup;
      updatedUser.manager = data.manager || (data.user && data.user.manager) || defaults.manager;
      updatedUser.description = data.description || (data.user && data.user.description) || defaults.description;

      localStorage.setItem('user', JSON.stringify(updatedUser));
      setUser(updatedUser);
      setContextUser(updatedUser);

      setSuccess(`تیم "${formData.teamName}" با موفقیت ثبت شد!`);

      // هدایت بعد از 1 ثانیه به صفحه پروفایل مربی که اطلاعات آپدیت شده را نشان می‌دهد
      setTimeout(() => {
        navigate('/CoachProfile2');
      }, 1000);

    } catch (err) {
      setError(err.message || 'خطا در ارتباط با سرور. لطفاً دوباره تلاش کنید.');
      console.error('خطا در ثبت تیم:', err);
    } finally {
      setLoading(false);
    }
  };

  // اگر کاربر هنوز لود نشده یا خطا هست
  if (error && !user) {
    return (
      <div style={{
        direction: 'rtl',
        textAlign: 'center',
        padding: '100px 20px',
        background: '#f8f9fa',
        minHeight: '100vh'
      }}>
        <h2 style={{ color: '#dc2626', marginBottom: '20px' }}>خطا</h2>
        <p style={{ fontSize: '1.3rem', color: '#374151' }}>{error}</p>
        <button
          onClick={() => navigate('/login')}
          style={{
            marginTop: '30px',
            padding: '14px 50px',
            background: '#3b82f6',
            color: 'white',
            border: 'none',
            borderRadius: '12px',
            fontSize: '1.3rem',
            cursor: 'pointer'
          }}
        >
          رفتن به صفحه ورود
        </button>
      </div>
    );
  }

  return (
    <div style={{
      direction: 'rtl',
      maxWidth: '700px',
      margin: '60px auto',
      padding: '0 20px'
    }}>
      <div style={{
        background: 'white',
        borderRadius: '16px',
        boxShadow: '0 10px 30px rgba(0,0,0,0.1)',
        padding: '40px',
      }}>
        <h1 style={{
          textAlign: 'center',
          color: '#1e293b',
          marginBottom: '40px',
          fontSize: '2.5rem'
        }}>
          ثبت‌نام تیم جدید
        </h1>

        <p style={{
          textAlign: 'center',
          color: '#64748b',
          marginBottom: '40px'
        }}>
          تیم خود را بسازید و وارد رقابت‌های لیگ شوید
        </p>

        {error && (
          <div style={{
            background: '#fee2e2',
            color: '#991b1b',
            padding: '16px',
            borderRadius: '8px',
            marginBottom: '30px',
            textAlign: 'center'
          }}>
            {error}
          </div>
        )}

        {success && (
          <div style={{
            background: '#d1fae5',
            color: '#065f46',
            padding: '16px',
            borderRadius: '8px',
            marginBottom: '30px',
            textAlign: 'center',
            fontWeight: 'bold'
          }}>
            {success}
          </div>
        )}

        <form onSubmit={handleSubmit}>
          {/* نام تیم */}
          <div style={{ marginBottom: '30px' }}>
            <label style={{
              display: 'block',
              marginBottom: '8px',
              fontWeight: '600',
              color: '#374151'
            }}>
              نام تیم <span style={{ color: '#ef4444' }}>*</span>
            </label>
            <input
              type="text"
              name="teamName"
              value={formData.teamName}
              onChange={handleChange}
              placeholder="مثال: عقابان تهران"
              required
              minLength="3"
              maxLength="20"
              style={{
                width: '100%',
                padding: '14px',
                border: '1px solid #d1d5db',
                borderRadius: '8px',
                fontSize: '1.1rem'
              }}
            />
          </div>

          {/* شهر */}
          <div style={{ marginBottom: '30px' }}>
            <label style={{
              display: 'block',
              marginBottom: '8px',
              fontWeight: '600',
              color: '#374151'
            }}>
              شهر تیم
            </label>
            <select
              name="teamCity"
              value={formData.teamCity}
              onChange={handleChange}
              style={{
                width: '100%',
                padding: '14px',
                border: '1px solid #d1d5db',
                borderRadius: '8px',
                fontSize: '1.1rem',
                background: 'white'
              }}
            >
              {cities.map(city => (
                <option key={city} value={city}>{city}</option>
              ))}
            </select>
          </div>

          {/* انتخاب لیگ */}
          <div style={{ marginBottom: '40px' }}>
            <label style={{
              display: 'block',
              marginBottom: '12px',
              fontWeight: '600',
              color: '#374151'
            }}>
              انتخاب لیگ شروع
            </label>

            <div style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
              gap: '16px'
            }}>
              {leagues.map(league => (
                <label
                  key={league.id}
                  style={{
                    display: 'flex',
                    alignItems: 'center',
                    padding: '16px',
                    border: formData.selectedLeague === league.name 
                      ? '2px solid #3b82f6' 
                      : '1px solid #d1d5db',
                    borderRadius: '12px',
                    cursor: 'pointer',
                    background: formData.selectedLeague === league.name 
                      ? '#eff6ff' 
                      : 'white',
                    transition: 'all 0.2s'
                  }}
                >
                  <input
                    type="radio"
                    name="selectedLeague"
                    value={league.name}
                    checked={formData.selectedLeague === league.name}
                    onChange={handleChange}
                    style={{ marginLeft: '12px' }}
                  />
                  <div style={{ flex: 1, marginRight: '16px' }}>
                    <div style={{ fontWeight: 'bold', marginBottom: '4px' }}>
                      {league.name}
                    </div>
                    <div style={{ color: '#64748b', fontSize: '0.95rem' }}>
                      سطح: {league.level} • جایزه: {league.prize}
                    </div>
                  </div>
                </label>
              ))}
            </div>
          </div>

          {/* دکمه‌ها */}
          {/* لوگوی تیم (اختیاری) */}
          <div style={{ marginBottom: '24px', textAlign: 'center' }}>
            <label style={{ display: 'block', marginBottom: 8, fontWeight: 600, color: '#374151' }}>لوگوی تیم (اختیاری)</label>
            <input type="file" accept="image/*" onChange={handleFileChange} />
            {teamLogoPreview && (
              <div style={{ marginTop: 12 }}>
                <img src={teamLogoPreview} alt="preview" style={{ maxWidth: 160, borderRadius: 8, boxShadow: '0 6px 18px rgba(0,0,0,0.08)' }} />
              </div>
            )}
          </div>
          <div style={{
            display: 'flex',
            gap: '20px',
            justifyContent: 'center',
            marginTop: '40px'
          }}>
            <button
              type="button"
              onClick={() => navigate(-1)}
              style={{
                padding: '14px 50px',
                background: '#6b7280',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                fontSize: '1.2rem',
                cursor: 'pointer'
              }}
            >
              بازگشت
            </button>

            <button
              type="submit"
              disabled={loading || !formData.teamName.trim()}
              style={{
                padding: '14px 50px',
                background: loading ? '#9ca3af' : '#3b82f6',
                color: 'white',
                border: 'none',
                borderRadius: '12px',
                fontSize: '1.2rem',
                fontWeight: '600',
                cursor: loading ? 'not-allowed' : 'pointer',
                display: 'flex',
                alignItems: 'center',
                gap: '10px'
              }}
            >
              {loading ? 'در حال ثبت...' : 'ثبت تیم و شروع بازی'}
            </button>
          </div>
        </form>

        <p style={{
          textAlign: 'center',
          marginTop: '40px',
          color: '#64748b',
          fontSize: '0.95rem'
        }}>
          با ثبت‌نام، با <a href="/terms" style={{ color: '#3b82f6' }}>قوانین بازی</a> موافقت می‌کنید.
        </p>
      </div>
    </div>
  );
};

export default SimpleTeamForm;