import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import '../styles/coatch.css';
import '../styles/tamrin.css'
import image1 from '../کارت ها/کارت-ساسان-انصاری.png'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments, FaTrophy } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import api from '../services/api';
import { userService } from '../services/userService';
import { youthCampService } from '../services/youthCampService';
import { squadService, normalizePlayers } from '../services/squadService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import "../styles/risponsive.css"

// ========== آدرس سرور تصاویر ==========
const IMAGE_BASE_URL = 'http://localhost:5003';

// ========== تصویر پیش‌فرض بازیکن ==========
const DEFAULT_PLAYER_IMAGE = 'https://via.placeholder.com/150?text=Player';

function Tamrin() {
  const [loading, setLoading] = useState(true);
  const [userData, setUserData] = useState({
    coins: 0,
    teamName: 'سی تی',
    players: []
  });
  const [trainingInfo, setTrainingInfo] = useState({
    hasCoach: false,
    coachQuality: 0,
    coachName: '',
    totalPlayers: 0
  });
  const [selectedPlayers, setSelectedPlayers] = useState([]);
  const [trainingType, setTrainingType] = useState('group');
  const [training, setTraining] = useState(false);
  const [message, setMessage] = useState('');
  const [selectedPlayerId, setSelectedPlayerId] = useState(null);
  const [playerSkills, setPlayerSkills] = useState({
    speed: 50,
    power: 50,
    ballIntercept: 50,
    dribble: 50,
    shoot: 50,
    pass: 50
  });

  // ========== تابع کمکی برای دریافت تصویر بازیکن ==========
  const getPlayerImage = (player) => {
    if (!player) return DEFAULT_PLAYER_IMAGE;
    
    if (player.image) {
      // اگر URL کامل است
      if (player.image.startsWith('http://') || player.image.startsWith('https://')) {
        return player.image;
      }
      // اگر از روت سرور شروع می‌شود
      if (player.image.startsWith('/uploads/')) {
        return `${IMAGE_BASE_URL}${player.image}`;
      }
      // اگر فقط نام فایل است
      return `${IMAGE_BASE_URL}/uploads/players/${player.image}`;
    }
    return DEFAULT_PLAYER_IMAGE;
  };

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [squadData, campRes, trainingRes] = await Promise.all([
        squadService.getPlayers(),
        youthCampService.getCampInfo().catch(() => null),
        api.get('/squad/training-info').catch(() => null)
      ]);

      const playersFromTraining = trainingRes?.data?.players;
      const players = normalizePlayers(
        (squadData.players && squadData.players.length > 0)
          ? squadData.players
          : (playersFromTraining || [])
      );

      const processedPlayers = players.map(p => ({
        ...p,
        _id: String(p._id),
        _image: getPlayerImage(p)
      }));

      setUserData({
        coins: squadData.coins || 0,
        teamName: squadData.teamName || squadData.username || 'تیم من',
        players: processedPlayers
      });

      if (trainingRes?.data?.trainingInfo) {
        setTrainingInfo(trainingRes.data.trainingInfo);
      } else if (squadData.coach) {
        setTrainingInfo({
          hasCoach: true,
          coachQuality: squadData.coach.quality || 1,
          coachName: squadData.coach.name || '',
          totalPlayers: processedPlayers.length
        });
      }
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handlePlayerSelect = (playerId) => {
    const id = String(playerId);
    setSelectedPlayerId(id);
    if (trainingType === 'individual') {
      setSelectedPlayers([]);
    } else {
      setSelectedPlayers(prev =>
        prev.includes(id) ? prev.filter(x => x !== id) : [...prev, id]
      );
    }
  };

  const handleTrainingTypeChange = (type) => {
    setTrainingType(type);
    setSelectedPlayers([]);
    setSelectedPlayerId(null);
  };

  const handleStartTraining = async () => {
    const ids = trainingType === 'individual' 
      ? (selectedPlayerId ? [selectedPlayerId] : []) 
      : selectedPlayers;
    
    if (ids.length === 0) {
      setMessage('حداقل یک بازیکن انتخاب کنید');
      return;
    }

    if (!trainingInfo.hasCoach) {
      setMessage('❌ شما مربی ندارید! ابتدا یک مربی خریداری کنید');
      return;
    }

    try {
      setTraining(true);
      setMessage('');
      
      const res = await api.post('/squad/train-players', { 
        playerIds: ids, 
        trainingType 
      });

      if (res.data.success) {
        setMessage(`✅ ${res.data.message} | کیفیت مربی: ${res.data.coachQuality}`);
        await loadData();
      } else {
        setMessage(`❌ ${res.data.message}`);
      }

      setSelectedPlayers([]);
      setSelectedPlayerId(null);
      setTimeout(() => setMessage(''), 5000);
    } catch (error) {
      setMessage(`❌ ${error.response?.data?.message || 'خطا در تمرین'}`);
    } finally {
      setTraining(false);
    }
  };

  const getSkillLabel = (key) => {
    const labels = {
      speed: 'سرعت',
      shot: 'شوت',
      pass: 'پاس',
      defense: 'دفاع',
      dribble: 'دریبل',
      physical: 'قدرت',
      stamina: 'استقامت'
    };
    return labels[key] || key;
  };

  // ========== بازیکن انتخاب‌شده ==========
  const selectedPlayerData = userData.players.find(p => 
    p._id?.toString() === selectedPlayerId?.toString()
  );

  // ========== نوار مهارت ==========
  const SkillBar = ({ label, value, color = '#007bff' }) => (
    <div style={{ 
      display: 'flex', 
      alignItems: 'center', 
      gap: '10px',
      marginBottom: '12px',
      padding: '8px',
      backgroundColor: '#f8f9fa',
      borderRadius: '8px'
    }}>
      <span style={{ 
        minWidth: '80px', 
        fontWeight: '600',
        fontSize: '14px',
        color: '#495057'
      }}>
        {label}
      </span>
      <div style={{ 
        flex: 1,
        height: '20px',
        backgroundColor: '#e9ecef',
        borderRadius: '10px',
        overflow: 'hidden',
        position: 'relative'
      }}>
        <div style={{
          width: `${value}%`,
          height: '100%',
          backgroundColor: color,
          transition: 'width 0.5s ease',
          borderRadius: '10px'
        }} />
        <span style={{
          position: 'absolute',
          right: '8px',
          top: '50%',
          transform: 'translateY(-50%)',
          fontSize: '12px',
          fontWeight: 'bold',
          color: '#fff',
          textShadow: '0 1px 2px rgba(0,0,0,0.5)'
        }}>
          {value}
        </span>
      </div>
    </div>
  );

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        <div className="main1">
          <SlamHeader/>

          {message && (
            <div style={{ 
              padding: '1rem', 
              margin: '1rem', 
              backgroundColor: message.includes('✅') ? '#d4edda' : '#f8d7da',
              color: message.includes('✅') ? '#155724' : '#721c24',
              borderRadius: '4px',
              textAlign: 'center'
            }}>
              {message}
            </div>
          )}

          <div className="cardd45">
            <div className="tas">
              <div className="tamba">
                <div className="pss">
                  <div className="pssba">
                    <h6 className='cljlcs'>تمرین گروهی</h6>
                  </div>
                  <div className="pasdpa">
                    <h4>برگزاری تمرین گروهی</h4>
                    <h6>مربی تیم شما توانایی برگزاری تمرین گروهی برای بازیکنان را دارد (بعد از انجام این تمرین +{trainingInfo.coachQuality || 0} واحد به مهارت انتخابی هر بازیکن اضافه خواهد شد)</h6>
                  </div>
                  <button 
                    className='lkdsa'
                    onClick={() => handleTrainingTypeChange('group')}
                    style={{
                      backgroundColor: trainingType === 'group' ? '#28a745' : '#6c757d',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      padding: '0.5rem 1rem',
                      cursor: 'pointer'
                    }}
                  >
                    <h6>{trainingType === 'group' ? '✓ انتخاب شده' : 'انتخاب'}</h6>
                  </button>
                </div>
                <div className="pss">
                  <div className="pssba">
                    <h6 className='cljlcs'>تمرین اختصاصی</h6>
                  </div>
                  <div className="pasdpa">
                    <h4>برگزاری تمرین اختصاصی</h4>
                    <h6>مربی ما توانایی تمرین اختصاصی روی ۱ بازیکن را دارد (بعد از تمرین +{trainingInfo.coachQuality || 0} به مهارت انتخابی همان بازیکن اضافه می‌شود)</h6>
                  </div>
                  <button 
                    className='lkdsa'
                    onClick={() => handleTrainingTypeChange('individual')}
                    style={{
                      backgroundColor: trainingType === 'individual' ? '#28a745' : '#6c757d',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      padding: '0.5rem 1rem',
                      cursor: 'pointer'
                    }}
                  >
                    <h6>{trainingType === 'individual' ? '✓ انتخاب شده' : 'انتخاب'}</h6>
                  </button>
                </div>
              </div>

              <div className="tamva" style={{ display: 'flex', gap: '20px' }}>
                {/* ========== لیست بازیکنان ========== */}
                <div className="adara" style={{ flex: 1 }}>
                  <h4 style={{ marginBottom: '1rem', color: '#333' }}>
                    📋 لیست بازیکنان تیم ({userData.players.length})
                  </h4>
                  <ul style={{ listStyle: 'none', padding: '10px', maxHeight: '500px', overflowY: 'auto' }}>
                    {userData.players && userData.players.length > 0 ? (
                      userData.players.map((player) => (
                        <li key={player._id} style={{
                          padding: '10px',
                          marginBottom: '8px',
                          backgroundColor: String(selectedPlayerId) === String(player._id) ? '#e8f5e9' : 'white',
                          borderRadius: '8px',
                          display: 'flex',
                          alignItems: 'center',
                          gap: '12px',
                          border: String(selectedPlayerId) === String(player._id) ? '2px solid #28a745' : '2px solid #e9ecef',
                          cursor: 'pointer',
                          transition: 'all 0.2s ease'
                        }}
                        onClick={() => handlePlayerSelect(player._id)}
                        >
                          <input
                            type={trainingType === 'individual' ? 'radio' : 'checkbox'}
                            name={trainingType === 'individual' ? 'player' : 'players'}
                            value={player._id}
                            checked={
                              trainingType === 'individual'
                                ? String(selectedPlayerId) === String(player._id)
                                : selectedPlayers.includes(String(player._id))
                            }
                            onChange={(e) => {
                              e.stopPropagation();
                              handlePlayerSelect(player._id);
                            }}
                            style={{ cursor: 'pointer' }}
                          />
                          {/* تصویر بازیکن */}
                          <div style={{
                            width: '45px',
                            height: '45px',
                            borderRadius: '50%',
                            overflow: 'hidden',
                            flexShrink: 0,
                            border: '2px solid #28a745'
                          }}>
                            <img 
                              src={player._image || getPlayerImage(player)} 
                              alt={player.name} 
                              style={{ 
                                width: '100%', 
                                height: '100%', 
                                objectFit: 'cover' 
                              }} 
                              onError={(e) => {
                                e.target.src = DEFAULT_PLAYER_IMAGE;
                              }}
                            />
                          </div>
                          {/* نام و شماره */}
                          <div style={{ flex: 1 }}>
                            <div style={{ fontWeight: 'bold', fontSize: '14px', color: '#333' }}>
                              {player.number && <span style={{ color: '#007bff', marginLeft: '5px' }}>#{player.number} </span>}
                              {player.name}
                            </div>
                            <div style={{ fontSize: '12px', color: '#6c757d' }}>
                              پست: {player.position}
                            </div>
                          </div>
                          {/* Overall */}
                          <div style={{ 
                            backgroundColor: player.overall >= 75 ? '#28a745' : player.overall >= 60 ? '#ffc107' : '#dc3545',
                            color: 'white', 
                            padding: '4px 10px', 
                            borderRadius: '15px',
                            fontSize: '13px',
                            fontWeight: 'bold',
                            minWidth: '45px',
                            textAlign: 'center'
                          }}>
                            {player.overall}
                          </div>
                        </li>
                      ))
                    ) : (
                      <li style={{ 
                        color: '#999', 
                        textAlign: 'center', 
                        padding: '30px',
                        backgroundColor: '#f8f9fa',
                        borderRadius: '8px'
                      }}>
                        هیچ بازیکنی در تیم شما نیست. لطفاً ابتدا بازیکن خریداری کنید.
                      </li>
                    )}
                  </ul>
                </div>

                {/* ========== اطلاعات بازیکن انتخاب‌شده ========== */}
                <div className="sdscha" style={{ 
                  flex: 1,
                  backgroundColor: '#fff',
                  borderRadius: '12px',
                  padding: '20px',
                  border: '2px solid #e9ecef',
                  maxHeight: '550px',
                  overflowY: 'auto'
                }}>
                  {selectedPlayerData ? (
                    <div>
                      {/* هدر اطلاعات بازیکن */}
                      <div style={{ 
                        textAlign: 'center', 
                        marginBottom: '20px',
                        paddingBottom: '15px',
                        borderBottom: '2px solid #e9ecef'
                      }}>
                        <div style={{
                          width: '80px',
                          height: '80px',
                          borderRadius: '50%',
                          margin: '0 auto 10px',
                          overflow: 'hidden',
                          border: '3px solid #28a745'
                        }}>
                          <img 
                            src={selectedPlayerData._image || getPlayerImage(selectedPlayerData)} 
                            alt={selectedPlayerData.name} 
                            style={{ 
                              width: '100%', 
                              height: '100%', 
                              objectFit: 'cover' 
                            }}
                            onError={(e) => {
                              e.target.src = DEFAULT_PLAYER_IMAGE;
                            }}
                          />
                        </div>
                        <h3 style={{ margin: '0 0 5px', color: '#333' }}>
                          {selectedPlayerData.number && <span style={{ color: '#007bff', fontSize: '18px' }}>#{selectedPlayerData.number} </span>}
                          {selectedPlayerData.name}
                        </h3>
                        <div style={{ display: 'flex', justifyContent: 'center', gap: '10px', marginTop: '8px' }}>
                          <span style={{ 
                            backgroundColor: '#007bff',
                            color: 'white',
                            padding: '4px 12px',
                            borderRadius: '15px',
                            fontSize: '13px'
                          }}>
                            پست: {selectedPlayerData.position}
                          </span>
                          <span style={{ 
                            backgroundColor: selectedPlayerData.overall >= 75 ? '#28a745' : '#ffc107',
                            color: 'white',
                            padding: '4px 12px',
                            borderRadius: '15px',
                            fontSize: '13px',
                            fontWeight: 'bold'
                          }}>
                            Overall: {selectedPlayerData.overall}
                          </span>
                        </div>
                      </div>

                      {/* مهارت‌ها */}
                      <h4 style={{ marginBottom: '15px', color: '#333', borderBottom: '1px solid #e9ecef', paddingBottom: '8px' }}>
                        📊 مهارت‌ها
                      </h4>
                      {Object.entries(selectedPlayerData.skills || {}).map(([key, value]) => {
                        let color = '#dc3545';
                        if (value >= 75) color = '#28a745';
                        else if (value >= 60) color = '#ffc107';
                        else if (value >= 40) color = '#fd7e14';
                        
                        return (
                          <SkillBar 
                            key={key} 
                            label={getSkillLabel(key)} 
                            value={value} 
                            color={color}
                          />
                        );
                      })}

                      {/* اطلاعات اضافی */}
                      {selectedPlayerData.age && (
                        <div style={{ 
                          marginTop: '15px',
                          padding: '10px',
                          backgroundColor: '#f8f9fa',
                          borderRadius: '8px'
                        }}>
                          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '5px' }}>
                            <span style={{ color: '#6c757d' }}>سن:</span>
                            <span style={{ fontWeight: 'bold', color: '#333' }}>{selectedPlayerData.age}</span>
                          </div>
                        </div>
                      )}
                    </div>
                  ) : (
                    <div style={{ 
                      padding: '2rem', 
                      textAlign: 'center', 
                      color: '#999',
                      display: 'flex',
                      flexDirection: 'column',
                      alignItems: 'center',
                      justifyContent: 'center',
                      height: '100%'
                    }}>
                      <FaTrophy style={{ fontSize: '48px', marginBottom: '15px', opacity: 0.3 }} />
                      <h5>ابتدا یک بازیکن از لیست انتخاب کنید</h5>
                      <p style={{ fontSize: '13px' }}>
                        با کلیک روی هر بازیکن، اطلاعات و مهارت‌هایش نمایش داده می‌شود
                      </p>
                    </div>
                  )}
                </div>
              </div>

              {/* اطلاعات مربی */}
              <div style={{
                padding: '1rem',
                margin: '1rem',
                backgroundColor: trainingInfo.hasCoach ? '#d4edda' : '#f8d7da',
                color: trainingInfo.hasCoach ? '#155724' : '#721c24',
                borderRadius: '4px',
                textAlign: 'center'
              }}>
                {trainingInfo.hasCoach ? (
                  <span>
                    ✅ مربی تیم: <strong>{trainingInfo.coachName}</strong> | 
                    کیفیت: <strong>{'⭐'.repeat(trainingInfo.coachQuality)}</strong> | 
                    بهبود هر تمرین: <strong>+{trainingInfo.coachQuality}</strong> | 
                    تعداد بازیکنان: <strong>{trainingInfo.totalPlayers}</strong>
                  </span>
                ) : (
                  <span>
                    ❌ شما مربی ندارید! ابتدا یک مربی خریداری کنید تا بتوانید تمرین انجام دهید.
                  </span>
                )}
              </div>

              {(selectedPlayers.length > 0 || selectedPlayerId) && (
                <div style={{ textAlign: 'center', marginTop: '2rem' }}>
                  <button
                    onClick={handleStartTraining}
                    disabled={training || !trainingInfo.hasCoach}
                    style={{
                      padding: '1rem 2rem',
                      backgroundColor: (training || !trainingInfo.hasCoach) ? '#ccc' : '#28a745',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: (training || !trainingInfo.hasCoach) ? 'not-allowed' : 'pointer',
                      fontSize: '1.1rem',
                      fontWeight: 'bold'
                    }}
                  >
                    {training ? 'در حال انجام تمرین...' : 'شروع تمرین'}
                  </button>
                </div>
              )}
               
              <div className="tampa">
                <h5 className='asas'><span style={{ color: "orange" }}>سرعت (Speed):</span> بازیکن با سرعت بالا قادر است در کوتاه‌ترین زمان‌ها مسافت را طی کند و از مدافعان عبور کند.</h5>
                <h5 className='asas'><span style={{ color: "orange" }}>شوت (Shot):</span> مهارت در شوت زنی، شانس گلزنی تیم را بالا می‌برد و تاثیرگذار در نتیجه بازی است.</h5>
                <h5 className='asas'><span style={{ color: "orange" }}>پاس (Pass):</span> توانایی پاس‌های دقیق و حساب شده، کلید موفقیت در تاکتیک‌های تیمی است.</h5>
                <h5 className='asas'><span style={{ color: "orange" }}>دفاع (Defense):</span> این بازیکن در گرفتن توپ از حریفان بسیار موفق بوده و نقش دفاعی مهمی دارد.</h5>
                <h5 className='asas'><span style={{ color: "orange" }}>دریبل (Dribble):</span> مهارت در دریبل زنی به بازیکن اجازه می‌دهد حریف را فریب دهد و موقعیت بهتری بسازد.</h5>
                <h5 className='asas'><span style={{ color: "orange" }}>قدرت (Physical):</span> این بازیکن می‌تواند ضربات محکم و پرقدرتی به توپ وارد کند که باعث ناامیدی مدافعان می‌شود.</h5>
                <h5 className='asas'><span style={{ color: "orange" }}>استقامت (Stamina):</span> توانایی بازیکن در ادامه دادن تلاش در طول بازی و جلوگیری از خستگی.</h5>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Tamrin;