import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { paymentService } from '../services/payment';

const PaymentCallback = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const [paymentStatus, setPaymentStatus] = useState('loading');
  const [paymentData, setPaymentData] = useState(null);

  useEffect(() => {
    const authority = searchParams.get('Authority');
    const status = searchParams.get('Status');

    if (!authority) {
      setPaymentStatus('error');
      return;
    }

    verifyPayment(authority, status);
  }, [searchParams]);

  const verifyPayment = async (authority, status) => {
    try {
      // در واقعیت این باید در بک‌اند انجام شود
      // اینجا فقط شبیه‌سازی می‌کنیم
      
      if (status === 'OK') {
        // پرداخت موفق
        setPaymentStatus('success');
        setPaymentData({
          refId: Math.random().toString(36).substr(2, 9).toUpperCase(),
          amount: 10000, // از authority می‌توان مقدار واقعی را گرفت
          package: { description: "۱۰,۰۰۰ سکه" }
        });
        
        // آپدیت موجودی کاربر
        setTimeout(() => {
          // اینجا می‌توانید موجودی کاربر را آپدیت کنید
          console.log('موجودی کاربر آپدیت شد');
        }, 2000);
      } else {
        // پرداخت ناموفق
        setPaymentStatus('failed');
      }
    } catch (error) {
      console.error('Verification error:', error);
      setPaymentStatus('error');
    }
  };

  const handleBackToShop = () => {
    navigate('/shop');
  };

  const handleViewTransactions = () => {
    navigate('/transactions');
  };

  // کامپوننت PaymentStatus که قبلا جدا بود، حالا اینجا تعریف می‌شود
  const PaymentStatus = ({ status, data, onBackToShop, onViewTransactions }) => {
    const statusConfig = {
      loading: {
        icon: '🔄',
        title: 'در حال بررسی پرداخت...',
        message: 'لطفا چند لحظه صبر کنید',
        color: '#ffc107',
        showButtons: false
      },
      success: {
        icon: '✅',
        title: 'پرداخت موفق',
        message: `پرداخت شما با موفقیت انجام شد`,
        color: '#28a745',
        showButtons: true
      },
      failed: {
        icon: '❌',
        title: 'پرداخت ناموفق',
        message: 'پرداخت انجام نشد. لطفا مجددا تلاش کنید.',
        color: '#dc3545',
        showButtons: true
      },
      error: {
        icon: '⚠️',
        title: 'خطا در پرداخت',
        message: 'خطایی در پرداخت رخ داده است.',
        color: '#fd7e14',
        showButtons: true
      }
    };

    const config = statusConfig[status] || statusConfig.error;

    return (
      <div style={{
        maxWidth: '500px',
        margin: '2rem auto',
        padding: '2rem',
        textAlign: 'center',
        backgroundColor: 'white',
        borderRadius: '12px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)',
        border: `2px solid ${config.color}`
      }}>
        <div style={{
          fontSize: '4rem',
          marginBottom: '1rem'
        }}>
          {config.icon}
        </div>
        
        <h1 style={{
          color: config.color,
          marginBottom: '1rem',
          fontSize: '1.8rem'
        }}>
          {config.title}
        </h1>
        
        <p style={{
          fontSize: '1.1rem',
          marginBottom: '1.5rem',
          color: '#666',
          lineHeight: '1.6'
        }}>
          {config.message}
        </p>

        {status === 'success' && data && (
          <div style={{
            backgroundColor: '#f8f9fa',
            padding: '1rem',
            borderRadius: '8px',
            marginBottom: '1.5rem',
            textAlign: 'right',
            direction: 'rtl'
          }}>
            <p style={{ margin: '0.5rem 0' }}>
              <strong>شناسه پرداخت:</strong> {data.refId}
            </p>
            <p style={{ margin: '0.5rem 0' }}>
              <strong>مبلغ:</strong> {data.amount.toLocaleString()} تومان
            </p>
            <p style={{ margin: '0.5rem 0' }}>
              <strong>پکیج:</strong> {data.package.description}
            </p>
          </div>
        )}

        {config.showButtons && (
          <div style={{
            display: 'flex',
            gap: '1rem',
            justifyContent: 'center',
            flexWrap: 'wrap'
          }}>
            <button
              onClick={onBackToShop}
              style={{
                padding: '0.75rem 1.5rem',
                backgroundColor: '#007bff',
                color: 'white',
                border: 'none',
                borderRadius: '6px',
                cursor: 'pointer',
                fontSize: '1rem',
                minWidth: '150px'
              }}
            >
              بازگشت به فروشگاه
            </button>
            
            {status === 'success' && (
              <button
                onClick={onViewTransactions}
                style={{
                  padding: '0.75rem 1.5rem',
                  backgroundColor: '#28a745',
                  color: 'white',
                  border: 'none',
                  borderRadius: '6px',
                  cursor: 'pointer',
                  fontSize: '1rem',
                  minWidth: '150px'
                }}
              >
                مشاهده تراکنش‌ها
              </button>
            )}
          </div>
        )}

        {status === 'loading' && (
          <div style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: '0.5rem',
            color: '#666'
          }}>
            <div className="loading-spinner" style={{
              width: '20px',
              height: '20px',
              border: '2px solid #f3f3f3',
              borderTop: '2px solid #007bff',
              borderRadius: '50%',
              animation: 'spin 1s linear infinite'
            }}></div>
            در حال بررسی...
          </div>
        )}
      </div>
    );
  };

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: '#f8f9fa',
      padding: '1rem',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center'
    }}>
      <PaymentStatus
        status={paymentStatus}
        data={paymentData}
        onBackToShop={handleBackToShop}
        onViewTransactions={handleViewTransactions}
      />
    </div>
  );
};

export default PaymentCallback;