import api from './api';

export const formationService = {
  // دریافت ترکیب فعلی
  getCurrentFormation: async () => {
    const response = await api.get('/formation/current');
    return response.data;
  },

  // ذخیره ترکیب
  saveFormation: async (formationData) => {
    const response = await api.post('/formation/save', formationData);
    return response.data;
  },

  // دریافت ترکیب‌های ذخیره شده
  getSavedFormations: async () => {
    const response = await api.get('/formation/saved');
    return response.data;
  },

  // حذف ترکیب
  deleteFormation: async (formationId) => {
    const response = await api.delete(`/formation/${formationId}`);
    return response.data;
  },

  // اعمال ترکیب به بازی
  applyFormation: async (formationId) => {
    const response = await api.post(`/formation/apply/${formationId}`);
    return response.data;
  }
};



