import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/coatch.css';
import '../styles/about.css'
import '../styles/Profile1.css'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments, FaBars, FaSave, FaEdit } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import { userService } from '../services/userService';
import { facilityService } from '../services/facilityService';

function Profile() {
  const navigate = useNavigate();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(false);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState('');
  const [profile, setProfile] = useState({
    username: '',
    email: '',
    profile: {
      firstName: '',
      lastName: '',
      bio: '',
      avatar: ''
    },
    coins: 0,
    role: 'user'
  });
  const [facilities, setFacilities] = useState(null);

  useEffect(() => {
    loadProfile();
  }, []);

  const loadProfile = async () => {
    try {
      setLoading(true);
      const [profileRes, facilitiesRes] = await Promise.all([
        userService.getProfile(),
        facilityService.getFacilities().catch(() => null)
      ]);

      if (profileRes) {
        setProfile(profileRes);
      }

      if (facilitiesRes?.success) {
        setFacilities(facilitiesRes.facilities);
      }
    } catch (error) {
      console.error('Error loading profile:', error);
      setMessage('خطا در بارگذاری پروفایل');
    } finally {
      setLoading(false);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    if (name.startsWith('profile.')) {
      const field = name.split('.')[1];
      setProfile(prev => ({
        ...prev,
        profile: {
          ...prev.profile,
          [field]: value
        }
      }));
    } else {
      setProfile(prev => ({
        ...prev,
        [name]: value
      }));
    }
  };

  const handleAvatarUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    try {
      setSaving(true);
      const response = await userService.uploadAvatar(file);
      if (response.avatar) {
        setProfile(prev => ({
          ...prev,
          profile: {
            ...prev.profile,
            avatar: response.avatar
          }
        }));
        setMessage('✅ آواتار با موفقیت آپلود شد');
      }
    } catch (error) {
      setMessage('خطا در آپلود آواتار');
    } finally {
      setSaving(false);
    }
  };

  const handleSave = async () => {
    try {
      setSaving(true);
      setMessage('');
      await userService.updateProfile({
        firstName: profile.profile.firstName,
        lastName: profile.profile.lastName,
        bio: profile.profile.bio
      });
      setMessage('✅ پروفایل با موفقیت به‌روزرسانی شد');
      setEditing(false);
    } catch (error) {
      setMessage('خطا در به‌روزرسانی پروفایل');
    } finally {
      setSaving(false);
    }
  };

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
        <div className={`kenar ${sidebarOpen ? 'active' : ''}`}>
          <Link to="/"><FaHome /> صفحه اصلی</Link>
          <Link to="/Profile"><FaUser /> پروفایل مربی</Link>
          <Link to="/Liga"><FaChartBar /> لیگ‌های من</Link>
          <Link to="/Tamrin"><FaClipboardList /> تمرین و تاکتیک</Link>
          <Link to="/Camp"><FaDumbbell /> کمپ تمرینی</Link>
          <Link to="/Player"><FaUsers /> بازیکنان</Link>
          <Link to="/Morabi"><FaChalkboardTeacher /> مربی</Link>
          <Link to="/Shop"><FaShoppingCart /> فروشگاه</Link>
          <Link to="/Poshtibani"><FaComments /> پشتیبانی</Link>
        </div>

        <div className="main1">
          <div className="slam">
            <div className="left">
              <div className='col1'> <span>نام تیم: {profile.username}</span></div>
              <div className='col2'> <img src={Image200} alt="سکه"/> <span> {profile.coins?.toLocaleString() || 0}</span></div>
              <div className='col3'> <img src={cashImage} alt="پول" /> <span> 47 اسکناس</span> </div>
              <div className='col4'> <img src={Image300} alt="آمار"/> <span> آمار</span></div>
              <div className='col5'>  <img src={Image400} alt="ثبت‌نام"/>  <span> ثبت‌نام در کاپ حذف</span></div>
            </div>

            <div className="right" style={{ direction: "rtl", textAlign: "center" }}>
              {/* آیکون‌های پیام و تنظیمات */}
            </div>
            <button className="menu-toggle" onClick={toggleSidebar}>
              <FaBars />
            </button>
          </div>

          {message && (
            <div style={{ 
              padding: '1rem', 
              margin: '1rem', 
              backgroundColor: message.includes('✅') ? '#d4edda' : '#f8d7da',
              color: message.includes('✅') ? '#155724' : '#721c24',
              borderRadius: '4px',
              textAlign: 'center'
            }}>
              {message}
            </div>
          )}

          <div className="card92">
            <div style={{ padding: '2rem', direction: 'rtl' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '2rem' }}>
                <h2>پروفایل کاربری</h2>
                {!editing ? (
                  <button
                    onClick={() => setEditing(true)}
                    style={{
                      padding: '0.5rem 1rem',
                      backgroundColor: '#007bff',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      gap: '0.5rem'
                    }}
                  >
                    <FaEdit /> ویرایش
                  </button>
                ) : (
                  <div style={{ display: 'flex', gap: '0.5rem' }}>
                    <button
                      onClick={handleSave}
                      disabled={saving}
                      style={{
                        padding: '0.5rem 1rem',
                        backgroundColor: saving ? '#ccc' : '#28a745',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: saving ? 'not-allowed' : 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '0.5rem'
                      }}
                    >
                      <FaSave /> {saving ? 'در حال ذخیره...' : 'ذخیره'}
                    </button>
                    <button
                      onClick={() => {
                        setEditing(false);
                        loadProfile();
                      }}
                      style={{
                        padding: '0.5rem 1rem',
                        backgroundColor: '#6c757d',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer'
                      }}
                    >
                      انصراف
                    </button>
                  </div>
                )}
              </div>

              <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '2rem' }}>
                {/* آواتار */}
                <div>
                  <div style={{ textAlign: 'center', marginBottom: '1rem' }}>
                    {profile.profile?.avatar ? (
                      <img 
                        src={`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}${profile.profile.avatar}`}
                        alt="آواتار"
                        style={{ width: '150px', height: '150px', borderRadius: '50%', objectFit: 'cover' }}
                      />
                    ) : (
                      <div style={{ 
                        width: '150px', 
                        height: '150px', 
                        borderRadius: '50%', 
                        backgroundColor: '#ddd',
                        display: 'flex',
                        alignItems: 'center',
                        justifyContent: 'center',
                        margin: '0 auto'
                      }}>
                        <FaUser size={60} />
                      </div>
                    )}
                  </div>
                  {editing && (
                    <input
                      type="file"
                      accept="image/*"
                      onChange={handleAvatarUpload}
                      style={{ width: '100%' }}
                    />
                  )}
                </div>

                {/* اطلاعات */}
                <div>
                  <div style={{ marginBottom: '1rem' }}>
                    <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
                      نام کاربری
                    </label>
                    <input
                      type="text"
                      value={profile.username || ''}
                      disabled
                      style={{
                        width: '100%',
                        padding: '0.5rem',
                        border: '1px solid #ddd',
                        borderRadius: '4px'
                      }}
                    />
                  </div>

                  <div style={{ marginBottom: '1rem' }}>
                    <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
                      ایمیل
                    </label>
                    <input
                      type="email"
                      value={profile.email || ''}
                      disabled
                      style={{
                        width: '100%',
                        padding: '0.5rem',
                        border: '1px solid #ddd',
                        borderRadius: '4px'
                      }}
                    />
                  </div>

                  <div style={{ marginBottom: '1rem' }}>
                    <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
                      نام
                    </label>
                    <input
                      type="text"
                      name="profile.firstName"
                      value={profile.profile?.firstName || ''}
                      onChange={handleInputChange}
                      disabled={!editing}
                      style={{
                        width: '100%',
                        padding: '0.5rem',
                        border: '1px solid #ddd',
                        borderRadius: '4px',
                        backgroundColor: editing ? 'white' : '#f5f5f5'
                      }}
                    />
                  </div>

                  <div style={{ marginBottom: '1rem' }}>
                    <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
                      نام خانوادگی
                    </label>
                    <input
                      type="text"
                      name="profile.lastName"
                      value={profile.profile?.lastName || ''}
                      onChange={handleInputChange}
                      disabled={!editing}
                      style={{
                        width: '100%',
                        padding: '0.5rem',
                        border: '1px solid #ddd',
                        borderRadius: '4px',
                        backgroundColor: editing ? 'white' : '#f5f5f5'
                      }}
                    />
                  </div>

                  <div style={{ marginBottom: '1rem' }}>
                    <label style={{ display: 'block', marginBottom: '0.5rem', fontWeight: 'bold' }}>
                      بیوگرافی
                    </label>
                    <textarea
                      name="profile.bio"
                      value={profile.profile?.bio || ''}
                      onChange={handleInputChange}
                      disabled={!editing}
                      rows="4"
                      style={{
                        width: '100%',
                        padding: '0.5rem',
                        border: '1px solid #ddd',
                        borderRadius: '4px',
                        backgroundColor: editing ? 'white' : '#f5f5f5'
                      }}
                    />
                  </div>

                  {facilities && (
                    <div style={{ marginTop: '2rem', padding: '1rem', backgroundColor: '#f8f9fa', borderRadius: '4px' }}>
                      <h4>وضعیت امکانات</h4>
                      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '1rem', marginTop: '1rem' }}>
                        {Object.entries(facilities).map(([key, facility]) => (
                          <div key={key} style={{ padding: '0.5rem', backgroundColor: 'white', borderRadius: '4px' }}>
                            <strong>{key}:</strong> سطح {facility.level}
                          </div>
                        ))}
                      </div>
                    </div>
                  )}
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Profile;
