import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import TeamSetupWizard from '../compoenents/TeamSetupWizard';

const TeamSetupWizardPage = () => {
  const navigate = useNavigate();
  const [submitting, setSubmitting] = useState(false);

  const handleWizardSubmit = async (data) => {
    try {
      setSubmitting(true);
      
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const token = localStorage.getItem('token');
      const storedUser = JSON.parse(localStorage.getItem('user') || '{}');

      // تبدیل بازیکنان انتخابی به فرمتی که سرور انتظار دارد
      const selectedPlayers = data.players.map((p, index) => ({
        name: p.name,
        age: p.age,
        overall: p.overall,
        position: p.position,
        skills: p.skills,
        contract: {
          expiresAt: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000),
          originalCost: 0,
          isBasePlayer: true
        },
        isInjured: false,
        injuryEndTime: null
      }));

      const response = await fetch(`${apiUrl}/api/team/create`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify({
          userId: storedUser._id || storedUser.id,
          teamName: data.team.name,
          teamCity: data.team.country,
          league: 'لیگ محلات دسته ۳',
          formation: data.team.formation,
          playStyle: data.team.playStyle,
          primaryColor: data.team.colors.primary,
          secondaryColor: data.team.colors.secondary,
          players: selectedPlayers
        })
      });

      const result = await response.json();

      if (!response.ok) {
        throw new Error(result.message || 'خطا در ثبت تیم');
      }

      // بروزرسانی اطلاعات کاربر در localStorage
      const updatedUser = { 
        ...storedUser, 
        ...result.user,
        teamName: result.user.teamName || data.team.name,
        teamCity: result.user.teamCity || data.team.country,
        league: result.user.league || { currentLeague: 'لیگ محلات دسته ۳' },
        formation: data.team.formation,
        playStyle: data.team.playStyle,
        teamColors: {
          primary: data.team.colors.primary,
          secondary: data.team.colors.secondary
        }
      };

      localStorage.setItem('user', JSON.stringify(updatedUser));
      
      alert('✅ تیم شما با موفقیت ایجاد شد!');
      navigate('/CoachProfile2');

    } catch (error) {
      console.error('Wizard submit error:', error);
      alert('❌ خطا در ثبت‌نام: ' + error.message);
      setSubmitting(false);
    }
  };

  return (
    <TeamSetupWizard onSubmit={handleWizardSubmit} />
  );
};

export default TeamSetupWizardPage;
