import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import '../images/استادیوم.jpg'
import '../styles/morabi.css'
import image1 from "../images/agent.png"
import image2 from "../images/nurse.png"
import image3 from "../images/messenger.png"
import image4 from "../images/raster.png"
import image5 from "../43dTsdAd06GgymszsvqoLmJI6UVlw6wJle33K3kI (1)/فیروز-کریمی.png"
import image6 from "../images/تخته تاکتیک.jpg"
import image7 from "../images/تمرینی.png"
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { userService } from '../services/userService';
import SlamHeader from '../compoenents/SlamHeader';
import Sidebar from '../compoenents/Sidebar';
import "../styles/risponsive.css"
import "../styles/coatch.css"
function Morabi() {
  const [loading, setLoading] = useState(true);
  const [userData, setUserData] = useState({
    coins: 0,
    teamName: 'سی تی'
  });
  const [coachData, setCoachData] = useState({
    name: 'مربی تیم',
    quality: 1,
    contract: {
      expiresAt: null
    }
  });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const profileRes = await userService.getProfile().catch(() => null);
      if (profileRes) {
        setUserData({
          coins: profileRes.coins || 0,
          teamName: profileRes.username || 'سی تی'
        });
        
        // بارگذاری اطلاعات مربی از user.coach
        if (profileRes.coach) {
          setCoachData({
            name: profileRes.coach.name || 'مربی تیم',
            quality: profileRes.coach.quality || 1,
            contract: profileRes.coach.contract || { expiresAt: null }
          });
        }
      }
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
    <Sidebar/>
        <div className="main1">
       <SlamHeader/>

          <div className="card29">
            <div className="profile-grid1">
              <ul className="features-list1">
                <div className='saddd'>
                  <img src={image1} alt="نام"/>
                  <li>👤 نام <strong>{coachData.name || 'مربی تیم'}</strong></li>
                </div>
                <div className='saddd'>
                  <img src={image2} alt="کیفیت"/>
                  <li>⭐ کیفیت مربی: <strong>سطح {coachData.quality || 1}</strong></li>
                </div>
                <div className='saddd'>
                  <img src={image3} alt="قرارداد"/>
                  <li>📅 انقضای قرارداد: <strong>{coachData.contract?.expiresAt ? new Date(coachData.contract.expiresAt).toLocaleDateString('fa-IR') : 'نامشخص'}</strong></li>
                </div>
                <div className='saddd'>
                  <img src={image4} alt="هزینه"/>
                  <li>💰 هزینه خرید: <strong>{coachData.contract?.originalCost || 0} سکه</strong></li>
                </div>
              </ul>

              <div className="center-section1">
                <div className='text2'>
                  <div className="underbox1">
                    <h4>مدت زمان قرارداد:</h4>
                    <div className="contract-box">
                      🕒 قرارداد: دائمی | تمدید: ثبت شده
                    </div>
                  </div>
                  <div className="underbox1">
                    <h4>تمدید قرارداد</h4>
                    <div className="contract-box">
                      🕒 قرارداد: دائمی | تمدید: ثبت شده
                    </div>
                  </div>
                </div>
              </div>

              <div className='ssccx'>
                <div className='eded2'>
                  <img className="equipment-img" src={image7} alt="تجهیزات تمرین" />
                </div>
                <div className='eded2'>
                  <img className="equipment-img" src={image6} alt="تخته تاکتیک" />
                </div>
              </div>

              <div className="note1">
                <p>تمرین اختصاصی: برای افزایش ویژگی‌های خاص بازیکن استفاده می‌شود.</p>
                <p>تمرین گروهی: ویژگی‌هایی به گروه بازیکنان اضافه می‌کند.</p>
                <p>تاکتیک و ترکیب: امکان تنظیم ترکیب و چینش تیم فراهم می‌شود.</p>
              </div>
            </div>

            <div className="coach-photo1">
              <img className="equipment-img" src={image5} alt="مربی" />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Morabi;
