import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import '../styles/coatch.css';
import '../images/استادیوم.jpg'
import '../styles/Amar.css'

import Image1 from '../images/98.png'
import Image2 from '../images/pngimg.com - coin_PNG36871.png';
import Image3 from '../images/pie-chart.png';
import Image4 from '../images/private-account.png';
import image5 from '../images/PikPng.com_football-player-clipart-png_1108985.png'
import image6 from '../images/ezgif-8f764386802cd0.png'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image100 from '../images/98.png'
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import SlamHeader from '../compoenents/SlamHeader';
import Sidebar from '../compoenents/Sidebar';
import "../styles/risponsive.css"
import api from '../services/api';

function Amar() {
  const [loading, setLoading] = useState(true);
  const [teamRankings, setTeamRankings] = useState([]);
  const [playerRankings, setPlayerRankings] = useState([]);
  const [countdown, setCountdown] = useState({ days: 0, hours: 0, minutes: 0, seconds: 0 });
  const [rewards, setRewards] = useState({ teams: [], players: [] });
  const [distributing, setDistributing] = useState(false);

  useEffect(() => {
    loadRankings();
    const interval = setInterval(() => {
      updateCountdown();
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  const loadRankings = async () => {
    try {
      setLoading(true);
      const [teamsRes, playersRes, rewardsRes] = await Promise.all([
        api.get('/team/rankings/teams').catch(() => ({ data: { rankings: [] } })),
        api.get('/team/rankings/players').catch(() => ({ data: { rankings: [] } })),
        api.get('/team/rewards/monthly').catch(() => ({ data: { countdown: {}, rewards: { teams: [], players: [] } } }))
      ]);

      if (teamsRes.data?.rankings) {
        setTeamRankings(teamsRes.data.rankings);
      }

      if (playersRes.data?.rankings) {
        setPlayerRankings(playersRes.data.rankings);
      }

      if (rewardsRes.data?.countdown) {
        setCountdown(rewardsRes.data.countdown);
      }

      if (rewardsRes.data?.rewards) {
        setRewards(rewardsRes.data.rewards);
      }
    } catch (error) {
      console.error('Error loading rankings:', error);
    } finally {
      setLoading(false);
    }
  };

  const updateCountdown = () => {
    const now = new Date();
    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
    const diff = endOfMonth - now;

    const days = Math.floor(diff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((diff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
    const minutes = Math.floor((diff % (1000 * 60 * 60)) / (1000 * 60));
    const seconds = Math.floor((diff % (1000 * 60)) / 1000);

    setCountdown({ days, hours, minutes, seconds });
  };

  const handleDistributeRewards = async () => {
    if (!window.confirm('آیا مطمئن هستید که می‌خواهید جوایز را اهدا کنید؟')) {
      return;
    }

    try {
      setDistributing(true);
      const res = await api.post('/team/rewards/distribute');
      if (res.data.success) {
        alert(`✅ ${res.data.message}`);
        loadRankings();
      }
    } catch (error) {
      alert(`❌ ${error.response?.data?.message || 'خطا در اهدای جوایز'}`);
    } finally {
      setDistributing(false);
    }
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <Sidebar />
          <div className="main12">
            <SlamHeader />
            <div className="card22" style={{ textAlign: 'center', padding: '2rem' }}>
              <p>در حال بارگذاری...</p>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar />
        <div className="main12">
          <SlamHeader />
          <div className="card22">
            {/* جدول تیم‌های قدرتمند - سمت راست */}
            <div className='dsfa'>
              <img src={image5} alt="پرچم‌ها" />
              <h2>قدرتمند ترین تیم ها</h2>
              <div className="table">
                <table>
                  <thead>
                    <tr>
                      <th>رتبه</th>
                      <th>نام تیم</th>
                      <th>قدرت تیم</th>
                      <th>قهرمانی</th>
                    </tr>
                  </thead>
                  <tbody>
                    {teamRankings.length > 0 ? (
                      teamRankings.map((team) => (
                        <tr key={team.rank}>
                          <td>{team.rank}</td>
                          <td>{team.teamName}</td>
                          <td>{team.teamPower}</td>
                          <td>{team.championships || 0}</td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan="4" style={{ textAlign: 'center', color: '#999' }}>
                          هنوز تیمی ثبت نشده است
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>

            {/* جوایز ماهانه - وسط */}
            <div className='sada'>
              <img src={image6} alt="هدیه‌ها" />
              <h1>جوایز ماهانه فوتبال</h1>

              <div style={{ textAlign: 'center', fontFamily: 'Arial, sans-serif', marginBottom: '70px' }}>
                <div style={{ display: 'flex', fontSize: '20px', fontWeight: 'bold', color: '#fff', gap: '20px', justifyContent: 'center' }}>
                  <div>{String(countdown.days).padStart(2, '0')}:</div>
                  <div>{String(countdown.hours).padStart(2, '0')}:</div>
                  <div>{String(countdown.minutes).padStart(2, '0')}:</div>
                  <div>{String(countdown.seconds).padStart(2, '0')}:</div>
                </div>
                <div style={{ display: 'flex', justifyContent: 'center', gap: '15px', color: '#fff', marginTop: '2px' }}>
                  <div>روز</div>
                  <div>ساعت</div>
                  <div>دقیقه</div>
                  <div>ثانیه</div>
                </div>
              </div>

              <div className='lkjk'>
                <div className='adfsd'>
                  <div className="rewards">
                    <div className='ssdez'>
                      <h3>بهترین تیم‌ها</h3>
                    </div>
                    {rewards.teams.length > 0 ? (
                      rewards.teams.map((reward, idx) => (
                        <div className="reward-item" key={idx}>
                          <img src={Image2} alt="سکه" style={{ width: '20px', height: '20px' }} />
                          <h6>{reward.coins?.toLocaleString()}</h6>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px' }} />
                          <h6>{reward.banknotes}</h6>
                          <h4>رتبه {idx + 1}:</h4>
                        </div>
                      ))
                    ) : (
                      <>
                        <div className="reward-item">
                          <img src={Image2} alt="سکه" style={{ width: '20px', height: '20px' }} />
                          <h6>3000000</h6>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px' }} />
                          <h6>100</h6>
                          <h4>رتبه اول:</h4>
                        </div>
                        <div className="reward-item">
                          <img src={Image2} alt="سکه" style={{ width: '20px', height: '20px' }} />
                          <h6>2000000</h6>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px' }} />
                          <h6>70</h6>
                          <h4>رتبه دوم:</h4>
                        </div>
                        <div className="reward-item">
                          <img src={Image2} alt="سکه" style={{ width: '20px', height: '20px' }} />
                          <h6>1000000</h6>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px' }} />
                          <h6>50</h6>
                          <h4>رتبه سوم:</h4>
                        </div>
                      </>
                    )}
                  </div>
                </div>

                <div className='adfsd'>
                  <div className="rewards">
                    <div className='ssdez'>
                      <h3>بهترین بازیکن‌ها</h3>
                    </div>
                    {rewards.players.length > 0 ? (
                      rewards.players.map((reward, idx) => (
                        <div className="reward-item" key={idx}>
                          <img src={Image2} alt="سکه" style={{ width: '20px', height: '20px' }} />
                          <h6>{reward.coins?.toLocaleString()}</h6>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px' }} />
                          <h6>{reward.banknotes}</h6>
                          <h4>رتبه {idx + 1}:</h4>
                        </div>
                      ))
                    ) : (
                      <>
                        <div className="reward-item">
                          <img src={Image2} alt="سکه" style={{ width: '20px', height: '20px' }} />
                          <h6>3000000</h6>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px' }} />
                          <h6>100</h6>
                          <h4>رتبه اول:</h4>
                        </div>
                        <div className="reward-item">
                          <img src={Image2} alt="سکه" style={{ width: '20px', height: '20px' }} />
                          <h6>2000000</h6>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px' }} />
                          <h6>70</h6>
                          <h4>رتبه دوم:</h4>
                        </div>
                        <div className="reward-item">
                          <img src={Image2} alt="سکه" style={{ width: '20px', height: '20px' }} />
                          <h6>1000000</h6>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px' }} />
                          <h6>50</h6>
                          <h4>رتبه سوم:</h4>
                        </div>
                      </>
                    )}
                  </div>
                </div>
              </div>

              <button
                onClick={handleDistributeRewards}
                disabled={distributing}
                style={{
                  marginTop: '20px',
                  padding: '10px 20px',
                  backgroundColor: distributing ? '#ccc' : '#28a745',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: distributing ? 'not-allowed' : 'pointer',
                  fontSize: '16px',
                  fontWeight: 'bold'
                }}
              >
                {distributing ? 'در حال اهدای جوایز...' : '🎁 اهدای جوایز ماهانه'}
              </button>
            </div>

            {/* جدول بازیکنان قدرتمند - سمت چپ */}
            <div className='dsfa'>
              <img src={image5} alt="پرچم‌ها" />
              <h2>قدرتمند ترین بازیکن‌ها</h2>
              <div className="table">
                <table>
                  <thead>
                    <tr>
                      <th>رتبه</th>
                      <th>نام بازیکن</th>
                      <th>امتیاز (Overall)</th>
                      <th>تیم</th>
                    </tr>
                  </thead>
                  <tbody>
                    {playerRankings.length > 0 ? (
                      playerRankings.map((player) => (
                        <tr key={player.rank}>
                          <td>{player.rank}</td>
                          <td>{player.playerName}</td>
                          <td>{player.overall}</td>
                          <td>{player.teamName}</td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan="4" style={{ textAlign: 'center', color: '#999' }}>
                          هنوز بازیکنی ثبت نشده است
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Amar;
