import React, { useState, useEffect, useRef } from 'react';
import { Link } from 'react-router-dom';
import '../styles/coatch.css';
import '../styles/Tarkib.css';
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments, FaSave, FaUndo } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import image1 from '../images/ترکیب.png';
import image342 from '../43dTsdAd06GgymszsvqoLmJI6UVlw6wJle33K3kI (1)/فیروز-کریمی.png'
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { userService } from '../services/userService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import "../styles/risponsive.css"
import api from '../services/api';

const FORMATIONS = {
  '4-4-2': {
    name: '4-4-2',
    positions: [
      { id: 'GK', x: 50, y: 95, position: 'GK' },
      { id: 'LB', x: 20, y: 80, position: 'LB' },
      { id: 'CB1', x: 40, y: 80, position: 'CB' },
      { id: 'CB2', x: 60, y: 80, position: 'CB' },
      { id: 'RB', x: 80, y: 80, position: 'RB' },
      { id: 'LM', x: 20, y: 60, position: 'LM' },
      { id: 'CM1', x: 40, y: 60, position: 'CM' },
      { id: 'CM2', x: 60, y: 60, position: 'CM' },
      { id: 'RM', x: 80, y: 60, position: 'RM' },
      { id: 'ST1', x: 40, y: 30, position: 'ST' },
      { id: 'ST2', x: 60, y: 30, position: 'ST' }
    ]
  },
  '4-3-3': {
    name: '4-3-3',
    positions: [
      { id: 'GK', x: 50, y: 95, position: 'GK' },
      { id: 'LB', x: 20, y: 80, position: 'LB' },
      { id: 'CB1', x: 40, y: 80, position: 'CB' },
      { id: 'CB2', x: 60, y: 80, position: 'CB' },
      { id: 'RB', x: 80, y: 80, position: 'RB' },
      { id: 'CM1', x: 30, y: 60, position: 'CM' },
      { id: 'CM2', x: 50, y: 60, position: 'CM' },
      { id: 'CM3', x: 70, y: 60, position: 'CM' },
      { id: 'LW', x: 20, y: 30, position: 'LW' },
      { id: 'ST', x: 50, y: 25, position: 'ST' },
      { id: 'RW', x: 80, y: 30, position: 'RW' }
    ]
  },
  '3-5-2': {
    name: '3-5-2',
    positions: [
      { id: 'GK', x: 50, y: 95, position: 'GK' },
      { id: 'CB1', x: 30, y: 80, position: 'CB' },
      { id: 'CB2', x: 50, y: 80, position: 'CB' },
      { id: 'CB3', x: 70, y: 80, position: 'CB' },
      { id: 'LWB', x: 15, y: 60, position: 'LWB' },
      { id: 'CM1', x: 40, y: 60, position: 'CM' },
      { id: 'CM2', x: 50, y: 60, position: 'CM' },
      { id: 'CM3', x: 60, y: 60, position: 'CM' },
      { id: 'RWB', x: 85, y: 60, position: 'RWB' },
      { id: 'ST1', x: 40, y: 30, position: 'ST' },
      { id: 'ST2', x: 60, y: 30, position: 'ST' }
    ]
  },
  '4-2-3-1': {
    name: '4-2-3-1',
    positions: [
      { id: 'GK', x: 50, y: 95, position: 'GK' },
      { id: 'LB', x: 20, y: 80, position: 'LB' },
      { id: 'CB1', x: 40, y: 80, position: 'CB' },
      { id: 'CB2', x: 60, y: 80, position: 'CB' },
      { id: 'RB', x: 80, y: 80, position: 'RB' },
      { id: 'CDM1', x: 40, y: 70, position: 'CDM' },
      { id: 'CDM2', x: 60, y: 70, position: 'CDM' },
      { id: 'CAM', x: 50, y: 50, position: 'CAM' },
      { id: 'LW', x: 20, y: 40, position: 'LW' },
      { id: 'RW', x: 80, y: 40, position: 'RW' },
      { id: 'ST', x: 50, y: 25, position: 'ST' }
    ]
  }
};

function Tarkib() {
  const [loading, setLoading] = useState(true);
  const [userData, setUserData] = useState({
    coins: 0,
    banknotes: 0,
    teamName: 'تیم من',
    players: []
  });
  const [formation, setFormation] = useState('4-4-2');
  const [fieldPlayers, setFieldPlayers] = useState({});
  const [benchPlayers, setBenchPlayers] = useState([]);
  const [selectedPlayer, setSelectedPlayer] = useState(null);
  const [draggedPlayer, setDraggedPlayer] = useState(null);
  const [gameStyle, setGameStyle] = useState({
    passing: false,
    dribbling: false,
    counter_attack: false,
    possession: false
  });
  const [specialRoles, setSpecialRoles] = useState({
    captain: '',
    penalty_taker: '',
    free_kick_taker: '',
    corner_taker: ''
  });
  const [gameStates, setGameStates] = useState({
    base: { formation: '4-4-2', players: {} },
    leading: { formation: '4-4-2', players: {} },
    draw: { formation: '4-4-2', players: {} }
  });
  const [currentState, setCurrentState] = useState('base');
  const [injuredPlayers, setInjuredPlayers] = useState([]);
  const [suspendedPlayers, setSuspendedPlayers] = useState([]);
  const [substitutions, setSubstitutions] = useState([]);
  const [saving, setSaving] = useState(false);
  const [applying, setApplying] = useState(false);
  const [message, setMessage] = useState('');
  const [teamPowerInfo, setTeamPowerInfo] = useState({ teamPower: 0, basePower: 0, tacticBonus: 0 });
  const [subsUsed, setSubsUsed] = useState(0);
  const fieldRef = useRef(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const profileRes = await userService.getProfile().catch(() => null);
      if (profileRes) {
        setUserData({
          coins: profileRes.coins || 0,
          banknotes: profileRes.banknotes || 0,
          teamName: profileRes.teamName || profileRes.username || 'تیم من',
          players: profileRes.players || []
        });
        loadSavedFormation();
      }
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadSavedFormation = async () => {
    try {
      const response = await api.get('/formation/current').catch(() => null);
      if (response?.data) {
        const saved = response.data;
        setFormation(saved.formation || '4-4-2');
        setFieldPlayers(saved.players || {});
        setGameStyle(saved.gameStyle || gameStyle);
        setSpecialRoles(saved.specialRoles || specialRoles);
        setGameStates(saved.gameStates || gameStates);
        setSubsUsed(saved.substitutionsUsed || 0);
      }
      const powerRes = await api.get('/formation/team-power').catch(() => null);
      if (powerRes?.data) {
        setTeamPowerInfo(powerRes.data);
      }
    } catch (error) {
      console.error('Error loading formation:', error);
    }
  };

  const showMessage = (msg) => {
    setMessage(msg);
    setTimeout(() => setMessage(''), 3000);
  };

  const handleFormationChange = (newFormation) => {
    setFormation(newFormation);
    setFieldPlayers({});
    showMessage(`ترکیب ${newFormation} انتخاب شد`);
  };

  const handlePlayerDragStart = (player, fromBench = false) => {
    setDraggedPlayer({ player, fromBench });
  };

  const handlePlayerDrop = (positionId, position) => {
    if (!draggedPlayer) return;
    const { player, fromBench } = draggedPlayer;

    if (!isPositionCompatible(player.position, position)) {
      showMessage('⚠️ این بازیکن برای این پست مناسب نیست');
      return;
    }

    const newFieldPlayers = { ...fieldPlayers };
    Object.keys(newFieldPlayers).forEach(key => {
      if (newFieldPlayers[key]?._id === player._id) {
        delete newFieldPlayers[key];
      }
    });

    newFieldPlayers[positionId] = player;
    setFieldPlayers(newFieldPlayers);

    if (fromBench) {
      setBenchPlayers(prev => prev.filter(p => p._id !== player._id));
    }

    setDraggedPlayer(null);
    updateTeamPower();
  };

  const handleRemoveFromField = (positionId) => {
    const player = fieldPlayers[positionId];
    if (player) {
      const newFieldPlayers = { ...fieldPlayers };
      delete newFieldPlayers[positionId];
      setFieldPlayers(newFieldPlayers);
      setBenchPlayers(prev => [...prev, player]);
    }
  };

  const isPositionCompatible = (playerPosition, requiredPosition) => {
    const compatibility = {
      'GK': ['GK'],
      'CB': ['CB', 'LB', 'RB', 'LWB', 'RWB'],
      'LB': ['LB', 'LWB', 'CB', 'LM'],
      'RB': ['RB', 'RWB', 'CB', 'RM'],
      'LWB': ['LWB', 'LB', 'LM', 'CM'],
      'RWB': ['RWB', 'RB', 'RM', 'CM'],
      'CM': ['CM', 'CDM', 'CAM', 'LM', 'RM', 'LWB', 'RWB'],
      'CDM': ['CDM', 'CM', 'CB'],
      'CAM': ['CAM', 'CM', 'ST', 'LW', 'RW'],
      'LM': ['LM', 'LW', 'CM', 'LWB'],
      'RM': ['RM', 'RW', 'CM', 'RWB'],
      'LW': ['LW', 'LM', 'ST', 'CAM'],
      'RW': ['RW', 'RM', 'ST', 'CAM'],
      'ST': ['ST', 'LW', 'RW', 'CAM']
    };
    return compatibility[playerPosition]?.includes(requiredPosition) || false;
  };

  const updateTeamPower = async () => {
    try {
      const powerRes = await api.get('/formation/team-power').catch(() => null);
      if (powerRes?.data) {
        setTeamPowerInfo(powerRes.data);
      }
    } catch (error) {
      console.error('Error updating team power:', error);
    }
  };

  const handleSaveFormation = async () => {
    try {
      setSaving(true);
      const formationData = {
        formation,
        players: fieldPlayers,
        gameStyle,
        specialRoles,
        gameStates: {
          ...gameStates,
          [currentState]: { formation, players: fieldPlayers }
        }
      };

      const response = await api.post('/formation/save', formationData);
      if (response.data.success) {
        showMessage('✅ ترکیب با موفقیت ذخیره شد');
      }
    } catch (error) {
      showMessage('❌ خطا در ذخیره ترکیب');
    } finally {
      setSaving(false);
    }
  };

  const handleApplyFormation = async () => {
    const fieldCount = Object.keys(fieldPlayers).length;
    if (fieldCount < 11) {
      showMessage(`⚠️ حداقل ${11 - fieldCount} بازیکن دیگر نیاز دارید`);
      return;
    }

    try {
      setApplying(true);
      const response = await api.post('/formation/apply/current', {});
      if (response.data.success) {
        showMessage(`✅ ترکیب اعمال شد! قدرت تیم: ${response.data.teamPower}`);
        setTeamPowerInfo(response.data);
        loadData();
      }
    } catch (error) {
      showMessage(`❌ ${error.response?.data?.message || 'خطا در اعمال ترکیب'}`);
    } finally {
      setApplying(false);
    }
  };

  const handleAddSubstitution = (outPlayer, inPlayer) => {
    if (subsUsed >= 5) {
      showMessage('⚠️ حداکثر 5 تعویض مجاز است');
      return;
    }
    setSubstitutions(prev => [...prev, { out: outPlayer, in: inPlayer }]);
  };

  const getPositionName = (position) => {
    const names = {
      'GK': 'دروازه‌بان', 'CB': 'مدافع مرکزی', 'LB': 'مدافع چپ', 'RB': 'مدافع راست',
      'LWB': 'وینگ‌بک چپ', 'RWB': 'وینگ‌بک راست', 'CM': 'هافبک میانی',
      'CDM': 'هافبک دفاعی', 'CAM': 'هافبک هجومی', 'LM': 'هافبک چپ',
      'RM': 'هافبک راست', 'LW': 'وینگر چپ', 'RW': 'وینگر راست', 'ST': 'مهاجم'
    };
    return names[position] || position;
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  const currentFormation = FORMATIONS[formation];
  const availablePlayers = userData.players.filter(p =>
    !injuredPlayers.includes(p._id) && !suspendedPlayers.includes(p._id)
  );
  const fieldPlayerIds = Object.values(fieldPlayers).map(p => p._id);
  const bench = availablePlayers.filter(p => !fieldPlayerIds.includes(p._id));
  const fieldCount = Object.keys(fieldPlayers).length;

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        <div className="main1">
        <SlamHeader/>

          {message && (
            <div style={{
              padding: '1rem', margin: '1rem',
              backgroundColor: message.includes('✅') ? '#d4edda' : message.includes('⚠️') ? '#fff3cd' : '#f8d7da',
              color: message.includes('✅') ? '#155724' : message.includes('⚠️') ? '#856404' : '#721c24',
              borderRadius: '4px', textAlign: 'center'
            }}>
              {message}
            </div>
          )}

          <div className="cadrd23">
            <div className='bala1'>
              <div className="dov1">
                <p className="title">مصدومین و محرومین بازی بعدی</p>
                <div className="list">
                  <p>مصدومین: {injuredPlayers.length}</p>
                  <p>محرومین: {suspendedPlayers.length}</p>
                </div>
              </div>

              <div className='dov2'>
                <div className="swap-section">تعویض‌ها ({subsUsed}/5)</div>
                <div className="swap-container">
                  {[...Array(5)].map((_, idx) => (
                    <div key={idx} className="swap-item">
                      <select
                        className="select-field"
                        value={substitutions[idx]?.out?._id || ''}
                        onChange={(e) => {
                          const outPlayer = availablePlayers.find(p => p._id === e.target.value);
                          if (outPlayer) {
                            const newSubs = [...substitutions];
                            newSubs[idx] = { ...newSubs[idx], out: outPlayer };
                            setSubstitutions(newSubs);
                          }
                        }}
                      >
                        <option value="">خروج</option>
                        {Object.values(fieldPlayers).map(p => (
                          <option key={p._id} value={p._id}>{p.name} ({p.number})</option>
                        ))}
                      </select>
                      <span style={{ margin: '0 0.5rem' }}>→</span>
                      <select
                        className="select-field"
                        value={substitutions[idx]?.in?._id || ''}
                        onChange={(e) => {
                          const inPlayer = bench.find(p => p._id === e.target.value);
                          if (inPlayer && substitutions[idx]?.out) {
                            handleAddSubstitution(substitutions[idx].out, inPlayer);
                          }
                        }}
                      >
                        <option value="">ورود</option>
                        {bench.map(p => (
                          <option key={p._id} value={p._id}>{p.name} ({p.number})</option>
                        ))}
                      </select>
                    </div>
                  ))}
                  <div style={{ display: 'flex', gap: '10px', marginTop: '1rem' }}>
                    <button
                      className="save-btn"
                      onClick={handleSaveFormation}
                      disabled={saving}
                    >
                      <FaSave /> {saving ? 'در حال ذخیره...' : 'ذخیره ترکیب'}
                    </button>
                    <button
                      className="clear-btn"
                      onClick={() => {
                        setFieldPlayers({});
                        setSubstitutions([]);
                      }}
                    >
                      <FaUndo /> پاکسازی
                    </button>
                    <button
                      className="save-btn"
                      onClick={handleApplyFormation}
                      disabled={applying || fieldCount < 11}
                      style={{ backgroundColor: applying || fieldCount < 11 ? '#ccc' : '#17a2b8' }}
                    >
                      🚀 {applying ? 'در حال اعمال...' : 'اعمال ترکیب'}
                    </button>
                  </div>
                </div>
              </div>

              <div className="layout-container">
                <div className="status-panel">
                  <div className="status-item">
                    <h6>مصدوم</h6>
                    <span>بازیکن مصدوم در بازی بعدی همه قدرت‌هایش ۵۰ می‌شود</span>
                  </div>
                  <div className="status-item">
                    <h6>محروم</h6>
                    <span>بازیکن محروم نمی‌تواند در بازی بعدی شرکت کند</span>
                  </div>
                  <div className="status-item">
                    <h6>تعویض</h6>
                    <span>حداکثر 5 تعویض در هر بازی مجاز است</span>
                  </div>
                  <div className="status-item">
                    <h6>کاپیتان</h6>
                    <span>کاپیتان تیم را انتخاب کنید</span>
                  </div>
                  <div className="status-item">
                    <h6>پست بازیکن</h6>
                    <span>بازیکنان را در پست مناسب قرار دهید</span>
                  </div>
                  <div className="status-item">
                    <h6>قدرت بازیکن</h6>
                    <span>Overall: {selectedPlayer?.overall || '-'}</span>
                  </div>
                  <div className="status-item" style={{ borderTop: '1px solid #ddd', paddingTop: '8px', marginTop: '8px' }}>
                    <h6>قدرت تیم</h6>
                    <span style={{ color: '#28a745', fontWeight: 'bold', fontSize: '18px' }}>{teamPowerInfo.teamPower || userData.teamPower}</span>
                  </div>
                  <div className="status-item">
                    <h6>بونوس تاکتیک</h6>
                    <span style={{ color: '#007bff', fontWeight: 'bold' }}>+{teamPowerInfo.tacticBonus || 0}</span>
                  </div>
                </div>
                <img className='coach-image' src={image342} alt="مربی" />
              </div>
            </div>

            <div className='balsd'>
              <div className='aval1'>
                <div className="formation-options">
                  <h3>انتخاب ترکیب</h3>
                  <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                    {Object.keys(FORMATIONS).map(form => (
                      <button
                        key={form}
                        className={`formation-btn ${formation === form ? 'active' : ''}`}
                        onClick={() => handleFormationChange(form)}
                      >
                        {form}
                      </button>
                    ))}
                  </div>
                </div>

                <div className='dasak'>
                  <h4>انتخاب سبک بازی:</h4>
                  {Object.keys(gameStyle).map(style => (
                    <label key={style}>
                      <input
                        type="checkbox"
                        checked={gameStyle[style]}
                        onChange={(e) => setGameStyle(prev => ({
                          ...prev,
                          [style]: e.target.checked
                        }))}
                      />
                      {style === 'passing' ? 'پاسکاری' :
                       style === 'dribbling' ? 'دریبل‌زنی' :
                       style === 'counter_attack' ? 'ضدحمله' :
                       'حفظ توپ'}
                    </label>
                  ))}
                </div>

                <div className='qrw'>
                  <div className='fdsq'>
                    <label>کاپیتان تیم:</label>
                    <select
                      value={specialRoles.captain}
                      onChange={(e) => setSpecialRoles(prev => ({ ...prev, captain: e.target.value }))}
                    >
                      <option value="">انتخاب بازیکن</option>
                      {Object.values(fieldPlayers).map(p => (
                        <option key={p._id} value={p._id}>{p.number} - {p.name}</option>
                      ))}
                    </select>
                  </div>
                  <div className='fdsq'>
                    <label>فری‌کیک زن:</label>
                    <select
                      value={specialRoles.free_kick_taker}
                      onChange={(e) => setSpecialRoles(prev => ({ ...prev, free_kick_taker: e.target.value }))}
                    >
                      <option value="">انتخاب بازیکن</option>
                      {Object.values(fieldPlayers).map(p => (
                        <option key={p._id} value={p._id}>{p.number} - {p.name}</option>
                      ))}
                    </select>
                  </div>
                  <div className='fdsq'>
                    <label>کرنر زن:</label>
                    <select
                      value={specialRoles.corner_taker}
                      onChange={(e) => setSpecialRoles(prev => ({ ...prev, corner_taker: e.target.value }))}
                    >
                      <option value="">انتخاب بازیکن</option>
                      {Object.values(fieldPlayers).map(p => (
                        <option key={p._id} value={p._id}>{p.number} - {p.name}</option>
                      ))}
                    </select>
                  </div>
                  <div className='fdsq'>
                    <label>پنالتی زن:</label>
                    <select
                      value={specialRoles.penalty_taker}
                      onChange={(e) => setSpecialRoles(prev => ({ ...prev, penalty_taker: e.target.value }))}
                    >
                      <option value="">انتخاب بازیکن</option>
                      {Object.values(fieldPlayers).map(p => (
                        <option key={p._id} value={p._id}>{p.number} - {p.name}</option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="state-container">
                  <div className="state-group">
                    {['base', 'leading', 'draw'].map(state => (
                      <div
                        key={state}
                        className={`state-item ${currentState === state ? 'active' : ''}`}
                        onClick={() => {
                          setCurrentState(state);
                          if (gameStates[state]) {
                            setFormation(gameStates[state].formation || formation);
                            setFieldPlayers(gameStates[state].players || fieldPlayers);
                          }
                        }}
                      >
                        <h3>
                          {state === 'base' ? 'حالت پایه' :
                           state === 'leading' ? 'حالت جلو بودن' :
                           'حالت مساوی'}
                        </h3>
                      </div>
                    ))}
                  </div>
                </div>
              </div>

              <div className='aval2'>
                <div
                  ref={fieldRef}
                  style={{
                    width: '100%',
                    height: '600px',
                    position: 'relative',
                    borderRadius: '8px',
                    overflow: 'hidden',
                    backgroundColor: '#1a4d2a'
                  }}
                >
                  <img
                    src={image1}
                    alt="زمین فوتبال"
                    style={{
                      width: '100%',
                      height: '100%',
                      objectFit: 'cover',
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      pointerEvents: 'none'
                    }}
                  />

                  {currentFormation.positions.map(pos => {
                    const player = fieldPlayers[pos.id];
                    return (
                      <div
                        key={pos.id}
                        onDrop={(e) => {
                          e.preventDefault();
                          handlePlayerDrop(pos.id, pos.position);
                        }}
                        onDragOver={(e) => e.preventDefault()}
                        onClick={() => player && setSelectedPlayer(player)}
                        style={{
                          position: 'absolute',
                          left: `${pos.x}%`,
                          top: `${pos.y}%`,
                          transform: 'translate(-50%, -50%)',
                          width: '50px',
                          height: '50px',
                          borderRadius: '50%',
                          backgroundColor: player ? '#007bff' : 'rgba(255,255,255,0.3)',
                          border: '2px solid #fff',
                          display: 'flex',
                          flexDirection: 'column',
                          alignItems: 'center',
                          justifyContent: 'center',
                          cursor: 'pointer',
                          transition: 'all 0.3s',
                          fontSize: '10px',
                          color: '#fff',
                          fontWeight: 'bold',
                          zIndex: 10,
                          boxShadow: '0 2px 8px rgba(0,0,0,0.3)'
                        }}
                      >
                        {player ? (
                          <>
                            <div style={{ fontSize: '14px', fontWeight: 'bold' }}>{player.number}</div>
                            <div style={{ fontSize: '8px', marginTop: '2px', textAlign: 'center' }}>
                              {player.name?.split(' ')[0] || player.name}
                            </div>
                          </>
                        ) : (
                          <div style={{ fontSize: '9px', textAlign: 'center' }}>{getPositionName(pos.position)}</div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>

              <div className='aval3'>
                <div className='players-list'>
                  <h4>بازیکنان در زمین ({fieldCount}/11)</h4>
                  {Object.entries(fieldPlayers).map(([posId, player]) => {
                    const pos = currentFormation.positions.find(p => p.id === posId);
                    return (
                      <div
                        key={posId}
                        className='player-item'
                        draggable
                        onDragStart={() => handlePlayerDragStart(player, false)}
                        onClick={() => setSelectedPlayer(player)}
                      >
                        <span className='player-number'>{player.number}</span>
                        <span className='player-name'>{player.name}</span>
                        <span className='player-position'>{getPositionName(pos?.position || '')}</span>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            handleRemoveFromField(posId);
                          }}
                          style={{
                            padding: '2px 8px',
                            fontSize: '10px',
                            backgroundColor: '#dc3545',
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            cursor: 'pointer'
                          }}
                        >
                          حذف
                        </button>
                      </div>
                    );
                  })}
                </div>

                <div className='players-list' style={{ marginTop: '2rem' }}>
                  <h4>نیمکت ({bench.length})</h4>
                  {bench.map(player => (
                    <div
                      key={player._id}
                      className='player-item'
                      draggable
                      onDragStart={() => handlePlayerDragStart(player, true)}
                      onClick={() => setSelectedPlayer(player)}
                    >
                      <span className='player-number'>{player.number}</span>
                      <span className='player-name'>{player.name}</span>
                      <span className='player-position'>{getPositionName(player.position)}</span>
                      <span style={{ fontSize: '12px', color: '#28a745' }}>
                        OVR: {player.overall || 50}
                      </span>
                    </div>
                  ))}
                </div>

                {selectedPlayer && (
                  <div style={{
                    marginTop: '2rem',
                    padding: '1rem',
                    backgroundColor: '#f8f9fa',
                    borderRadius: '8px',
                    border: '2px solid #007bff'
                  }}>
                    <h4>اطلاعات بازیکن</h4>
                    <p><strong>نام:</strong> {selectedPlayer.name}</p>
                    <p><strong>شماره:</strong> {selectedPlayer.number}</p>
                    <p><strong>پست:</strong> {getPositionName(selectedPlayer.position)}</p>
                    <p><strong>Overall:</strong> {selectedPlayer.overall || 50}</p>
                    {selectedPlayer.skills && (
                      <div>
                        <p><strong>مهارت‌ها:</strong></p>
                        <ul>
                          {Object.entries(selectedPlayer.skills).map(([skill, value]) => (
                            <li key={skill}>{skill}: {value}</li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Tarkib;
