import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/coatch.css';
import '../styles/liga.css'
import Image1 from '../images/pngtree-champions-league-cup-football-trophy-realistic-vector-generative-ai-png-image_12336978.png'
import Image3 from '../images/تیک-سبز.png'
import Image4 from '../images/تیک-قرمز.png'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagees from '../images/esteghlal-min.jpg'
import imageprc from '../images/perspolis-min.jpg'
import imageFcb from '../images/FCB.svg.png'
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { userService } from '../services/userService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import "../styles/risponsive.css"
import api from '../services/api';

// اطلاعات لیگ‌ها
const LEAGUE_DATA = {
  'لیگ محلات دسته 3': { coins: 1000, banknotes: 0, name: 'لیگ محلات دسته ۳' },
  'لیگ محلات دسته 2': { coins: 3000, banknotes: 1, name: 'لیگ محلات دسته ۲' },
  'لیگ محلات دسته 1': { coins: 5000, banknotes: 2, name: 'لیگ محلات دسته ۱' },
  'لیگ استانی دسته 3': { coins: 7000, banknotes: 2, name: 'لیگ استانی دسته ۳' },
  'لیگ استانی دسته 2': { coins: 10000, banknotes: 3, name: 'لیگ استانی دسته ۲' },
  'لیگ استانی دسته 1': { coins: 15000, banknotes: 5, name: 'لیگ استانی دسته ۱' },
  'لیگ برتر دسته 3': { coins: 20000, banknotes: 7, name: 'لیگ برتر دسته ۳' },
  'لیگ برتر دسته 2': { coins: 30000, banknotes: 10, name: 'لیگ برتر دسته ۲' },
  'لیگ برتر دسته 1': { coins: 45000, banknotes: 15, name: 'لیگ برتر دسته ۱' },
  'لیگ ستارگان': { coins: 70000, banknotes: 25, name: 'لیگ ستارگان' }
};

function Liga() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [currentLeague, setCurrentLeague] = useState('لیگ محلات دسته 3');
  const [leagueRewards, setLeagueRewards] = useState(LEAGUE_DATA['لیگ محلات دسته 3']);
  const [userData, setUserData] = useState({
    coins: 0,
    banknotes: 0,
    teamName: 'تیم من',
    points: 0,
    goalsFor: 0,
    goalsAgainst: 0,
    matchesPlayed: 0
  });
  const [standings, setStandings] = useState([]);
  const [matches, setMatches] = useState([]);
  const [nextMatch, setNextMatch] = useState(null);
  const [lastMatch, setLastMatch] = useState(null);
  const [leagueInfo, setLeagueInfo] = useState({
    userRank: 0,
    totalTeams: 0,
    prizes: [],
    status: { registered: false, paid: false, matchPlayed: false, rewardsClaimed: false }
  });
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [showMatchDetail, setShowMatchDetail] = useState(false);
  const [simulating, setSimulating] = useState(false);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      let leagueName = 'لیگ محلات دسته 3';
      
      const profileRes = await userService.getProfile().catch(() => null);
      if (profileRes) {
        setUserData(prev => ({
          ...prev,
          coins: profileRes.coins ?? 0,
          banknotes: profileRes.banknotes ?? 0,
          teamName: profileRes.teamName || profileRes.username || 'تیم من',
          points: profileRes.league?.points || 0,
          goalsFor: profileRes.league?.goalsFor || 0,
          goalsAgainst: profileRes.league?.goalsAgainst || 0,
          matchesPlayed: profileRes.league?.matchesPlayed || 0
        }));
        leagueName = profileRes?.league?.currentLeague || 'لیگ محلات دسته 3';
      }
      
      setCurrentLeague(leagueName);
      const rewards = LEAGUE_DATA[leagueName] || LEAGUE_DATA['لیگ محلات دسته 3'];
      setLeagueRewards(rewards);

      // دریافت اطلاعات لیگ
      const infoRes = await api.get('/league/info').catch(() => null);
      if (infoRes?.data) {
        setLeagueInfo({
          userRank: infoRes.data.userRank || 0,
          totalTeams: infoRes.data.totalTeams || 0,
          prizes: infoRes.data.prizes || [],
          status: infoRes.data.status || {}
        });
      }

      // دریافت جدول
      const standRes = await api.get('/league/standings').catch(() => null);
      if (standRes?.data?.standings) {
        setStandings(standRes.data.standings);
      }

      // دریافت بازی‌ها
      const matchesRes = await api.get('/league/matches').catch(() => null);
      if (matchesRes?.data) {
        setNextMatch(matchesRes.data.nextMatch);
        setLastMatch(matchesRes.data.lastMatch);
        setMatches(matchesRes.data.finishedMatches || []);
      }
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleViewMatchDetail = async (match) => {
    try {
      const res = await api.get(`/league/match/${match._id}`).catch(() => null);
      if (res?.data?.match) {
        setSelectedMatch(res.data.match);
        setShowMatchDetail(true);
      }
    } catch (error) {
      console.error('Error loading match detail:', error);
    }
  };

  const handleSimulate = async () => {
    if (!window.confirm('آیا مطمئن هستید که می‌خواهید بازی‌ها را شبیه‌سازی کنید؟')) {
      return;
    }
    try {
      setSimulating(true);
      const res = await api.post('/league/simulate', { leagueName: currentLeague });
      if (res.data.success) {
        alert(`✅ ${res.data.message}`);
        loadData();
      }
    } catch (error) {
      alert(`❌ ${error.response?.data?.message || 'خطا در شبیه‌سازی'}`);
    } finally {
      setSimulating(false);
    }
  };

  const goToLiveMatches = () => {
    navigate('/weektable2');
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        <div className="main1">
          <SlamHeader/>

          <div className="card333">
            <div className="daba1">
              {/* جدول رتبه‌بندی - داینامیک */}
              <div className="standings">
                <table className="standings-table">
                  <thead>
                    <tr className="headerRow">
                      <th>رتبه</th>
                      <th>نام تیم</th>
                      <th>بازی</th>
                      <th>برد</th>
                      <th>مساوی</th>
                      <th>باخت</th>
                      <th>تفاضل گل</th>
                      <th>امتیاز</th>
                    </tr>
                  </thead>
                  <tbody>
                    {standings.length > 0 ? (
                      standings.map((team, idx) => (
                        <tr key={idx} className={`row-${idx}`} style={{
                          backgroundColor: team.isCurrentUser ? '#d4edda' : idx % 2 === 0 ? '#f8f9fa' : '#ffffff',
                          fontWeight: team.isCurrentUser ? 'bold' : 'normal'
                        }}>
                          <td>
                            <span style={{
                              backgroundColor: team.rank <= 1 ? '#28a745' : team.rank <= 4 ? '#17a2b8' : '#6c757d',
                              color: 'white',
                              padding: '2px 8px',
                              borderRadius: '50%',
                              minWidth: '25px',
                              display: 'inline-block'
                            }}>
                              {team.rank}
                            </span>
                          </td>
                          <td>
                            {team.teamLogo ? (
                              <img src={team.teamLogo} alt={team.team} style={{ width: '20px', height: '20px', borderRadius: '50%', marginRight: '5px' }} />
                            ) : null}
                            {team.team}
                            {team.isCurrentUser && <span style={{ color: '#28a745', fontSize: '12px' }}> (شما)</span>}
                          </td>
                          <td>{team.played}</td>
                          <td>{team.won}</td>
                          <td>{team.drawn}</td>
                          <td>{team.lost}</td>
                          <td>{team.goalDiff > 0 ? '+' : ''}{team.goalDiff}</td>
                          <td style={{ fontWeight: 'bold', color: '#28a745' }}>{team.points}</td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan="8" style={{ textAlign: 'center', color: '#999', padding: '20px' }}>
                          هنوز تیمی در این لیگ ثبت نشده است
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>

              {/* بازی قبلی و بعدی - داینامیک */}
              <div className="sacha">
                <div className="kdass">
                  <div className="ssas" onClick={() => lastMatch && handleViewMatchDetail(lastMatch)} style={{ cursor: lastMatch ? 'pointer' : 'default' }}>
                    <h5>📺 مشاهده بازی قبلی</h5>
                    {lastMatch ? (
                      <>
                        <div>{lastMatch.home} vs {lastMatch.away}</div>
                        <div>نتیجه: {lastMatch.score}</div>
                        <div style={{ color: '#28a745', fontSize: '12px' }}>کلیک برای جزئیات</div>
                      </>
                    ) : (
                      <div style={{ color: '#999' }}>هنوز بازی انجام نشده</div>
                    )}
                  </div>
                  <div className="ssas1" onClick={() => nextMatch && goToLiveMatches()} style={{ cursor: nextMatch ? 'pointer' : 'default' }}>
                    <h5>🔴 مشاهده بازی بعدی (زنده)</h5>
                    {nextMatch ? (
                      <>
                        <div>{nextMatch.home} vs {nextMatch.away}</div>
                        <div style={{ color: '#dc3545', fontSize: '12px' }}>کلیک برای مشاهده در صفحه بازی‌ها</div>
                      </>
                    ) : (
                      <div style={{ color: '#999' }}>بازی بعدی هنوز تعیین نشده</div>
                    )}
                  </div>
                </div>
              </div>

              <hr/>

              {/* نتایج بازی‌ها - داینامیک */}
              <div className="dsd2">
                <div className="condftainer">
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <h1>نتایج بازی‌های فوتبال</h1>
                    <button
                      onClick={handleSimulate}
                      disabled={simulating}
                      style={{
                        padding: '8px 16px',
                        backgroundColor: simulating ? '#ccc' : '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: simulating ? 'not-allowed' : 'pointer'
                      }}
                    >
                      {simulating ? 'در حال شبیه‌سازی...' : '🎮 شبیه‌سازی بازی‌ها'}
                    </button>
                  </div>
                  {matches.length > 0 ? (
                    matches.map((match, idx) => (
                      <div key={match._id || idx} className="match" onClick={() => handleViewMatchDetail(match)} style={{ cursor: 'pointer' }}>
                        <div className="teams">
                          <div className="team home-team">
                            <span>{match.home}</span>
                            <img src={match.homeLogo || imageprc} alt={match.home} className="team-logo"/>
                          </div>
                          <div className="score" style={{ fontSize: '24px', fontWeight: 'bold' }}>
                            {match.scoreHome} - {match.scoreAway}
                          </div>
                          <div className="team away-team">
                            <img src={match.awayLogo || imagees} alt={match.away} className="team-logo"/>
                            <span>{match.away}</span>
                          </div>
                        </div>
                      </div>
                    ))
                  ) : (
                    <p style={{ color: '#999', textAlign: 'center', padding: '20px' }}>
                      هنوز بازی‌ای انجام نشده است
                    </p>
                  )}
                </div>
              </div>
            </div>

            <hr/>

            {/* جوایز و وضعیت لیگ - داینامیک */}
            <div className="fspa">
              <div className="hsd">
                <div className='sss'>
                  <img src={Image1} alt="جام"/>
                </div>
                <div className="tecs">
                  <h3>جوایز لیگ {currentLeague}</h3>
                  <div className='ksl'>
                    <h4>۱. رتبه اول و صعود به مرحله بعد +</h4>
                    <div className='gsdl'>
                      <img src={Image200} alt="سکه"/>
                      <h3>سکه {(leagueRewards.coins || 0).toLocaleString()} +</h3>
                    </div>
                    <div className='gsdl'>
                      <img src={cashImage} alt="اسکناس"/>
                      <h3>{leagueRewards.banknotes || 0} اسکناس +</h3>
                    </div>
                  </div>
                  <div className='ksl'>
                    <h4>۲. رتبه دوم: صعود به مرحله بعد +</h4>
                    <div className='gsdl'>
                      <img src={Image200} alt="سکه"/>
                      <h3>سکه {Math.floor((leagueRewards.coins || 0) * 0.7).toLocaleString()} +</h3>
                    </div>
                    <div className='gsdl'>
                      <img src={cashImage} alt="اسکناس"/>
                      <h3>{Math.floor((leagueRewards.banknotes || 0) * 0.7)} اسکناس +</h3>
                    </div>
                  </div>
                  <div className='ksl'>
                    <h4>رتبه سوم</h4>
                    <div className='gsdl'>
                      <img src={Image200} alt="سکه"/>
                      <h3>سکه {Math.floor((leagueRewards.coins || 0) * 0.5).toLocaleString()} +</h3>
                    </div>
                    <div className='gsdl'>
                      <img src={cashImage} alt="اسکناس"/>
                      <h3>{Math.floor((leagueRewards.banknotes || 0) * 0.5)} اسکناس +</h3>
                    </div>
                  </div>
                  <div className='ksl'>
                    <h4>رتبه چهارم</h4>
                    <div className='gsdl'>
                      <img src={Image200} alt="سکه"/>
                      <h3>سکه {Math.floor((leagueRewards.coins || 0) * 0.25).toLocaleString()} +</h3>
                    </div>
                    <div className='gsdl'>
                      <img src={cashImage} alt="اسکناس"/>
                      <h3>{Math.floor((leagueRewards.banknotes || 0) * 0.25)} اسکناس +</h3>
                    </div>
                  </div>
                </div>
              </div>

              <div className="jsdl">
                <h2>وضعیت لیگ شما</h2>
                <h5>{currentLeague}</h5>
                <div style={{ marginBottom: '15px', padding: '10px', backgroundColor: '#e9ecef', borderRadius: '5px' }}>
                  <p style={{ margin: '5px 0' }}>🏆 رتبه شما: <strong>{leagueInfo.userRank}</strong> از <strong>{leagueInfo.totalTeams}</strong> تیم</p>
                  <p style={{ margin: '5px 0' }}>📊 امتیاز: <strong>{userData.points}</strong></p>
                  <p style={{ margin: '5px 0' }}>⚽ گل زده: <strong>{userData.goalsFor}</strong> | گل خورده: <strong>{userData.goalsAgainst}</strong></p>
                  <p style={{ margin: '5px 0' }}>🎮 بازی انجام شده: <strong>{userData.matchesPlayed}</strong></p>
                </div>
                <div className='swe'>
                  <img src={Image3} alt="تیک"/>
                  <h4 className='dsa'>ثبت‌نام انجام شده</h4>
                </div>
                <div className='swe'>
                  <img src={Image3} alt="تیک"/>
                  <h4 className='dsa'>پرداخت انجام شده</h4>
                </div>
                <div className='swe'>
                  <img src={userData.matchesPlayed > 0 ? Image3 : Image4} alt="وضعیت"/>
                  <h4 className={userData.matchesPlayed > 0 ? 'dsa' : 'dsa1'}>
                    {userData.matchesPlayed > 0 ? 'بازی انجام شده' : 'بازی انجام نشده'}
                  </h4>
                </div>
                <div className='swe'>
                  <img src={leagueInfo.status.rewardsClaimed ? Image3 : Image4} alt="وضعیت"/>
                  <h4 className={leagueInfo.status.rewardsClaimed ? 'dsa' : 'dsa1'}>
                    {leagueInfo.status.rewardsClaimed ? 'جوایز دریافت شده' : 'جوایز دریافت نشده'}
                  </h4>
                </div>
              </div>
            </div>
          </div>

          {/* مودال جزئیات بازی */}
          {showMatchDetail && selectedMatch && (
            <div style={{
              position: 'fixed',
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              backgroundColor: 'rgba(0,0,0,0.7)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 9999
            }} onClick={() => setShowMatchDetail(false)}>
              <div style={{
                backgroundColor: 'white',
                borderRadius: '15px',
                padding: '30px',
                maxWidth: '500px',
                width: '90%',
                maxHeight: '80vh',
                overflow: 'auto'
              }} onClick={e => e.stopPropagation()}>
                <div style={{ textAlign: 'center', marginBottom: '20px' }}>
                  <h3>{selectedMatch.home} vs {selectedMatch.away}</h3>
                  <h1 style={{ fontSize: '48px', margin: '10px 0' }}>{selectedMatch.score}</h1>
                  <p style={{ color: '#666' }}>{selectedMatch.league}</p>
                  {selectedMatch.isFinished && <span style={{ backgroundColor: '#28a745', color: 'white', padding: '5px 15px', borderRadius: '20px' }}>پایان یافته</span>}
                </div>
                {selectedMatch.events && selectedMatch.events.length > 0 ? (
                  <div>
                    <h4>رویدادهای بازی:</h4>
                    {selectedMatch.events.map((event, idx) => (
                      <div key={idx} style={{
                        padding: '8px',
                        marginBottom: '5px',
                        backgroundColor: event.type === 'goal' ? '#d4edda' : '#fff3cd',
                        borderRadius: '5px'
                      }}>
                        <strong>دقیقه {event.minute}</strong> - {event.playerName || event.description}
                      </div>
                    ))}
                  </div>
                ) : (
                  <p style={{ color: '#999', textAlign: 'center' }}>هنوز رویدادی ثبت نشده</p>
                )}
                <button onClick={() => setShowMatchDetail(false)} style={{
                  marginTop: '20px',
                  padding: '10px 20px',
                  backgroundColor: '#6c757d',
                  color: 'white',
                  border: 'none',
                  borderRadius: '4px',
                  cursor: 'pointer',
                  width: '100%'
                }}>
                  بستن
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Liga;
