import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useUser } from '../contexts/UserContext';
import { socket } from '../socket';
import LogoImage from '../images/favicon.png';
import api from '../services/api';

import '../styles/login.css';

const Login = () => {
  const [formData, setFormData] = useState({ email: '', password: '' });
  const [message, setMessage] = useState('');
  const [loading, setLoading] = useState(false);
  const { setUser } = useUser();
  const navigate = useNavigate();

  const onChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const onSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setMessage('');

    try {
      const res = await api.post('/auth/login', formData);

      if (!res.data.success) {
        throw new Error(res.data.message || res.data.msg || 'ورود ناموفق');
      }

      const { token, user } = res.data;

      if (!token || !user) {
        throw new Error('پاسخ سرور ناقص است - توکن یا کاربر وجود ندارد');
      }

      localStorage.setItem('token', token);
      localStorage.setItem('user', JSON.stringify(user));
      setUser(user);

      socket.auth = { token };
      socket.connect();

      setMessage('ورود موفقیت‌آمیز بود! به زمین بازی خوش اومدی!');

      setTimeout(() => {
        navigate(user.role === 'admin' ? '/admin' : '/CoachProfile2');
      }, 1500);
    } catch (err) {
      const errorMsg = err.response?.data?.message || err.response?.data?.msg || err.message || 'خطا در ورود';
      setMessage(errorMsg);
      console.error('Login error:', err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="d-flex justify-content-center align-items-center" style={{ minHeight: "80vh" }} dir="rtl">
      <div className="bg-white p-4 rounded-lg shadow-lg border border-light" style={{ maxWidth: '400px', width: '90%' }}>
        <div className="text-center mb-4">
          <img
            src={LogoImage}
            alt="لوگو"
            className="img-fluid rounded-circle mb-3"
            style={{ width: '80px', height: '80px', objectFit: 'cover' }}
          />
          <h4 className="fw-bold text-primary">ورود به حساب کاربری</h4>
          <p className="text-muted small">به پنل مدیریت تیم خوش آمدید</p>
        </div>

        <form onSubmit={onSubmit}>
          <div className="mb-3">
            <label className="form-label fw-semibold text-muted small">ایمیل</label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={onChange}
              placeholder="ایمیل خود را وارد کنید"
              required
              className="form-control"
              disabled={loading}
            />
          </div>

          <div className="mb-4">
            <label className="form-label fw-semibold text-muted small">رمز عبور</label>
            <input
              type="password"
              name="password"
              value={formData.password}
              onChange={onChange}
              placeholder="رمز عبور خود را وارد کنید"
              required
              className="form-control"
              disabled={loading}
            />
          </div>

          <button
            type="submit"
            className="btn btn-primary w-100 fw-bold py-2"
            disabled={loading}
          >
            {loading ? 'در حال ورود...' : 'ورود'}
          </button>
        </form>

        {message && (
          <div className={`alert mt-3 text-center small ${message.includes('موفق') ? 'alert-success' : 'alert-danger'}`}>
            {message}
          </div>
        )}

        <p className="text-center mt-3 text-muted small">
          حساب کاربری ندارید؟ <a href="/register" className="text-primary fw-semibold">ثبت‌نام کنید</a>
        </p>
      </div>
    </div>
  );
};

export default Login;
