import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/coatch.css';
import '../styles/shop.css'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { paymentService } from '../services/payment';
import { userService } from '../services/userService';

function Shop() {
  const [sortPrice, setSortPrice] = useState('');
  const [playerPosition, setPlayerPosition] = useState('');
  const [loading, setLoading] = useState(true);
  const [packages, setPackages] = useState([]);
  const [userData, setUserData] = useState({
    coins: 0,
    teamName: 'سی تی'
  });
  const [activeTab, setActiveTab] = useState('coins'); // coins, banknotes, players
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [packagesRes, profileRes] = await Promise.all([
        paymentService.getPackages().catch(() => ({ packages: { coins: [], banknotes: [], special: [] } })),
        userService.getProfile().catch(() => null)
      ]);

      if (packagesRes.packages) {
        const allPackages = [
          ...packagesRes.packages.coins.map(p => ({ ...p, type: 'coins' })),
          ...packagesRes.packages.banknotes.map(p => ({ ...p, type: 'banknotes' })),
          ...packagesRes.packages.special.map(p => ({ ...p, type: 'special' }))
        ];
        setPackages(allPackages);
      }

      if (profileRes) {
        setUserData({
          coins: profileRes.coins || 0,
          teamName: profileRes.username || 'سی تی'
        });
      }
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleBuy = (packageItem) => {
    navigate(`/payment?package=${packageItem.id}`);
  };

  const handleCoachClick = () => {
    navigate('/shop2');
  };

  // فیلتر و مرتب‌سازی
  const filteredPackages = packages
    .filter(pkg => {
      if (activeTab === 'coins' && pkg.type !== 'coins') return false;
      if (activeTab === 'banknotes' && pkg.type !== 'banknotes') return false;
      return true;
    })
    .sort((a, b) => {
      if (sortPrice === 'asc') {
        return (a.price || 0) - (b.price || 0);
      } else if (sortPrice === 'desc') {
        return (b.price || 0) - (a.price || 0);
      }
      return 0;
    });

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
        <div className="sidebar">
          <Link to="/"><FaHome /> صفحه اصلی</Link>
          <Link to="/Profile"><FaUser /> پروفایل مربی</Link>
          <Link to="/Liga"><FaChartBar /> لیگ‌های من</Link>
          <Link to="/Tamrin"><FaClipboardList /> تمرین و تاکتیک</Link>
          <Link to="/Camp"><FaDumbbell /> کمپ تمرینی</Link>
          <Link to="/Player"><FaUsers /> بازیکنان</Link>
          <Link to="/Morabi"><FaChalkboardTeacher /> مربی</Link>
          <Link to="/Shop"><FaShoppingCart /> فروشگاه</Link>
          <Link to="/Poshtibani"><FaComments /> پشتیبانی</Link>
        </div>
        
        <div className="main1">
          <div className="slam">
            <div className="left">
              <div className='col1'> <img src={imagePcg} alt=''/> <span>نام تیم: {userData.teamName}</span></div>
              <div className='col2'> <img src={Image200} alt="سکه"/> <span> {userData.coins.toLocaleString()}</span></div>
              <div className='col3'> <img src={cashImage} alt="پول" /> <span> 47 اسکناس</span> </div>
              <div className='col4'> <img src={Image300} alt="آمار"/> <span> آمار</span></div>
              <div className='col5'>  <img src={Image400} alt="ثبت‌نام"/>  <span> ثبت‌نام در کاپ حذف</span></div>
            </div>
            <div className="right" style={{ direction: "rtl", textAlign: "center" }}>
              {/* آیکون‌های پیام و تنظیمات */}
            </div>
          </div>
          
          <div className="card28">
            <div className="sas">
              <div className="sds">
                <div 
                  className={`sscdee ${activeTab === 'banknotes' ? 'active' : ''}`}
                  onClick={() => setActiveTab('banknotes')}
                  style={{ cursor: 'pointer' }}
                >
                  <img src={cashImage} alt='اسکناس'/>
                  <h2>خرید با اسکناس</h2>
                </div>
                <div 
                  className={`sscdee1 ${activeTab === 'coins' ? 'active' : ''}`}
                  onClick={() => setActiveTab('coins')}
                  style={{ cursor: 'pointer' }}
                >
                  <img src={Image200} alt='سکه'/>
                  <h2>خرید با سکه</h2>
                </div>
              </div>

              <div className="sdjdja">
                <div style={{ display: 'flex', width: 'fit-content', borderRadius: '8px', overflow: 'hidden' }}>
                  <button
                    onClick={() => setActiveTab('players')}
                    style={{
                      backgroundColor: activeTab === 'players' ? 'red' : '#ccc',
                      color: 'white',
                      padding: '10px 20px',
                      border: 'none',
                      borderTopLeftRadius: '8px',
                      borderBottomLeftRadius: '8px',
                      cursor: 'pointer',
                      fontWeight: 'bold'
                    }}
                  >
                    خرید بازیکن
                  </button>
                  <button
                    onClick={handleCoachClick}
                    style={{
                      backgroundColor: 'blue',
                      color: 'white',
                      padding: '10px 20px',
                      border: 'none',
                      borderTopRightRadius: '8px',
                      borderBottomRightRadius: '8px',
                      cursor: 'pointer',
                      fontWeight: 'bold',
                      marginLeft: '-1px'
                    }}
                  >
                    خرید مربی
                  </button>
                </div>

                <div>
                  <label className='wes'>
                    مرتب‌سازی بر اساس قیمت:
                    <select 
                      name="sortPrice" 
                      style={{ marginLeft: "10px" }}
                      value={sortPrice}
                      onChange={(e) => setSortPrice(e.target.value)}
                    >
                      <option value="">انتخاب کنید</option>
                      <option value="asc">از کم به زیاد</option>
                      <option value="desc">از زیاد به کم</option>
                    </select>
                  </label>
                </div>
              </div>

              <div className="iwew">  
                <h6>توجه: بازیکنان و سرمربیانی که از فروشگاه خریداری می‌شوند و قراردادشان پایان فصل نیاز به تمدید دارد، یک سوم قیمت اصلی می‌باشد</h6>  
              </div>
            </div>

            <div className="pa2">
              {activeTab === 'players' ? (
                <div style={{ padding: '2rem', textAlign: 'center' }}>
                  <p>بازیکنان از طریق کمپ جوانان قابل جذب هستند</p>
                  <Link to="/Player" style={{ color: '#007bff' }}>رفتن به صفحه بازیکنان</Link>
                </div>
              ) : filteredPackages.length > 0 ? (
                filteredPackages.map((pkg) => (
                  <div key={pkg.id} className="pva" style={{ cursor: 'pointer' }} onClick={() => handleBuy(pkg)}>
                    <div style={{ 
                      padding: '1rem', 
                      border: '1px solid #ddd', 
                      borderRadius: '8px',
                      backgroundColor: 'white',
                      textAlign: 'center'
                    }}>
                      <h4>{pkg.name || pkg.description}</h4>
                      <p style={{ fontSize: '1.2rem', fontWeight: 'bold', color: '#28a745' }}>
                        {pkg.price?.toLocaleString()} تومان
                      </p>
                      {pkg.coins && (
                        <p>
                          <img src={Image200} alt="سکه" style={{ width: '20px', height: '20px', verticalAlign: 'middle' }} />
                          {' '}{pkg.coins.toLocaleString()} سکه
                        </p>
                      )}
                      {pkg.banknotes && (
                        <p>
                          <img src={cashImage} alt="اسکناس" style={{ width: '20px', height: '20px', verticalAlign: 'middle' }} />
                          {' '}{pkg.banknotes.toLocaleString()} اسکناس
                        </p>
                      )}
                      {pkg.bonus && (
                        <p style={{ color: '#ffc107', fontSize: '0.9rem' }}>
                          هدیه: {pkg.bonus.toLocaleString()}
                        </p>
                      )}
                      <button
                        style={{
                          marginTop: '1rem',
                          padding: '0.5rem 1rem',
                          backgroundColor: '#007bff',
                          color: 'white',
                          border: 'none',
                          borderRadius: '4px',
                          cursor: 'pointer'
                        }}
                      >
                        خرید
                      </button>
                    </div>
                  </div>
                ))
              ) : (
                <div style={{ padding: '2rem', textAlign: 'center' }}>
                  <p>پکیجی یافت نشد</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Shop;
