import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/coatch.css';
import '../images/استادیوم.jpg'
import '../styles/Hazfi.css'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image100 from '../images/98.png'
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { userService } from '../services/userService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import api from '../services/api';
import image1 from "../images/287.png"


function Hazfi() {
  const [loading, setLoading] = useState(true);
  const [userData, setUserData] = useState({
    coins: 0,
    banknotes: 0,
    teamName: 'تیم من',
    teamLogo: '',
    role: 'user'
  });
  const [activeCup, setActiveCup] = useState(null);
  const [cupMessage, setCupMessage] = useState('');
  const [isAdmin, setIsAdmin] = useState(false);
  const [showCreateCup, setShowCreateCup] = useState(false);
  const [newCup, setNewCup] = useState({
    name: 'جام حذفی',
    season: '1405-1404',
    entryFeeBanknotes: 0,
    entryFeeCoins: 0,
    rewardBanknotes: 1000,
    rewardCoins: 5000,
    maxTeams: 16
  });
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const profileRes = await userService.getProfile().catch(() => null);
      if (profileRes) {
        setUserData({
          coins: profileRes.coins || 0,
          banknotes: profileRes.banknotes || 0,
          teamName: profileRes.teamName || profileRes.username || 'تیم من',
          teamLogo: profileRes.teamLogo || '',
          role: profileRes.role || 'user'
        });
        setIsAdmin(profileRes.role === 'admin');
      }
      fetchActiveCup();
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchActiveCup = async () => {
    try {
      const res = await api.get('/cup/active').catch(() => null);
      if (res?.data) {
        setActiveCup(res.data.cup);
      }
    } catch (error) {
      console.error('Error fetching cup:', error);
    }
  };

  const showMessage = (msg) => {
    setCupMessage(msg);
    setTimeout(() => setCupMessage(''), 4000);
  };

  const handleCreateCup = async (e) => {
    e.preventDefault();
    try {
      const res = await api.post('/cup/create', newCup).catch(() => null);
      if (res?.data) {
        showMessage('✅ جام حذفی ایجاد شد');
        setShowCreateCup(false);
        fetchActiveCup();
      }
    } catch (error) {
      showMessage('❌ خطا در ایجاد جام');
    }
  };

  const handleRegister = async () => {
    if (!activeCup) return;
    setCupMessage('');
    try {
      const res = await api.post(`/cup/${activeCup._id}/register`).catch(() => null);
      if (res?.data) {
        showMessage('✅ ثبت‌نام با موفقیت انجام شد!');
        fetchActiveCup();
        setTimeout(() => navigate('/hazfi-table'), 2000);
      }
    } catch (error) {
      showMessage(`❌ ${error.response?.data?.message || 'خطا در ثبت‌نام'}`);
    }
  };

  const handleStartCup = async () => {
    if (!activeCup) return;
    try {
      const res = await api.post(`/cup/${activeCup._id}/start`).catch(() => null);
      if (res?.data) {
        showMessage('✅ جام حذفی شروع شد!');
        fetchActiveCup();
      }
    } catch (error) {
      showMessage(`❌ ${error.response?.data?.message || 'خطا'}`);
    }
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        <div className="main1">
          <SlamHeader/>
          <div className="card24">
            <img src={image1} alt=""/>
            <h1><strong>ثبت نام در جام باشگاه‌ها</strong></h1>
            
            {activeCup ? (
              <>
                <div className='ljcve'>
                  <div className='sldsdasa'>
                    <h3 className='fjvmcm'>هزینه ثبت نام: {activeCup.entryFeeBanknotes || 0} اسکناس</h3>
                    {activeCup.entryFeeCoins ? <img src={Image200} alt="سکه" style={{ width: '30px', height: '30px' }} /> : null}
                    <span style={{ color: '#aaa', marginRight: '10px' }}>({activeCup.registered}/{activeCup.maxTeams} تیم)</span>
                  </div>
                </div>

                {/* نوار پیشرفت */}
                <div style={{ width: '80%', margin: '15px auto', height: '8px', backgroundColor: '#333', borderRadius: '4px', overflow: 'hidden' }}>
                  <div style={{
                    width: `${(activeCup.registered / activeCup.maxTeams) * 100}%`,
                    height: '100%',
                    backgroundColor: activeCup.status === 'registration' ? '#28a745' : '#007bff',
                    transition: 'width 0.3s'
                  }} />
                </div>

                {activeCup.status === 'registration' && (
                  <button
                    disabled={activeCup.isRegistered || !activeCup.canRegister}
                    onClick={handleRegister}
                    style={{
                      padding: '12px 30px',
                      backgroundColor: activeCup.isRegistered ? '#6c757d' : '#28a745',
                      color: 'white',
                      border: 'none',
                      borderRadius: '8px',
                      cursor: activeCup.isRegistered ? 'not-allowed' : 'pointer',
                      fontWeight: 'bold',
                      fontSize: '16px',
                      marginTop: '10px'
                    }}
                  >
                    {activeCup.isRegistered ? '✅ شما ثبت‌نام کرده‌اید' : '➕ ثبت‌نام کنید'}
                  </button>
                )}

                {activeCup.status === 'in_progress' && (
                  <button
                    onClick={() => navigate('/hazfi-table')}
                    style={{
                      padding: '12px 30px',
                      backgroundColor: '#007bff',
                      color: 'white',
                      border: 'none',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      fontWeight: 'bold',
                      fontSize: '16px',
                      marginTop: '10px'
                    }}
                  >
                    🏆 مشاهده جدول حذفی
                  </button>
                )}

                {isAdmin && activeCup.status === 'registration' && (
                  <button
                    onClick={handleStartCup}
                    disabled={activeCup.registered < activeCup.minTeamsToStart}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: activeCup.registered >= activeCup.minTeamsToStart ? '#dc3545' : '#6c757d',
                      color: 'white',
                      border: 'none',
                      borderRadius: '8px',
                      cursor: activeCup.registered >= activeCup.minTeamsToStart ? 'pointer' : 'not-allowed',
                      fontWeight: 'bold',
                      fontSize: '14px',
                      marginTop: '10px',
                      marginRight: '10px'
                    }}
                  >
                    🚀 شروع جام حذفی
                  </button>
                )}

                {isAdmin && (
                  <button
                    onClick={() => setShowCreateCup(!showCreateCup)}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: '#6c757d',
                      color: 'white',
                      border: 'none',
                      borderRadius: '8px',
                      cursor: 'pointer',
                      fontWeight: 'bold',
                      fontSize: '14px',
                      marginTop: '10px'
                    }}
                  >
                    ➕ جام جدید
                  </button>
                )}

                {showCreateCup && (
                  <div style={{
                    position: 'fixed',
                    top: 0, left: 0, right: 0, bottom: 0,
                    backgroundColor: 'rgba(0,0,0,0.7)',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    zIndex: 9999
                  }} onClick={() => setShowCreateCup(false)}>
                    <div style={{
                      backgroundColor: '#1a1a2e',
                      padding: '30px',
                      borderRadius: '10px',
                      maxWidth: '500px',
                      width: '90%'
                    }} onClick={e => e.stopPropagation()}>
                      <h3 style={{ color: '#FFD700' }}>ایجاد جام حذفی جدید</h3>
                      <form onSubmit={handleCreateCup}>
                        <div style={{ marginBottom: '10px' }}>
                          <label style={{ display: 'block', color: '#aaa' }}>نام جام:</label>
                          <input type="text" value={newCup.name} onChange={e => setNewCup(p => ({...p, name: e.target.value}))} required
                            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #444', backgroundColor: '#0f3460', color: 'white' }} />
                        </div>
                        <div style={{ marginBottom: '10px' }}>
                          <label style={{ display: 'block', color: '#aaa' }}>فصل:</label>
                          <input type="text" value={newCup.season} onChange={e => setNewCup(p => ({...p, season: e.target.value}))}
                            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #444', backgroundColor: '#0f3460', color: 'white' }} />
                        </div>
                        <div style={{ marginBottom: '10px' }}>
                          <label style={{ display: 'block', color: '#aaa' }}>تعداد تیم‌ها:</label>
                          <input type="number" value={newCup.maxTeams} onChange={e => setNewCup(p => ({...p, maxTeams: parseInt(e.target.value)}))} min="16"
                            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #444', backgroundColor: '#0f3460', color: 'white' }} />
                        </div>
                        <div style={{ marginBottom: '10px' }}>
                          <label style={{ display: 'block', color: '#aaa' }}>ورودی (بانکنافت):</label>
                          <input type="number" value={newCup.entryFeeBanknotes} onChange={e => setNewCup(p => ({...p, entryFeeBanknotes: parseInt(e.target.value)}))}
                            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #444', backgroundColor: '#0f3460', color: 'white' }} />
                        </div>
                        <div style={{ marginBottom: '10px' }}>
                          <label style={{ display: 'block', color: '#aaa' }}>جایزه (بانکنافت):</label>
                          <input type="number" value={newCup.rewardBanknotes} onChange={e => setNewCup(p => ({...p, rewardBanknotes: parseInt(e.target.value)}))}
                            style={{ width: '100%', padding: '8px', borderRadius: '4px', border: '1px solid #444', backgroundColor: '#0f3460', color: 'white' }} />
                        </div>
                        <div style={{ display: 'flex', gap: '10px', marginTop: '15px' }}>
                          <button type="submit" style={{ flex: 1, padding: '10px', backgroundColor: '#28a745', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer', fontWeight: 'bold' }}>ایجاد</button>
                          <button type="button" onClick={() => setShowCreateCup(false)} style={{ flex: 1, padding: '10px', backgroundColor: '#6c757d', color: 'white', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>بستن</button>
                        </div>
                      </form>
                    </div>
                  </div>
                )}

                {cupMessage && <p style={{ color: '#d00', marginTop: '10px' }}>{cupMessage}</p>}
              </>
            ) : (
              <p>جام حذفی فعالی وجود ندارد</p>
            )}
            
            <p className='fdeasdw'>*جام حذفی با حضور ۱۶ تیم به صورت تک بازی و حذفی انجام می‌شود</p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Hazfi;
