import api from './api';

export const userService = {
  // دریافت پروفایل کاربر (برگشت آبجکت user برای سازگاری با صفحات)
  getProfile: async () => {
    const response = await api.get('/auth/profile');
    const raw = response.data;
    const user = raw?.user || raw;
    return {
      ...user,
      _id: user._id,
      username: user.username || '',
      teamName: user.teamName || user.username || '',
      coins: user.coins ?? 0,
      banknotes: user.banknotes ?? 0,
      teamPower: user.teamPower ?? 0,
      players: Array.isArray(user.players) ? user.players : [],
      coach: user.coach || null,
      league: user.league || {},
      lineup: user.lineup || [],
      manager: user.manager || '',
      description: user.description || '',
      rank: user.rank ?? 0,
      teamLogo: user.teamLogo || null
    };
  },

  // به‌روزرسانی پروفایل
  updateProfile: async (profileData) => {
    const response = await api.put('/auth/profile', profileData);
    return response.data;
  },

  // آپلود آواتار
  uploadAvatar: async (file) => {
    const formData = new FormData();
    formData.append('avatar', file);
    const response = await api.post('/upload/upload-avatar', formData, {
      headers: {
        'Content-Type': 'multipart/form-data'
      }
    });
    return response.data;
  }
};



