import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import '../styles/coatch.css';
import image1 from '../images/spons.jpg'
import image3 from '../images/pngimg.com - coin_PNG36871.png'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import api from '../services/api';
import { facilityService } from '../services/facilityService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import "../styles/risponsive.css"

function Sponser() {
  const [loading, setLoading] = useState(true);
  const [upgrading, setUpgrading] = useState(false);
  const [message, setMessage] = useState('');
  const [facilities, setFacilities] = useState(null);
  const [userData, setUserData] = useState({
    coins: 0,
    teamName: 'تیم من',
    facilities: {}
  });

  useEffect(() => {
    loadData();
    // به‌روز‌رسانی خودکار هر ۳۰ ثانیه برای نمایش سکه‌های تولید شده
    const interval = setInterval(loadData, 30000);
    return () => clearInterval(interval);
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const facilitiesRes = await facilityService.getFacilities();
      
      if (facilitiesRes.success) {
        setFacilities(facilitiesRes.facilities);
        setUserData(prev => ({
          ...prev,
          coins: facilitiesRes.coins || 0,
          facilities: facilitiesRes.facilities || {}
        }));
      }
    } catch (error) {
      console.error('Error loading data:', error);
      setMessage('خطا در بارگذاری اطلاعات');
    } finally {
      setLoading(false);
    }
  };

  const handleUpgrade = async () => {
    const currentLevel = facilities?.sponsor?.level || 1;
    const upgradeCost = currentLevel * 100;
    
    if (userData.coins < upgradeCost) {
      setMessage(`❌ سکه کافی ندارید (نیاز: ${upgradeCost})`);
      return;
    }
    
    if (!window.confirm(`اسپانسر را به سطح ${currentLevel + 1} ارتقا دهید?\nهزینه: ${upgradeCost} سکه`)) {
      return;
    }

    setUpgrading(true);
    setMessage('');
    try {
      const res = await api.post('/squad/upgrade-facility', { facilityType: 'sponsor' });
      if (res.data.success) {
        setUserData(prev => ({
          ...prev,
          coins: res.data.coins,
          facilities: {
            ...prev.facilities,
            sponsor: res.data.facility
          }
        }));
        setMessage(`✅ ${res.data.message}`);
        setTimeout(() => loadData(), 1000);
      } else {
        setMessage(`❌ ${res.data.message}`);
      }
    } catch (err) {
      setMessage(`❌ خطا: ${err.response?.data?.message || err.message}`);
    } finally {
      setUpgrading(false);
    }
  };

  const handleCollect = async () => {
    try {
      const res = await api.post('/squad/collect-coins', { facilityType: 'sponsor' });
      if (res.data.success) {
        setMessage(`✅ ${res.data.message}`);
        loadData();
      } else {
        setMessage(`❌ ${res.data.message}`);
      }
    } catch (err) {
      setMessage(`❌ خطا: ${err.response?.data?.message || err.message}`);
    }
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>درحال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  const sponsor = facilities?.sponsor || { level: 1, collectableCoins: 0, productionRate: 10, upgradeCost: 100, maxLevel: false };
  const currentLevel = sponsor.level || 1;
  const upgradeCost = currentLevel * 100;

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        
        <div className="main1">
         <SlamHeader/>

          {message && (
            <div style={{ 
              padding: '1rem', 
              margin: '1rem', 
              backgroundColor: message.includes('❌') ? '#ffebee' : '#e8f5e9',
              color: message.includes('❌') ? '#c62828' : '#1b5e20',
              borderRadius: '4px',
              textAlign: 'center',
              border: message.includes('❌') ? '1px solid #ef5350' : '1px solid #4caf50'
            }}>
              {message}
            </div>
          )}

          <div className="card23">
            <div className="righttt">
              <div className="oodd">
                <h1>اسپانسر تیم سطح {currentLevel}</h1>
                <p>اسپانسر یا حامی مالی می‌تواند درآمد تیم و جذابیت آن را افزایش دهد.</p>
              </div>
              <div className="vasat">
                <div className="rast5">
                  <h3>ارتقا به سطح {currentLevel + 1}</h3>
                  <div className='kwnwedwj'>
                    <h5>هزینه ارتقا: {upgradeCost} </h5>
                    <img src={image3} alt="سکه"/>
                  </div>
                  <button
                    onClick={handleUpgrade}
                    disabled={upgrading || userData.coins < upgradeCost}
                    style={{
                      padding: '0.5rem 1rem',
                      backgroundColor: (upgrading || userData.coins < upgradeCost) ? '#ccc' : '#28a745',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: (upgrading || userData.coins < upgradeCost) ? 'not-allowed' : 'pointer',
                      marginTop: '1rem',
                      width: '100%'
                    }}
                  >
                    {upgrading ? 'درحال ارتقاء...' : userData.coins < upgradeCost ? 'سکه کافی نیست' : 'ارتقاء'}
                  </button>
                </div>
                <div className='ldlsd'>
                  <div className="dcsdcd">
                    <h3>سطح {currentLevel}</h3>
                    <p className='wla'>
                      درآمد ماهانه: <span>+{currentLevel * 5000}</span> سکه
                    </p>
                    <p className='wla'>
                      شهرت تیم: <span>+{currentLevel * 10}%</span>
                    </p>
                    {sponsor.collectableCoins > 0 && (
                      <button
                        onClick={handleCollect}
                        style={{
                          padding: '0.5rem 1rem',
                          backgroundColor: '#007bff',
                          color: 'white',
                          border: 'none',
                          borderRadius: '4px',
                          cursor: 'pointer',
                          marginTop: '1rem',
                          width: '100%'
                        }}
                      >
                        💰 برداشت {sponsor.collectableCoins} سکه
                      </button>
                    )}
                  </div>
                  <div className="dccdcdas">
                    <h3>سطح {currentLevel + 1}</h3>
                    <p className='wla'>
                      درآمد ماهانه: <span>+{(currentLevel + 1) * 5000}</span> سکه
                    </p>
                    <p className='wla'>
                      شهرت تیم: <span>+{(currentLevel + 1) * 10}%</span>
                    </p>
                  </div>
                </div>
              </div>
              <div className="paeen">
                <h6>اسپانسر می‌تواند درآمد تیم و جذابیت آن را افزایش دهد.</h6>
              </div>
            </div>
            <div className="leftt">
              <div className="balach">
                <img src={image1} alt="اسپانسر"/>
              </div>
              <div className="paeench">
                <h3>اسپانسر</h3>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Sponser;
