import React, { useEffect, useState, useRef } from 'react';
import { Link, useNavigate } from 'react-router-dom';

import '../styles/coatchprofile2.css';
import image1 from '../images/audio_volume_bars.png';
import image2 from '../images/administrator.png';
import image3 from '../images/clock.png';
import image4 from '../images/network.png';
import image5 from '../images/pedestrian_traffic_light_walk.png';
import image6 from '../images/certificate.png';
import image7 from '../images/استادیوم.png';
import image8 from '../images/اسپانسر-1.png';
import image9 from '../images/حق-پخش.png';
import image10 from '../images/کمپ-نوجوانان.png';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg';

import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments, FaCoins } from 'react-icons/fa';

import SlamHeader from './SlamHeader';
import { useUser } from '../contexts/UserContext';
import api from '../services/api';
import Sidebar from './Sidebar';
import '../styles/coatchprofile2.css'
import "../styles/coatch.css"
import '../styles/risponsive.css'

function CoachProfile2() {
  const navigate = useNavigate();
  const { user } = useUser();
  const { loading } = useUser();
  const [upgrading, setUpgrading] = useState(false);
  const [message, setMessage] = useState('');
  const [tooltip, setTooltip] = useState(null);
  const [collecting, setCollecting] = useState(null);
  const [collectingAll, setCollectingAll] = useState(false);
  const [facilityData, setFacilityData] = useState({
    stadium: { currentCoins: 0, level: 1 },
    sponsor: { currentCoins: 0, level: 1 },
    tvRights: { currentCoins: 0, level: 1 },
    youthCamp: { currentCoins: 0, level: 1 }
  });
  const facilityRefs = useRef({});

  // دریافت اطلاعات facilities از API برای نمایش سکه‌های تولید شده
  useEffect(() => {
    const fetchFacilities = async () => {
      try {
        const res = await api.get('/facilities');
        if (res.data.success && res.data.facilities) {
          const facilities = res.data.facilities;
          setFacilityData(prev => ({
            ...prev,
            stadium: {
              currentCoins: facilities.stadium?.collectableCoins || 0,
              level: facilities.stadium?.level || 1
            },
            sponsor: {
              currentCoins: facilities.sponsor?.collectableCoins || 0,
              level: facilities.sponsor?.level || 1
            },
            tvRights: {
              currentCoins: facilities.tvRights?.collectableCoins || 0,
              level: facilities.tvRights?.level || 1
            },
            youthCamp: {
              currentCoins: facilities.youthCamp?.collectableCoins || 0,
              level: facilities.youthCamp?.level || 1
            }
          }));
        }
      } catch (error) {
        console.error('Error fetching facilities:', error);
      }
    };

    // دریافت اولیه
    fetchFacilities();
    
    // به‌روز‌رسانی هر 30 ثانیه
    const interval = setInterval(fetchFacilities, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!loading && (!user || !user.teamName)) {
      navigate('/TeamRegistrationForm');
    }
  }, [loading, user, navigate]);

  const handleUpgradeFacility = async (facilityType) => {
    if (!window.confirm(`سطح ${facilityType} را بهبود دهید؟\nهزینه: ${(user.facilities?.[facilityType]?.level || 1) * 100} سکه`)) {
      return;
    }

    setUpgrading(true);
    setMessage('');
    try {
      const res = await api.post('/squad/upgrade-facility', { facilityType });
      if (res.data.success) {
        setMessage(`✅ ${res.data.message}`);
        // به‌روز‌رسانی فوری facilities
        await refreshFacilities();
      } else {
        setMessage(`❌ ${res.data.message}`);
      }
    } catch (err) {
      setMessage(`❌ خطا: ${err.response?.data?.message || err.message}`);
    } finally {
      setUpgrading(false);
    }
  };

  // تابع به‌روز‌رسانی facilities
  const refreshFacilities = async () => {
    try {
      const res = await api.get('/facilities');
      if (res.data.success && res.data.facilities) {
        const facilities = res.data.facilities;
        setFacilityData({
          stadium: {
            currentCoins: facilities.stadium?.collectableCoins || 0,
            level: facilities.stadium?.level || 1
          },
          sponsor: {
            currentCoins: facilities.sponsor?.collectableCoins || 0,
            level: facilities.sponsor?.level || 1
          },
          tvRights: {
            currentCoins: facilities.tvRights?.collectableCoins || 0,
            level: facilities.tvRights?.level || 1
          },
          youthCamp: {
            currentCoins: facilities.youthCamp?.collectableCoins || 0,
            level: facilities.youthCamp?.level || 1
          }
        });
        // به‌روز‌رسانی user context
        if (res.data.coins !== undefined) {
          localStorage.setItem('user', JSON.stringify({ ...user, coins: res.data.coins }));
        }
      }
    } catch (error) {
      console.error('Error refreshing facilities:', error);
    }
  };

    const handleCollectCoins = async (facilityType, e) => {
    e.stopPropagation();
    setCollecting(facilityType);
    try {
      // تغییر مهم: استفاده از /facilities/collect/:facilityType به جای /squad/collect-coins
      const res = await api.post(`/facilities/collect/${facilityType}`);
      if (res.data.success) {
        setMessage(`✅ ${res.data.message}`);
        await refreshFacilities();
        // به‌روز‌رسانی user
        if (user) {
          const updatedUser = { ...user, coins: res.data.totalCoins || user.coins + res.data.collectedCoins };
          localStorage.setItem('user', JSON.stringify(updatedUser));
        }
      } else {
        setMessage(`❌ ${res.data.message}`);
      }
    } catch (err) {
      setMessage(`❌ خطا: ${err.response?.data?.message || err.message}`);
    } finally {
      setCollecting(null);
    }
  };



  // جمع‌آوری همه سکه‌ها
   const handleCollectAllCoins = async () => {
    setCollectingAll(true);
    setMessage('');
    const facilityTypes = ['stadium', 'sponsor', 'tvRights', 'youthCamp'];
    let totalCollected = 0;

    for (const type of facilityTypes) {
      try {
        // تغییر مهم: استفاده از /facilities/collect/:facilityType
        const res = await api.post(`/facilities/collect/${type}`);
        if (res.data.success) {
          totalCollected += res.data.collectedCoins || 0;
        }
      } catch (err) {
        console.error(`Error collecting ${type}:`, err);
      }
    }

    if (totalCollected > 0) {
      setMessage(`✅ مجموعاً ${totalCollected} سکه جمع‌آوری شد!`);
      await refreshFacilities();
      if (user) {
        const updatedUser = JSON.parse(localStorage.getItem('user'));
        localStorage.setItem('user', JSON.stringify({ ...updatedUser, coins: updatedUser.coins + totalCollected }));
      }
    } else {
      setMessage('سکه‌ای برای جمع‌آوری وجود ندارد');
    }

    setCollectingAll(false);
  };


  const updateTooltipPosition = (e, facilityType) => {
    const ref = facilityRefs.current[facilityType];
    if (ref) {
      const rect = ref.getBoundingClientRect();
      setTooltip({ 
        left: rect.left + rect.width / 2, 
        top: rect.top - 10, 
        text: getTooltipText(facilityType) 
      });
    }
  };

  const getTooltipText = (facilityType) => {
    const facility = facilityData[facilityType];
    const currentCoins = facility?.currentCoins ?? 0;
    const level = facility?.level ?? 1;
    
    switch (facilityType) {
      case 'stadium':
        return `تعداد سکه تولید شده: ${currentCoins}\nسطح: ${level}\nنرخ: ${level * 50} سکه/مسابقه\nبرای جمع‌آوری کلیک کنید`;
      case 'sponsor':
        return `تعداد سکه تولید شده: ${currentCoins}\nسطح: ${level}\nنرخ: ${level * 100} سکه/روز\nبرای جمع‌آوری کلیک کنید`;
      case 'tvRights':
        return `تعداد سکه تولید شده: ${currentCoins}\nسطح: ${level}\nنرخ: ${level * 75} سکه/هفته\nبرای جمع‌آوری کلیک کنید`;
      case 'youthCamp':
        return `تعداد سکه تولید شده: ${currentCoins}\nسطح: ${level}\nنرخ: ${level * 30} سکه/ماه\nبرای جمع‌آوری کلیک کنید`;
      default:
        return '';
    }
  };

  if (!user) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="sidebar">
            <Link to="/"><FaHome /> صفحه اصلی</Link>
            <Link to="/profile"><FaUser /> پروفایل مربی</Link>
            <Link to="/leagues"><FaChartBar /> لیگ‌های من</Link>
            <Link to="/training"><FaClipboardList /> تمرین و تاکتیک</Link>
            <Link to="/camp"><FaDumbbell /> کمپ تمرینی</Link>
            <Link to="/players"><FaUsers /> بازیکنان</Link>
            <Link to="/coach"><FaChalkboardTeacher /> مربی</Link>
            <Link to="/shop"><FaShoppingCart /> فروشگاه</Link>
            <Link to="/support"><FaComments /> پشتیبانی</Link>
          </div>

          <div className="main1" style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '70vh' }}>
            <div style={{ padding: 40, textAlign: 'center' }}>در حال بارگذاری...</div>
          </div>
        </div>
      </div>
    );
  }

  const stadiumLevel = facilityData.stadium.level;
  const sponsorLevel = facilityData.sponsor.level;
  const tvLevel = facilityData.tvRights.level;
  const youthLevel = facilityData.youthCamp.level;

  const stadiumCoins = facilityData.stadium.currentCoins;
  const sponsorCoins = facilityData.sponsor.currentCoins;
  const tvCoins = facilityData.tvRights.currentCoins;
  const youthCoins = facilityData.youthCamp.currentCoins;

  const totalAvailableCoins = stadiumCoins + sponsorCoins + tvCoins + youthCoins;

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar />

        <div className="main1">
          <SlamHeader />

          <div className="cardd26">
            <div className="sa">
              <div className="baraa">
                <div className='wecdqq'>
                  <h3>لیگ شروع: {(user.league && user.league.currentLeague) || user.league || 'اطلاعات وارد نشده'}</h3>
                  <img src={image1} alt="" />
                </div>
                <div className='wecdqq'>
                  <h3>قدرت تیم: {user.teamPower ?? 'اطلاعات وارد نشده'}</h3>
                  <img src={image2} alt="" />
                </div>
                <div className='wecdqq'>
                  <h3>زمان باقی مانده شما برای مسابقه بعدی: 14:21:38</h3>
                  <img src={image3} alt="" />
                </div>
              </div>

              <div className="bachaa">
                <div className='wecdqq'>
                  <h3>حتما قبل از هر بازی حریف رو آنالیز کن و از ترکیب و تاکتیک تیمت مطمئن شو</h3>
                  <img src={image4} alt="" />
                </div>
                <div className='wecdqq'>
                  <h3>هرچی سطح کمپ نوجوانان بالاتر باشه بعد از بازنشستگی بازیکن بهتری می‌گیری</h3>
                  <img src={image5} alt="" />
                </div>
                <div className='wecdqq'>
                  <h3>جدی باش مربی چون تیم‌های درخشان لیگ ستارگان مبلغ ۱۰۰۰۰۰۰۰۰ت</h3>
                  <img src={image6} alt="" />
                </div>
              </div>
            </div>

            {/* دکمه جمع‌آوری همه سکه‌ها */}
          

            <div className="pa2">
              <div
                ref={(el) => { facilityRefs.current['stadium'] = el; }}
                className="pva"
                onClick={() => handleUpgradeFacility('stadium')}
                style={{ cursor: upgrading ? 'not-allowed' : 'pointer', opacity: upgrading ? 0.6 : 1, position: 'relative' }}
                onMouseEnter={(e) => updateTooltipPosition(e, 'stadium')}
                onMouseLeave={() => setTooltip(null)}
                onDoubleClick={(e) => handleCollectCoins('stadium', e)}
              >
                <img className='qapl' src={image7} alt="استادیوم" />
                <h5>استادیوم: سطح {stadiumLevel}</h5>
                <p style={{ fontSize: '0.85rem', color: '#666', margin: '5px 0' }}>
                  هزینه: {stadiumLevel * 100} سکه
                </p>
                {stadiumCoins > 0 && (
                  <div className="coin-badge" onClick={(e) => handleCollectCoins('stadium', e)} style={{ cursor: 'pointer' }}>
                    <FaCoins style={{ color: '#FFD700', fontSize: '1.2rem' }} />
                    <span>{stadiumCoins}</span>
                  </div>
                )}
              </div>

              <div
                ref={(el) => { facilityRefs.current['sponsor'] = el; }}
                className="pva"
                onClick={() => handleUpgradeFacility('sponsor')}
                style={{ cursor: upgrading ? 'not-allowed' : 'pointer', opacity: upgrading ? 0.6 : 1, position: 'relative' }}
                onMouseEnter={(e) => updateTooltipPosition(e, 'sponsor')}
                onMouseLeave={() => setTooltip(null)}
                onDoubleClick={(e) => handleCollectCoins('sponsor', e)}
              >
                <img src={image8} alt="اسپانسر" />
                <h5>اسپانسر: سطح {sponsorLevel}</h5>
                <p style={{ fontSize: '0.85rem', color: '#666', margin: '5px 0' }}>
                  هزینه: {sponsorLevel * 100} سکه
                </p>
                {sponsorCoins > 0 && (
                  <div className="coin-badge" onClick={(e) => handleCollectCoins('sponsor', e)} style={{ cursor: 'pointer' }}>
                    <FaCoins style={{ color: '#FFD700', fontSize: '1.2rem' }} />
                    <span>{sponsorCoins}</span>
                  </div>
                )}
              </div>

              <div
                ref={(el) => { facilityRefs.current['tvRights'] = el; }}
                className="pva"
                onClick={() => handleUpgradeFacility('tvRights')}
                style={{ cursor: upgrading ? 'not-allowed' : 'pointer', opacity: upgrading ? 0.6 : 1, position: 'relative' }}
                onMouseEnter={(e) => updateTooltipPosition(e, 'tvRights')}
                onMouseLeave={() => setTooltip(null)}
                onDoubleClick={(e) => handleCollectCoins('tvRights', e)}
              >
                <img src={image9} alt="حق پخش" />
                <h5>حق پخش تلویزیونی: سطح {tvLevel}</h5>
                <p style={{ fontSize: '0.85rem', color: '#666', margin: '5px 0' }}>
                  هزینه: {tvLevel * 100} سکه
                </p>
                {tvCoins > 0 && (
                  <div className="coin-badge" onClick={(e) => handleCollectCoins('tvRights', e)} style={{ cursor: 'pointer' }}>
                    <FaCoins style={{ color: '#FFD700', fontSize: '1.2rem' }} />
                    <span>{tvCoins}</span>
                  </div>
                )}
              </div>

              <div
                ref={(el) => { facilityRefs.current['youthCamp'] = el; }}
                className="pva"
                style={{ position: 'relative' }}
                onMouseEnter={(e) => updateTooltipPosition(e, 'youthCamp')}
                onMouseLeave={() => setTooltip(null)}
                onDoubleClick={(e) => handleCollectCoins('youthCamp', e)}
              >
                <Link to="/camp">
                  <img  src={image10} alt="کمپ" />
                  <h5>کمپ نوجوانان: سطح {youthLevel}</h5>
                </Link>
                {youthCoins > 0 && (
                  <div className="coin-badge" onClick={(e) => handleCollectCoins('youthCamp', e)} style={{ cursor: 'pointer' }}>
                    <FaCoins style={{ color: '#FFD700', fontSize: '1.2rem' }} />
                    <span>{youthCoins}</span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {tooltip && (
        <div
          style={{
            position: 'fixed',
            left: tooltip.left,
            top: tooltip.top,
            transform: 'translate(-50%, -100%)',
            backgroundColor: 'rgba(0,0,0,0.9)',
            color: '#FFD700',
            padding: '10px 16px',
            borderRadius: '10px',
            fontSize: '0.85rem',
            fontWeight: 'bold',
            pointerEvents: 'none',
            zIndex: 9999,
            whiteSpace: 'pre-line',
            boxShadow: '0 4px 15px rgba(255, 215, 0, 0.3)',
            border: '1px solid rgba(255, 215, 0, 0.4)',
            maxWidth: '250px',
            textAlign: 'center'
          }}
        >
          {tooltip.text}
        </div>
      )}

      {message && (
        <div style={{
          position: 'fixed',
          bottom: '20px',
          left: '50%',
          transform: 'translateX(-50%)',
          padding: '12px 24px',
          borderRadius: '8px',
          backgroundColor: message.includes('✅') ? '#4caf50' : '#f44336',
          color: '#fff',
          zIndex: 10000,
          boxShadow: '0 4px 12px rgba(0,0,0,0.3)'
        }}>
          {message}
        </div>
      )}
    </div>
  );
}

export default CoachProfile2;
