import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/coatch.css';
import '../images/استادیوم.jpg'
import image1 from "../images/287.png"
import '../styles/hazfitable.css'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image100 from '../images/98.png'
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { userService } from '../services/userService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import api from '../services/api';



function HazfiTable() {
  const [loading, setLoading] = useState(true);
  const [userData, setUserData] = useState({
    coins: 0,
    banknotes: 0,
    teamName: 'تیم من',
    teamLogo: '',
    role: 'user'
  });
  const [activeCup, setActiveCup] = useState(null);
  const [bracket, setBracket] = useState(null);
  const [cupMessage, setCupMessage] = useState('');
  const [isAdmin, setIsAdmin] = useState(false);
  const [scoreInputs, setScoreInputs] = useState({});
  const navigate = useNavigate();

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const profileRes = await userService.getProfile().catch(() => null);
      if (profileRes) {
        setUserData({
          coins: profileRes.coins || 0,
          banknotes: profileRes.banknotes || 0,
          teamName: profileRes.teamName || profileRes.username || 'تیم من',
          teamLogo: profileRes.teamLogo || '',
          role: profileRes.role || 'user'
        });
        setIsAdmin(profileRes.role === 'admin');
      }
      fetchCup();
    } catch (error) {
      console.error('Error loading data:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchCup = async () => {
    try {
      const res = await api.get('/cup/active').catch(() => null);
      if (res?.data?.cup) {
        setActiveCup(res.data.cup);
        if (res.data.cup.bracket) {
          setBracket(res.data.cup.bracket);
        }
      }
    } catch (error) {
      console.error('Error fetching cup:', error);
    }
  };

  

  const handleScoreChange = (round, index, field, value) => {
    setScoreInputs(prev => ({
      ...prev,
      [`${round}_${index}_${field}`]: value
    }));
  };

  const handleSaveScore = async (round, index) => {
    const t1 = scoreInputs[`${round}_${index}_team1`];
    const t2 = scoreInputs[`${round}_${index}_team2`];
    
    if (t1 === undefined || t2 === undefined) {
      setCupMessage('⚠️ هر دو امتیاز را وارد کنید');
      return;
    }

    try {
      const res = await api.post(`/cup/match/${round}/${index}/result`, {
        team1Score: parseInt(t1),
        team2Score: parseInt(t2)
      }).catch(() => null);

      if (res?.data) {
        setCupMessage('✅ نتیجه ثبت شد');
        fetchCup();
        setTimeout(() => setCupMessage(''), 3000);
      }
    } catch (error) {
      setCupMessage('❌ خطا در ثبت نتیجه');
    }
  };

  const getTeamInfo = (userId) => {
    if (!userId) return null;
    const team = activeCup?.registered?.find(t => t._id?.toString() === userId.toString() || t.toString() === userId.toString());
    return team;
  };

  const renderMatch = (match, round, index) => {
    if (!match) return null;

    const team1 = getTeamInfo(match.team1);
    const team2 = getTeamInfo(match.team2);
    const isFinished = match.status === 'finished';
    const hasWinner = !!match.winner;

    return (
      <div key={`${round}_${index}`} className={`match-card ${hasWinner ? 'has-winner' : ''}`}>
        <div className={`team ${match.winner?.toString() === (match.team1?.toString()) ? 'winner' : ''}`}>
          {match.team1 ? (
            <>
              <img
                src={team1?.teamLogo || userData.teamLogo || '/default-logo.png'}
                alt="Team 1"
                className="team-logo"
                onError={(e) => { e.target.style.display = 'none'; }}
              />
              <span className="team-name">{team1?.username || 'تیم ۱'}</span>
            </>
          ) : (
            <>
              <div className="team-logo placeholder">?</div>
              <span className="team-name">---</span>
            </>
          )}
          <div className="score-display">{match.team1Score !== null ? match.team1Score : '-'}</div>
        </div>

        <div className="vs-badge">VS</div>

        <div className={`team ${match.winner?.toString() === (match.team2?.toString()) ? 'winner' : ''}`}>
          {match.team2 ? (
            <>
              <img
                src={team2?.teamLogo || userData.teamLogo || '/default-logo.png'}
                alt="Team 2"
                className="team-logo"
                onError={(e) => { e.target.style.display = 'none'; }}
              />
              <span className="team-name">{team2?.username || 'تیم ۲'}</span>
            </>
          ) : (
            <>
              <div className="team-logo placeholder">?</div>
              <span className="team-name">---</span>
            </>
          )}
          <div className="score-display">{match.team2Score !== null ? match.team2Score : '-'}</div>
        </div>

        {isAdmin && !isFinished && match.team1 && match.team2 && (
          <div className="score-input">
            <input
              type="number"
              min="0"
              value={scoreInputs[`${round}_${index}_team1`] || ''}
              onChange={(e) => handleScoreChange(round, index, 'team1', e.target.value)}
              placeholder="تیم ۱"
              style={{ width: '50px', padding: '5px', borderRadius: '4px', border: '1px solid #444', textAlign: 'center' }}
            />
            <span>-</span>
            <input
              type="number"
              min="0"
              value={scoreInputs[`${round}_${index}_team2`] || ''}
              onChange={(e) => handleScoreChange(round, index, 'team2', e.target.value)}
              placeholder="تیم ۲"
              style={{ width: '50px', padding: '5px', borderRadius: '4px', border: '1px solid #444', textAlign: 'center' }}
            />
            <button
              onClick={() => handleSaveScore(round, index)}
              style={{
                padding: '5px 10px',
                backgroundColor: '#28a745',
                color: 'white',
                border: 'none',
                borderRadius: '4px',
                cursor: 'pointer'
              }}
            >
              ذخیره
            </button>
          </div>
        )}
      </div>
    );
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        <div className="main1">
          <SlamHeader/>
          
          {cupMessage && (
            <div style={{
              padding: '1rem', margin: '1rem',
              backgroundColor: cupMessage.includes('✅') ? '#d4edda' : '#f8d7da',
              color: cupMessage.includes('✅') ? '#155724' : '#721c24',
              borderRadius: '4px', textAlign: 'center'
            }}>
              {cupMessage}
            </div>
          )}

          <div style={{ padding: '20px', maxWidth: '1400px', margin: '0 auto' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h2 style={{ color: '#FFD700' }}>🏆 جدول حذفی - {activeCup?.name || 'جام حذفی'}</h2>
              <button
                onClick={() => navigate('/hazfi')}
                style={{
                  padding: '10px 20px',
                  backgroundColor: '#6c757d',
                  color: 'white',
                  border: 'none',
                  borderRadius: '8px',
                  cursor: 'pointer'
                }}
              >
                ← بازگشت
              </button>
            </div>

            {bracket ? (
              <div className="bracket-container">
                {/* Round of 16 */}
                <div className="bracket-round">
                  <h4 style={{ color: '#aaa', marginBottom: '15px', textAlign: 'center' }}>مرحله ۱۶ تیم</h4>
                  <div className="round-matches">
                    {bracket.round16?.map((match, idx) => renderMatch(match, 'round16', idx))}
                  </div>
                </div>

                {/* Quarterfinal */}
                <div className="bracket-round">
                  <h4 style={{ color: '#aaa', marginBottom: '15px', textAlign: 'center' }}>چهارمینی</h4>
                  <div className="round-matches">
                    {bracket.quarterfinal?.map((match, idx) => renderMatch(match, 'quarterfinal', idx))}
                  </div>
                </div>

                {/* Semifinal */}
                <div className="bracket-round">
                  <h4 style={{ color: '#aaa', marginBottom: '15px', textAlign: 'center' }}>نیمه‌نهایی</h4>
                  <div className="round-matches">
                    {bracket.semifinal?.map((match, idx) => renderMatch(match, 'semifinal', idx))}
                  </div>
                </div>

                {/* Final */}
                <div className="bracket-round final-round">
                  <h4 style={{ color: '#FFD700', marginBottom: '15px', textAlign: 'center' }}>🏆 فینال</h4>
                  <div className="round-matches">
                    {renderMatch(bracket.final, 'final', 0)}
                  </div>
                </div>
              </div>
            ) : (
              <div style={{
                backgroundColor: '#1a1a2e',
                padding: '40px',
                borderRadius: '10px',
                textAlign: 'center',
                border: '1px solid #333'
              }}>
                <div style={{ fontSize: '60px', marginBottom: '20px' }}>🏆</div>
                <h3 style={{ color: '#aaa' }}>جدول حذفی هنوز ایجاد نشده</h3>
                <p style={{ color: '#666' }}>صبر کنید تا جام حذفی شروع شود</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

export default HazfiTable;
