import api from './api';

export const paymentService = {
  // دریافت لیست پکیج‌ها
  getPackages: async () => {
    const response = await api.get('/payment/packages');
    return response.data?.packages || response.data || [];
  },

  // ایجاد درخواست پرداخت
  createPayment: async (packageId, userData = {}) => {
    const response = await api.post('/payment/create', {
      packageId,
      ...userData
    });
    return response.data;
  },

  // دریافت تاریخچه تراکنش‌ها
  getTransactions: async (limit = 10) => {
    const response = await api.get(`/payment/transactions?limit=${limit}`);
    return response.data;
  },

  // دریافت وضعیت تراکنش
  getTransactionStatus: async (transactionId) => {
    const response = await api.get(`/payment/transaction/${transactionId}`);
    return response.data;
  },

  // تأیید پرداخت (برای کال‌بک)
  verifyPayment: async (authority, status) => {
    const response = await api.post('/payment/verify', {
      authority,
      status
    });
    return response.data;
  }
};