import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import '../styles/coatch.css';
import '../styles/player.css'
import image1 from '../43dTsdAd06GgymszsvqoLmJI6UVlw6wJle33K3kI/محمدرضا اخباری.png'
import image2 from '../کارت ها/کارت-محمدرضا-اخباری.png'
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { youthCampService } from '../services/youthCampService';
import { squadService, normalizePlayers } from '../services/squadService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';

function Player() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [campInfo, setCampInfo] = useState(null);
  const [userData, setUserData] = useState({
    coins: 0,
    teamName: 'سی تی',
    players: []
  });
  const [recruiting, setRecruiting] = useState(false);
  const [firing, setFiring] = useState(null);
  const [message, setMessage] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [campRes, squadData] = await Promise.all([
        youthCampService.getCampInfo().catch(() => null),
        squadService.getPlayers()
      ]);

      if (campRes?.success) {
        setCampInfo(campRes.campInfo);
      }

      const players = normalizePlayers(squadData.players || []);
      setUserData(prev => ({
        ...prev,
        coins: squadData.coins ?? prev.coins,
        teamName: squadData.teamName || squadData.username || 'تیم من',
        players
      }));
    } catch (error) {
      console.error('Error loading data:', error);
      setMessage('خطا در بارگذاری اطلاعات');
    } finally {
      setLoading(false);
    }
  };

  const handleRecruit = async () => {
    try {
      setRecruiting(true);
      setMessage('');
      const response = await youthCampService.recruitPlayer();
      if (response.success) {
        setMessage(`✅ بازیکن ${response.player.name} با موفقیت جذب شد!`);
        await loadData();
      }
    } catch (error) {
      setMessage(error.response?.data?.message || 'خطا در جذب بازیکن');
    } finally {
      setRecruiting(false);
    }
  };

  const handleFire = async (playerId) => {
    if (!window.confirm('آیا مطمئن هستید که می‌خواهید این بازیکن را اخراج کنید؟')) {
      return;
    }

    try {
      setFiring(playerId);
      setMessage('');
      const response = await youthCampService.firePlayer(playerId);
      if (response.success) {
        setMessage(`✅ بازیکن با موفقیت اخراج شد. ${response.remainingFires} اخراج باقی مانده.`);
        await loadData();
      }
    } catch (error) {
      setMessage(error.response?.data?.message || 'خطا در اخراج بازیکن');
    } finally {
      setFiring(null);
    }
  };

  const playersByPosition = {
    GK: userData.players.filter(p => p.position === 'GK'),
    DF: userData.players.filter(p => p.position === 'DF'),
    MF: userData.players.filter(p => p.position === 'MF'),
    FW: userData.players.filter(p => p.position === 'FW')
  };

  const totalPlayers = userData.players.length;
  const maxPlayers = 20;
  const canRecruit = totalPlayers < maxPlayers;

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        <div className="main1">
          <SlamHeader/>

          {message && (
            <div style={{ 
              padding: '1rem', 
              margin: '1rem', 
              backgroundColor: message.includes('✅') ? '#d4edda' : '#f8d7da',
              color: message.includes('✅') ? '#155724' : '#721c24',
              borderRadius: '4px',
              textAlign: 'center'
            }}>
              {message}
            </div>
          )}

          <div className="card313">
            <div className="bra2">
              <div className='hebd'>
                <img className='sdfs' src={image1} alt=""/>
                <img className='cewew' src={image2} alt=""/>
              </div>
            </div>

            <div className="bva">
              <h5 style={{ color: '#333', fontWeight: 'bold' }}>
                📊 تعداد بازیکنان تیم: {totalPlayers}/{maxPlayers}
              </h5>
              <h5 
                className='sad1' 
                onClick={canRecruit ? handleRecruit : undefined}
                style={{ 
                  cursor: canRecruit ? 'pointer' : 'not-allowed', 
                  opacity: canRecruit ? 1 : 0.5 
                }}
              >
                {recruiting ? 'در حال جذب...' : 'جذب بازیکن جدید'}
              </h5>
              <h5 className='sad2'>مدت قرارداد بازیکن: دایمی</h5>
              <h5 className='sad3'>تمدید قرارداد</h5>
              <h5 className='sad4'>ثبت/ویرایش شماره پیراهن</h5>
              {campInfo && (
                <h5 className='sad5'>
                  سطح کمپ: {campInfo.level} | 
                  اخراج باقی‌مانده: {campInfo.maxFires - campInfo.monthlyFires}/{campInfo.maxFires}
                </h5>
              )}
            </div>

            <div className="bcha">
              <div className='hgsg'>
                <div className='dsjjdsd'>
                  <div className='titikel'><h4>دروازه‌بان</h4></div>
                  <div className='names'>
                    {playersByPosition.GK.length > 0 ? (
                      playersByPosition.GK.map((player) => (
                        <div key={player._id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <h4>{player.name} ({player.overall})</h4>
                          <button
                            onClick={() => handleFire(player._id)}
                            disabled={firing === player._id}
                            style={{
                              padding: '0.25rem 0.5rem',
                              backgroundColor: '#dc3545',
                              color: 'white',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer',
                              fontSize: '0.8rem'
                            }}
                          >
                            {firing === player._id ? '...' : 'اخراج'}
                          </button>
                        </div>
                      ))
                    ) : (
                      <p style={{ color: '#999' }}>بدون بازیکن</p>
                    )}
                  </div>
                </div>

                <div className='dsjjdsd'>
                  <h4 className='titikel'>مدافع</h4>
                  <div className='names'>
                    {playersByPosition.DF.length > 0 ? (
                      playersByPosition.DF.map((player) => (
                        <div key={player._id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <h4>{player.name} ({player.overall})</h4>
                          <button
                            onClick={() => handleFire(player._id)}
                            disabled={firing === player._id}
                            style={{
                              padding: '0.25rem 0.5rem',
                              backgroundColor: '#dc3545',
                              color: 'white',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer',
                              fontSize: '0.8rem'
                            }}
                          >
                            {firing === player._id ? '...' : 'اخراج'}
                          </button>
                        </div>
                      ))
                    ) : (
                      <p style={{ color: '#999' }}>بدون بازیکن</p>
                    )}
                  </div>
                </div>

                <div className='dsjjdsd'>
                  <h4 className='titikel'>هافبک</h4>
                  <div className='names'>
                    {playersByPosition.MF.length > 0 ? (
                      playersByPosition.MF.map((player) => (
                        <div key={player._id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <h4>{player.name} ({player.overall})</h4>
                          <button
                            onClick={() => handleFire(player._id)}
                            disabled={firing === player._id}
                            style={{
                              padding: '0.25rem 0.5rem',
                              backgroundColor: '#dc3545',
                              color: 'white',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer',
                              fontSize: '0.8rem'
                            }}
                          >
                            {firing === player._id ? '...' : 'اخراج'}
                          </button>
                        </div>
                      ))
                    ) : (
                      <p style={{ color: '#999' }}>بدون بازیکن</p>
                    )}
                  </div>
                </div>

                <div className='dsjjdsd'>
                  <h4 className='titikel'>مهاجم</h4>
                  <div className='names'>
                    {playersByPosition.FW.length > 0 ? (
                      playersByPosition.FW.map((player) => (
                        <div key={player._id} style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                          <h4>{player.name} ({player.overall})</h4>
                          <button
                            onClick={() => handleFire(player._id)}
                            disabled={firing === player._id}
                            style={{
                              padding: '0.25rem 0.5rem',
                              backgroundColor: '#dc3545',
                              color: 'white',
                              border: 'none',
                              borderRadius: '4px',
                              cursor: 'pointer',
                              fontSize: '0.8rem'
                            }}
                          >
                            {firing === player._id ? '...' : 'اخراج'}
                          </button>
                        </div>
                      ))
                    ) : (
                      <p style={{ color: '#999' }}>بدون بازیکن</p>
                    )}
                  </div>
                </div>
              </div>

              <div className='jdssw'>
                <div className="info-text">تیم شما دارای {totalPlayers} بازیکن است</div>
                <div className="info-text">شما می‌توانید {maxPlayers - totalPlayers} نفر به تیم خود اضافه کنید</div>
              </div>
            </div>
          </div>

          {/* بخش تصاویر بازیکنان خریداری شده - پایین صفحه */}
          {userData.players.length > 0 && (
            <div style={{
              marginTop: '20px',
              padding: '20px',
              backgroundColor: 'rgba(255, 255, 255, 0.9)',
              borderRadius: '15px',
              boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
            }}>
              <h4 style={{ 
                color: '#28a745', 
                marginBottom: '15px',
                textAlign: 'center',
                fontSize: '18px'
              }}>
                ⚽ بازیکنان خریداری شده
              </h4>
              <div style={{
                display: 'flex',
                flexWrap: 'wrap',
                gap: '15px',
                justifyContent: 'center'
              }}>
                {userData.players.map((player) => (
                  <div key={player._id} style={{
                    width: '100px',
                    height: '120px',
                    backgroundColor: '#f8f9fa',
                    borderRadius: '10px',
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    padding: '10px',
                    border: '2px solid #28a745',
                    boxShadow: '0 2px 8px rgba(0,0,0,0.1)'
                  }}>
                    <div style={{
                      width: '60px',
                      height: '60px',
                      borderRadius: '50%',
                      backgroundColor: '#28a745',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: 'white',
                      fontSize: '24px',
                      fontWeight: 'bold',
                      marginBottom: '8px'
                    }}>
                      {player.name?.charAt(0) || '?'}
                    </div>
                    <span style={{
                      fontSize: '11px',
                      fontWeight: 'bold',
                      color: '#333',
                      textAlign: 'center',
                      overflow: 'hidden',
                      textOverflow: 'ellipsis',
                      whiteSpace: 'nowrap',
                      width: '100%'
                    }}>
                      {player.name}
                    </span>
                    <span style={{
                      fontSize: '10px',
                      color: '#666',
                      backgroundColor: '#e9ecef',
                      padding: '2px 6px',
                      borderRadius: '8px'
                    }}>
                      {player.position} | OVR: {player.overall}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Player;
