import api from './api';

export const youthCampService = {
  // دریافت اطلاعات کمپ
  getCampInfo: async () => {
    const response = await api.get('/youth-camp/info');
    return response.data;
  },

  // جذب بازیکن جدید
  recruitPlayer: async () => {
    const response = await api.post('/youth-camp/recruit');
    return response.data;
  },

  // اخراج بازیکن
  firePlayer: async (playerId) => {
    const response = await api.delete(`/youth-camp/fire/${playerId}`);
    return response.data;
  }
};



