import React, { useState, useEffect } from 'react';
import {
  Container,
  Paper,
  Typography,
  TextField,
  Button,
  Stepper,
  Step,
  StepLabel,
  Box,
  Grid,
  Card,
  CardContent,
  Avatar,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  IconButton,
  Tooltip,
  Divider,
  Chip,
  CircularProgress,
  Image as MuiImage
} from '@mui/material';
import {
  SportsSoccer,
  Flag,
  Person,
  ArrowBack,
  ArrowForward,
  CheckCircle,
  Info,
  CloudUpload
} from '@mui/icons-material';
import '../styles/TeamSetupWizard.css';

const TeamSetupWizard = ({ onSubmit }) => {
  const [activeStep, setActiveStep] = useState(0);
  const [formData, setFormData] = useState({
    // Step 1: اطلاعات تیم
    teamName: '',
    teamCountry: 'ایران',
    teamLogo: '',
    logoType: 'color', // 'color' or 'upload'
    
    // Step 2: انتخاب تاکتیک پایه
    formation: '4-3-3',
    playStyle: 'متوازن',
    
    // Step 3: انتخاب بازیکنان پایه
    basePlayers: [],
    
    // Step 4: انتخاب رنگ‌های تیم
    primaryColor: '#1e88e5',
    secondaryColor: '#ff9800',
    uploadedLogo: null
  });
  
  const [errors, setErrors] = useState({});
  const [uploading, setUploading] = useState(false);
  const [adminPlayers, setAdminPlayers] = useState([]);
  const [hasAdminPlayers, setHasAdminPlayers] = useState(false);
  const [loading, setLoading] = useState(true);

  // مراحل فرم - حذف مرحله اطلاعات کاربر
  const steps = [
    'مشخصات تیم',
    'تاکتیک پایه',
    'انتخاب بازیکنان',
    'رنگ‌بندی تیم'
  ];

  // گزینه‌های کشور
  const countries = [
    'ایران', 'آمریکا', 'انگلستان', 'اسپانیا', 'آلمان', 'فرانسه',
    'ایتالیا', 'برزیل', 'آرژانتین', 'پرتغال', 'هلند', 'بلژیک'
  ];

  // گزینه‌های فرماسیون
  const formations = [
    { value: '4-4-2', label: 'کلاسیک ۴-۴-۲', description: 'متوازن دفاع و حمله' },
    { value: '4-3-3', label: 'حمله‌ای ۴-۳-۳', description: 'تمرکز بر حمله' },
    { value: '3-5-2', label: 'کنترلی ۳-۵-۲', description: 'کنترل میانی' },
    { value: '4-2-3-1', label: 'مدرن ۴-۲-۳-۱', description: 'انعطاف‌پذیر' },
    { value: '5-3-2', label: 'دفاعی ۵-۳-۲', description: 'دفاع محکم' }
  ];

  // گزینه‌های سبک بازی
  const playStyles = [
    { value: 'تهاجمی', label: '⚡ تهاجمی', description: 'حمله مداوم' },
    { value: 'متوازن', label: '⚖️ متوازن', description: 'تعادل دفاع و حمله' },
    { value: 'دفاعی', label: '🛡️ دفاعی', description: 'تمرکز بر دفاع' },
    { value: 'کنترلی', label: '🎯 کنترلی', description: 'کنترل بازی' }
  ];

  // لیست بازیکنان پایه برای انتخاب
  const basePlayersList = [
    // دروازه‌بان‌ها
    { id: 1, name: 'علیرضا حقیقی', position: 'GK', overall: 78, age: 28, value: 5000 },
    { id: 2, name: 'امیرعلی مرادمند', position: 'GK', overall: 75, age: 25, value: 4000 },
    
    // مدافعان
    { id: 3, name: 'میلاد محمدی', position: 'DF', overall: 76, age: 29, value: 4500 },
    { id: 4, name: 'سعید عزت‌اللهی', position: 'DF', overall: 77, age: 27, value: 4800 },
    { id: 5, name: 'مجید حسینی', position: 'DF', overall: 75, age: 26, value: 4200 },
    { id: 6, name: 'شجاع خلیل‌زاده', position: 'DF', overall: 74, age: 24, value: 4000 },
    
    // هافبک‌ها
    { id: 7, name: 'علیرضا جهانبخش', position: 'MF', overall: 79, age: 28, value: 5200 },
    { id: 8, name: 'احمد نوراللهی', position: 'MF', overall: 76, age: 27, value: 4700 },
    { id: 9, name: 'سامان قدوس', position: 'MF', overall: 77, age: 26, value: 4900 },
    
    // مهاجمان
    { id: 10, name: 'مهدی طارمی', position: 'FW', overall: 81, age: 29, value: 6000 },
    { id: 11, name: 'سردار آزمون', position: 'FW', overall: 80, age: 28, value: 5800 },
    { id: 12, name: 'کریم انصاریمهر', position: 'FW', overall: 79, age: 25, value: 5500 }
  ];

  // بارگذاری بازیکنان ادمین
  useEffect(() => {
    loadAdminPlayers();
  }, []);

  const loadAdminPlayers = async () => {
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      if (!token) {
        setLoading(false);
        return;
      }
      
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const res = await fetch(`${apiUrl}/api/admin/players`, {
        headers: { 'Authorization': `Bearer ${token}` }
      });
      
      if (res.ok) {
        const data = await res.json();
        if (data.players && data.players.length > 0) {
          setAdminPlayers(data.players);
          setHasAdminPlayers(true);
        }
      }
    } catch (error) {
      console.error('خطا در بارگذاری بازیکنان ادمین:', error);
    } finally {
      setLoading(false);
    }
  };

  // اعتبارسنجی هر مرحله
  const validateStep = (step) => {
    const newErrors = {};
    
    switch(step) {
      case 0: // اطلاعات تیم
        if (!formData.teamName.trim()) newErrors.teamName = 'نام تیم ضروری است';
        if (!formData.teamCountry) newErrors.teamCountry = 'کشور تیم را انتخاب کنید';
        break;
        
      case 1: // تاکتیک
        if (!formData.formation) newErrors.formation = 'فرماسیون را انتخاب کنید';
        if (!formData.playStyle) newErrors.playStyle = 'سبک بازی را انتخاب کنید';
        break;
        
      case 2: // بازیکنان
        if (formData.basePlayers.length !== 11) {
          newErrors.basePlayers = `۱۱ بازیکن انتخاب کنید (${formData.basePlayers.length}/۱۱)`;
        }
        break;
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // مدیریت تغییرات فرم
  const handleChange = (field, value) => {
    setFormData(prev => ({
      ...prev,
      [field]: value
    }));
    
    if (errors[field]) {
      setErrors(prev => ({
        ...prev,
        [field]: null
      }));
    }
  };

  // انتخاب/لغو انتخاب بازیکن
   // انتخاب/لغو انتخاب بازیکن
  const togglePlayer = (player) => {
    const playerKey = player._id || player.id;
    const isSelected = formData.basePlayers.some(p => (p._id || p.id) === playerKey);
    let updatedPlayers;
    
    if (isSelected) {
      updatedPlayers = formData.basePlayers.filter(p => (p._id || p.id) !== playerKey);
    } else {
      if (formData.basePlayers.length >= 11) {
        alert('حداکثر ۱۱ بازیکن می‌توانید انتخاب کنید');
        return;
      }
      updatedPlayers = [...formData.basePlayers, player];
    }
    
    handleChange('basePlayers', updatedPlayers);
  };


  // رفتن به مرحله بعد
  const handleNext = () => {
    if (validateStep(activeStep)) {
      setActiveStep(prev => prev + 1);
    }
  };

  // برگشت به مرحله قبل
  const handleBack = () => {
    setActiveStep(prev => prev - 1);
  };

  // آپلود لوگو
  const handleLogoUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;
    
    setUploading(true);
    try {
      const uploadData = new FormData();
      uploadData.append('logo', file);
      
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const token = localStorage.getItem('token');
      const res = await fetch(`${apiUrl}/api/upload/logo`, {
        method: 'POST',
        headers: { 'Authorization': `Bearer ${token}` },
        body: uploadData
      });
      
      if (res.ok) {
        const data = await res.json();
        handleChange('uploadedLogo', data.url);
        handleChange('teamLogo', data.url);
      } else {
        alert('خطا در آپلود لوگو');
      }
    } catch (error) {
      console.error('خطا در آپلود لوگو:', error);
      alert('خطا در آپلود لوگو');
    } finally {
      setUploading(false);
    }
  };

  // ارسال نهایی فرم
  const handleSubmit = async () => {
    const finalData = {
      team: {
        name: formData.teamName,
        country: formData.teamCountry,
        formation: formData.formation,
        playStyle: formData.playStyle,
        logo: formData.uploadedLogo || formData.teamLogo,
        logoType: formData.logoType,
        colors: {
          primary: formData.primaryColor,
          secondary: formData.secondaryColor
        }
      },
      players: formData.basePlayers.map(p => ({
        name: p.name,
        position: p.position,
        overall: p.overall,
        age: p.age,
        skills: generateSkills(p.position, p.overall)
      }))
    };
    
    try {
      await onSubmit(finalData);
    } catch (error) {
      alert('خطا در ثبت‌نام: ' + error.message);
    }
  };

  // تولید مهارت‌های بازیکن بر اساس پست و قدرت
  const generateSkills = (position, overall) => {
    const base = {
      speed: 50, shot: 50, pass: 50,
      stamina: 50, defense: 50, dribble: 50, physical: 50
    };
    
    switch(position) {
      case 'GK':
        return { ...base, defense: overall, physical: overall - 10 };
      case 'DF':
        return { ...base, defense: overall, physical: overall - 5, speed: overall - 15 };
      case 'MF':
        return { ...base, pass: overall, dribble: overall - 5, stamina: overall - 10 };
      case 'FW':
        return { ...base, shot: overall, speed: overall - 5, dribble: overall - 10 };
      default:
        return base;
    }
  };

  // رندر هر مرحله
  const getStepContent = (step) => {
    switch(step) {
      case 0: // اطلاعات تیم
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                <Flag sx={{ verticalAlign: 'middle', mr: 1 }} />
                مشخصات تیم فوتبال
              </Typography>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="نام تیم"
                value={formData.teamName}
                onChange={(e) => handleChange('teamName', e.target.value)}
                error={!!errors.teamName}
                helperText={errors.teamName}
                required
                placeholder="مثال: پرسپولیس، بارسلونا"
              />
            </Grid>
            
            <Grid item xs={12} md={6}>
              <FormControl fullWidth error={!!errors.teamCountry}>
                <InputLabel>کشور تیم</InputLabel>
                <Select
                  value={formData.teamCountry}
                  onChange={(e) => handleChange('teamCountry', e.target.value)}
                  label="کشور تیم"
                >
                  {countries.map(country => (
                    <MenuItem key={country} value={country}>{country}</MenuItem>
                  ))}
                </Select>
                {errors.teamCountry && (
                  <Typography variant="caption" color="error">
                    {errors.teamCountry}
                  </Typography>
                )}
              </FormControl>
            </Grid>
            
            <Grid item xs={12}>
              <Alert severity="info" icon={<Info />}>
                نام تیم شما در رقابت‌های لیگ و جام‌ها نمایش داده می‌شود.
              </Alert>
            </Grid>
          </Grid>
        );
        
      case 1: // تاکتیک
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                🏟️ تاکتیک و سبک بازی
              </Typography>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <FormControl fullWidth error={!!errors.formation}>
                <InputLabel>فرماسیون تیمی</InputLabel>
                <Select
                  value={formData.formation}
                  onChange={(e) => handleChange('formation', e.target.value)}
                  label="فرماسیون تیمی"
                >
                  {formations.map(form => (
                    <MenuItem key={form.value} value={form.value}>
                      <Box>
                        <Typography>{form.label}</Typography>
                        <Typography variant="caption" color="text.secondary">
                          {form.description}
                        </Typography>
                      </Box>
                    </MenuItem>
                  ))}
                </Select>
                {errors.formation && (
                  <Typography variant="caption" color="error">
                    {errors.formation}
                  </Typography>
                )}
              </FormControl>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <FormControl fullWidth error={!!errors.playStyle}>
                <InputLabel>سبک بازی</InputLabel>
                <Select
                  value={formData.playStyle}
                  onChange={(e) => handleChange('playStyle', e.target.value)}
                  label="سبک بازی"
                >
                  {playStyles.map(style => (
                    <MenuItem key={style.value} value={style.value}>
                      <Box>
                        <Typography>{style.label}</Typography>
                        <Typography variant="caption" color="text.secondary">
                          {style.description}
                        </Typography>
                      </Box>
                    </MenuItem>
                  ))}
                </Select>
                {errors.playStyle && (
                  <Typography variant="caption" color="error">
                    {errors.playStyle}
                  </Typography>
                )}
              </FormControl>
              
              <Box mt={2}>
                <Typography variant="body2" color="text.secondary">
                  <Info sx={{ fontSize: 16, verticalAlign: 'middle', mr: 0.5 }} />
                  سبک بازی بر روی عملکرد تیم در مسابقات تأثیر مستقیم دارد.
                </Typography>
              </Box>
            </Grid>
          </Grid>
        );
        
      case 2: // انتخاب بازیکنان - دو حالت
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Box display="flex" justifyContent="space-between" alignItems="center">
                <Typography variant="h6" gutterBottom>
                  ⚽ انتخاب ۱۱ بازیکن پایه
                </Typography>
                <Chip 
                  label={`${formData.basePlayers.length}/۱۱ انتخاب شده`}
                  color={formData.basePlayers.length === 11 ? "success" : "default"}
                  icon={formData.basePlayers.length === 11 ? <CheckCircle /> : undefined}
                />
              </Box>
              
              {errors.basePlayers && (
                <Alert severity="error" sx={{ mt: 2 }}>
                  {errors.basePlayers}
                </Alert>
              )}
              
              <Alert severity="info" sx={{ mt: 2, mb: 3 }}>
                {hasAdminPlayers 
                  ? 'بازیکنان از فروشگاه ادمین نمایش داده می‌شوند'
                  : 'برای شروع، ۱۱ بازیکن با بودجه اولیه ۵۰,۰۰۰ سکه انتخاب کنید.'
                }
              </Alert>
            </Grid>
            
            {loading ? (
              <Grid item xs={12}>
                <Box display="flex" justifyContent="center" p={3}>
                  <CircularProgress />
                </Box>
              </Grid>
            ) : hasAdminPlayers && adminPlayers.length >= 11 ? (
              // حالت ۲: نمایش بازیکنان ادمین مثل فروشگاه
              <Grid item xs={12}>
                <Grid container spacing={2}>
                  {adminPlayers.map((player) => {
                    const isSelected = formData.basePlayers.some(p => p._id === player._id);
                    const positionColors = {
                      'GK': '#4caf50',
                      'DF': '#2196f3',
                      'MF': '#ff9800',
                      'FW': '#f44336'
                    };
                    
                    return (
                      <Grid item xs={12} sm={6} md={4} lg={3} key={player._id}>
                        <Card 
                          sx={{ 
                            cursor: 'pointer',
                            border: isSelected ? 2 : 0,
                            borderColor: 'primary.main',
                            position: 'relative',
                            transition: 'all 0.3s'
                          }}
                          onClick={() => togglePlayer(player)}
                        >
                          {isSelected && (
                            <CheckCircle 
                              sx={{ 
                                position: 'absolute',
                                top: 8,
                                right: 8,
                                color: 'primary.main',
                                zIndex: 1
                              }} 
                            />
                          )}
                          
                          <CardContent>
                            <Box display="flex" alignItems="center" mb={1}>
                              <Avatar sx={{ bgcolor: positionColors[player.position] || '#999' }}>
                                {player.position}
                              </Avatar>
                              <Box ml={2}>
                                <Typography variant="subtitle1">
                                  {player.name}
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                  سن: {player.age || '-'} | ارزش: {player.value?.toLocaleString() || '-'} سکه
                                </Typography>
                              </Box>
                            </Box>
                            
                            <Box display="flex" justifyContent="space-between" alignItems="center">
                              <Chip 
                                label={`قدرت: ${player.overall || '-'}`}
                                color="primary"
                                size="small"
                              />
                              <Typography variant="h6" color="success.main">
                                {player.value?.toLocaleString() || '-'}
                              </Typography>
                            </Box>
                          </CardContent>
                        </Card>
                      </Grid>
                    );
                  })}
                </Grid>
              </Grid>
            ) : (
              // حالت ۱: نمایش بازیکنان پیش‌فرض
              <Grid item xs={12}>
                <Grid container spacing={2}>
                  {basePlayersList.map(player => {
                    const isSelected = formData.basePlayers.some(p => p.id === player.id);
                    const positionColors = {
                      'GK': '#4caf50',
                      'DF': '#2196f3',
                      'MF': '#ff9800',
                      'FW': '#f44336'
                    };
                    
                    return (
                      <Grid item xs={12} sm={6} md={4} lg={3} key={player.id}>
                        <Card 
                          sx={{ 
                            cursor: 'pointer',
                            border: isSelected ? 2 : 0,
                            borderColor: 'primary.main',
                            position: 'relative'
                          }}
                          onClick={() => togglePlayer(player)}
                        >
                          {isSelected && (
                            <CheckCircle 
                              sx={{ 
                                position: 'absolute',
                                top: 8,
                                right: 8,
                                color: 'primary.main',
                                zIndex: 1
                              }} 
                            />
                          )}
                          
                          <CardContent>
                            <Box display="flex" alignItems="center" mb={1}>
                              <Avatar sx={{ bgcolor: positionColors[player.position] }}>
                                {player.position}
                              </Avatar>
                              <Box ml={2}>
                                <Typography variant="subtitle1">
                                  {player.name}
                                </Typography>
                                <Typography variant="body2" color="text.secondary">
                                  سن: {player.age} | ارزش: {player.value.toLocaleString()} سکه
                                </Typography>
                              </Box>
                            </Box>
                            
                            <Box display="flex" justifyContent="space-between" alignItems="center">
                              <Chip 
                                label={`قدرت: ${player.overall}`}
                                color="primary"
                                size="small"
                              />
                              <Typography variant="h6" color="success.main">
                                {player.value.toLocaleString()}
                              </Typography>
                            </Box>
                          </CardContent>
                        </Card>
                      </Grid>
                    );
                  })}
                </Grid>
              </Grid>
            )}
            
            {/* خلاصه انتخاب */}
            <Grid item xs={12}>
              <Divider sx={{ my: 2 }} />
              <Typography variant="subtitle1" gutterBottom>
                خلاصه انتخاب‌ها:
              </Typography>
                           <Box display="flex" flexWrap="wrap" gap={1}>
                {formData.basePlayers.map((player) => {
                  const playerKey = player._id || player.id;
                  return (
                    <Chip 
                      key={playerKey}
                      label={`${player.name} (${player.position})`}
                      onDelete={() => togglePlayer(player)}
                      size="small"
                    />
                  );
                })}
              </Box>

            </Grid>
          </Grid>
        );
        
      case 3: // رنگ‌بندی و لوگو
        return (
          <Grid container spacing={3}>
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>
                🎨 رنگ‌بندی و شخصی‌سازی
              </Typography>
            </Grid>
            
            {/* بخش لوگوی تیم */}
            <Grid item xs={12}>
              <Typography variant="subtitle1" gutterBottom>
                🏅 لوگوی تیم
              </Typography>
              <Box mb={2}>
                <Button
                  variant={formData.logoType === 'color' ? 'contained' : 'outlined'}
                  onClick={() => handleChange('logoType', 'color')}
                  startIcon={<Flag />}
                  sx={{ mr: 2, mb: 1 }}
                >
                  انتخاب رنگ
                </Button>
                <Button
                  variant={formData.logoType === 'upload' ? 'contained' : 'outlined'}
                  onClick={() => handleChange('logoType', 'upload')}
                  startIcon={<CloudUpload />}
                  sx={{ mb: 1 }}
                >
                  آپلود لوگو
                </Button>
              </Box>
              
              {formData.logoType === 'upload' ? (
                <Box>
                  <input
                    accept="image/*"
                    style={{ display: 'none' }}
                    id="logo-upload-button"
                    type="file"
                    onChange={handleLogoUpload}
                  />
                  <label htmlFor="logo-upload-button">
                    <Button
                      variant="contained"
                      component="span"
                      startIcon={<CloudUpload />}
                      disabled={uploading}
                    >
                      {uploading ? 'در حال آپلود...' : 'انتخاب فایل لوگو'}
                    </Button>
                  </label>
                  {formData.uploadedLogo && (
                    <Box mt={2} textAlign="center">
                      <Typography variant="body2" color="text.secondary">
                        لوگوی انتخاب شده:
                      </Typography>
                      <img 
                        src={formData.uploadedLogo} 
                        alt="Logo Preview" 
                        style={{ 
                          maxWidth: 120, 
                          maxHeight: 120, 
                          borderRadius: '50%', 
                          marginTop: 10,
                          border: '3px solid #ddd'
                        }} 
                      />
                    </Box>
                  )}
                </Box>
              ) : (
                <Alert severity="info" icon={<Info />}>
                  از رنگ‌های زیر برای لوگوی تیم استفاده کنید
                </Alert>
              )}
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Typography gutterBottom>رنگ اول (اصلی):</Typography>
              <Box display="flex" alignItems="center" gap={2}>
                <input
                  type="color"
                  value={formData.primaryColor}
                  onChange={(e) => handleChange('primaryColor', e.target.value)}
                  style={{ width: 60, height: 60, borderRadius: '50%', border: 'none' }}
                />
                <Box>
                  <Typography variant="body1">
                    {formData.primaryColor}
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    رنگ پیراهن خانگی
                  </Typography>
                </Box>
              </Box>
              
              <Box mt={3}>
                <Typography gutterBottom>سایه‌های رنگ اصلی:</Typography>
                <Box display="flex" gap={1}>
                  {['#1565c0', '#1976d2', '#2196f3', '#64b5f6'].map(color => (
                    <Box
                      key={color}
                      sx={{
                        width: 40,
                        height: 40,
                        bgcolor: color,
                        borderRadius: 1,
                        cursor: 'pointer'
                      }}
                      onClick={() => handleChange('primaryColor', color)}
                    />
                  ))}
                </Box>
              </Box>
            </Grid>
            
            <Grid item xs={12} md={6}>
              <Typography gutterBottom>رنگ دوم (فرعی):</Typography>
              <Box display="flex" alignItems="center" gap={2}>
                <input
                  type="color"
                  value={formData.secondaryColor}
                  onChange={(e) => handleChange('secondaryColor', e.target.value)}
                  style={{ width: 60, height: 60, borderRadius: '50%', border: 'none' }}
                />
                <Box>
                  <Typography variant="body1">
                    {formData.secondaryColor}
                  </Typography>
                  <Typography variant="caption" color="text.secondary">
                    رنگ پیراهن خارج از خانه
                  </Typography>
                </Box>
              </Box>
              
              <Box mt={3}>
                <Typography gutterBottom>سایه‌های رنگ فرعی:</Typography>
                <Box display="flex" gap={1}>
                  {['#f57c00', '#ff9800', '#ffb74d', '#ffcc80'].map(color => (
                    <Box
                      key={color}
                      sx={{
                        width: 40,
                        height: 40,
                        bgcolor: color,
                        borderRadius: 1,
                        cursor: 'pointer'
                      }}
                      onClick={() => handleChange('secondaryColor', color)}
                    />
                  ))}
                </Box>
              </Box>
            </Grid>
            
            <Grid item xs={12}>
              <Divider sx={{ my: 2 }} />
              <Typography variant="subtitle1" gutterBottom>
                پیش‌نمایش:
              </Typography>
              <Box 
                sx={{ 
                  p: 3, 
                  borderRadius: 2,
                  background: `linear-gradient(135deg, ${formData.primaryColor} 0%, ${formData.secondaryColor} 100%)`,
                  color: 'white',
                  textAlign: 'center'
                }}
              >
                {formData.uploadedLogo ? (
                  <img 
                    src={formData.uploadedLogo} 
                    alt="Logo" 
                    style={{ 
                      width: 60, 
                      height: 60, 
                      borderRadius: '50%', 
                      marginBottom: 10,
                      border: '2px solid white'
                    }} 
                  />
                ) : (
                  <Box 
                    sx={{ 
                      width: 60, 
                      height: 60, 
                      borderRadius: '50%', 
                      background: 'white',
                      margin: '0 auto 10px',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: formData.primaryColor,
                      fontWeight: 'bold',
                      fontSize: 20
                    }}
                  >
                    {formData.teamName?.charAt(0) || 'ت'}
                  </Box>
                )}
                <Typography variant="h5">{formData.teamName || 'نام تیم'}</Typography>
                <Typography variant="body2">تیم فوتبال شما</Typography>
              </Box>
            </Grid>
          </Grid>
        );
        
      default:
        return 'مرحله ناشناخته';
    }
  };

  return (
    <div className="team-setup-wizard">
      <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
        <Paper elevation={3} sx={{ p: 4 }}>
          {/* هدر */}
          <Box className="wizard-header" mb={4}>
            <SportsSoccer className="wizard-icon" sx={{ fontSize: 60, color: 'primary.main', mb: 2 }} />
            <Typography className="wizard-title" variant="h4" gutterBottom>
              🎮 راه‌اندازی تیم فوتبال
            </Typography>
            <Typography className="wizard-subtitle" variant="body1" color="text.secondary">
              {steps.length} مرحله ساده برای ایجاد تیم رویایی خود
            </Typography>
          </Box>
          
          {/* Stepper */}
          <Stepper className="wizard-stepper" activeStep={activeStep} alternativeLabel sx={{ mb: 4 }}>
            {steps.map((label) => (
              <Step key={label}>
                <StepLabel>{label}</StepLabel>
              </Step>
            ))}
          </Stepper>
          
          {/* محتوای مرحله */}
          <Box sx={{ mt: 4, mb: 4 }}>
            {getStepContent(activeStep)}
          </Box>
          
          {/* دکمه‌های ناوبری */}
          <Box className="wizard-navigation" sx={{ display: 'flex', justifyContent: 'space-between', mt: 4 }}>
            <Button
              className="btn-back"
              onClick={handleBack}
              disabled={activeStep === 0}
              startIcon={<ArrowBack />}
            >
              بازگشت
            </Button>
            
            {activeStep === steps.length - 1 ? (
              <Button
                className="btn-submit"
                variant="contained"
                onClick={handleSubmit}
                endIcon={<CheckCircle />}
                size="large"
              >
                تکمیل ثبت‌نام و ایجاد تیم
              </Button>
            ) : (
              <Button
                className="btn-next"
                variant="contained"
                onClick={handleNext}
                endIcon={<ArrowForward />}
              >
                مرحله بعد
              </Button>
            )}
          </Box>
        </Paper>
      </Container>
    </div>
  );
};

export default TeamSetupWizard;
