import { createContext, useContext, useState, useEffect } from 'react';
import { socket } from '../socket'; // فایل socket.js که قبلاً ساختیم

const UserContext = createContext(undefined);

export function UserProvider({ children }) {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    // چک کردن کاربر ذخیره‌شده در localStorage بعد از رفرش صفحه
    const storedToken = localStorage.getItem('token');
    const storedUser = localStorage.getItem('user');

    if (storedToken && storedUser) {
      try {
        const parsedUser = JSON.parse(storedUser);
        setUser(parsedUser);

        // دوباره اتصال socket با توکن
        socket.auth = { token: storedToken };
        socket.connect();
      } catch (err) {
        console.error('خطا در لود کاربر از localStorage:', err);
        localStorage.removeItem('token');
        localStorage.removeItem('user');
      }
    }

    setLoading(false);
  }, []);

  // وقتی کاربر تغییر کرد (مثلاً بعد از لاگین یا آپدیت)، ذخیره کن
  useEffect(() => {
    if (user) {
      localStorage.setItem('user', JSON.stringify(user));
    }
  }, [user]);

  const value = { user, setUser, loading };

  return (
    <UserContext.Provider value={value}>
      {children}
    </UserContext.Provider>
  );
}

export function useUser() {
  const context = useContext(UserContext);
  if (context === undefined) {
    throw new Error('useUser باید داخل UserProvider استفاده بشه');
  }
  return context;
}