import React, { useState, useEffect } from 'react';

const LANDSCAPE_PATHS = ['/football90', '/login', '/register', '/LoginBootstrap', '/TeamSetupWizard.jsx'];
const MOBILE_MAX_WIDTH = 768;

export function LandscapeNotice() {
  const [show, setShow] = useState(false);

  useEffect(() => {
    const check = () => {
      const hash = window.location.hash || '';
      const path = (hash.replace('#', '') || window.location.pathname || '/').split('?')[0] || '/';
      const isLandscapePath = LANDSCAPE_PATHS.some(p => path === p || path === p + '/');
      const isMobile = window.innerWidth <= MOBILE_MAX_WIDTH;
      const isPortrait = typeof window.orientation !== 'undefined'
        ? (window.orientation === 0 || window.orientation === 180)
        : window.innerHeight > window.innerWidth;
      setShow(isMobile && isPortrait && !isLandscapePath);
    };
    check();
    window.addEventListener('resize', check);
    window.addEventListener('orientationchange', check);
    return () => {
      window.removeEventListener('resize', check);
      window.removeEventListener('orientationchange', check);
    };
  }, []);

  if (!show) return null;

  return (
    <div
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0,0,0,0.92)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        zIndex: 99999,
        padding: 24,
        textAlign: 'center',
        direction: 'rtl'
      }}
    >
      <div>
        <div style={{ fontSize: 48, marginBottom: 16 }}>📱</div>
        <p style={{ color: '#fff', fontSize: '1.25rem', marginBottom: 8 }}>
          برای تجربه بهتر، لطفاً گوشی را افقی نگه دارید.
        </p>
        <p style={{ color: '#aaa', fontSize: '0.9rem' }}>
          (چرخش به حالت landscape)
        </p>
      </div>
    </div>
  );
}

export default LandscapeNotice;
