import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/coatch.css';
import '../images/استادیوم.jpg'
import image7 from '../images/استادیوم.jpg'
import image1 from '../images/pngimg.com - coin_PNG36871.png'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image100 from '../images/98.png'
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import image3 from '../images/pngimg.com - coin_PNG36871.png'
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { facilityService } from '../services/facilityService';
import { userService } from '../services/userService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import '../styles/risponsive.css'

function Camp() {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [facilities, setFacilities] = useState(null);
  const [userData, setUserData] = useState({
    coins: 0,
    teamName: 'سی تی'
  });
  const [collecting, setCollecting] = useState(false);
  const [upgrading, setUpgrading] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [facilitiesRes, profileRes] = await Promise.all([
        facilityService.getFacilities(),
        userService.getProfile().catch(() => null)
      ]);

      if (facilitiesRes.success) {
        setFacilities(facilitiesRes.facilities);
        setUserData(prev => ({
          ...prev,
          coins: facilitiesRes.coins || 0
        }));
      }

      if (profileRes) {
        setUserData(prev => ({
          ...prev,
          teamName: profileRes.username || 'سی تی'
        }));
      }
    } catch (error) {
      console.error('Error loading data:', error);
      setMessage('خطا در بارگذاری اطلاعات');
    } finally {
      setLoading(false);
    }
  };

  const handleCollect = async (facilityType) => {
    try {
      setCollecting(true);
      setMessage('');
      const response = await facilityService.collectCoins(facilityType);
      if (response.success) {
        setMessage(`✅ ${response.collectedCoins} سکه برداشت شد!`);
        await loadData(); // بارگذاری مجدد داده‌ها
      }
    } catch (error) {
      setMessage(error.response?.data?.message || 'خطا در برداشت سکه');
    } finally {
      setCollecting(false);
    }
  };

  const handleUpgrade = async (facilityType) => {
    try {
      setUpgrading(true);
      setMessage('');
      const response = await facilityService.upgradeFacility(facilityType);
      if (response.success) {
        setMessage(`✅ ارتقاء ${facilityType} با موفقیت انجام شد!`);
        await loadData(); // بارگذاری مجدد داده‌ها
      }
    } catch (error) {
      setMessage(error.response?.data?.message || 'خطا در ارتقاء');
    } finally {
      setUpgrading(false);
    }
  };

  if (loading) {
    return (
      <div className="container1">
        <div className="con1">
          <div className="main1" style={{ padding: '2rem', textAlign: 'center' }}>
            <p>در حال بارگذاری...</p>
          </div>
        </div>
      </div>
    );
  }

  const stadium = facilities?.stadium || {
    level: 1,
    collectableCoins: 0,
    productionRate: 15,
    upgradeCost: 150,
    maxLevel: false
  };

  return (
    <div className="container1">
      <div className="con1">
    <Sidebar/>
        <div className="main1">
         <SlamHeader/>

          {message && (
            <div style={{ 
              padding: '1rem', 
              margin: '1rem', 
              backgroundColor: message.includes('✅') ? '#d4edda' : '#f8d7da',
              color: message.includes('✅') ? '#155724' : '#721c24',
              borderRadius: '4px',
              textAlign: 'center'
            }}>
              {message}
            </div>
          )}

          <div className="card23">
            <div className="righttt">
              <div className='oodd'>
                <h1>استادیوم سطح {stadium.level}</h1>
                <div className="bala">
                  <p>استادیوم شما در سطح {stadium.level} است. می‌توانید با ارتقاء آن، درآمد بیشتری از بازی‌ها کسب کنید.</p>
                </div>
              </div>

              <div className="vasat">
                <div className="rast5">
                  <h3 style={{ width: "200px" }}>ارتقا به سطح {stadium.level + 1}</h3>
                  <div className='kwnwedwj'>
                    <h5>هزینه ارتقا: {stadium.upgradeCost} </h5>
                    <img src={image3} alt="سکه"/>
                  </div>
                  <button
                    onClick={() => handleUpgrade('stadium')}
                    disabled={upgrading || stadium.maxLevel || userData.coins < stadium.upgradeCost}
                    style={{
                      padding: '0.5rem 1rem',
                      backgroundColor: (upgrading || stadium.maxLevel || userData.coins < stadium.upgradeCost) ? '#ccc' : '#28a745',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: (upgrading || stadium.maxLevel || userData.coins < stadium.upgradeCost) ? 'not-allowed' : 'pointer',
                      marginTop: '1rem'
                    }}
                  >
                    {upgrading ? 'در حال ارتقاء...' : stadium.maxLevel ? 'حداکثر سطح' : 'ارتقاء'}
                  </button>
                </div>

                <div className='ldlsd'>
                  <div className="dcsdcd" style={{ marginLeft: '10px' }}>
                    <h3>سطح {stadium.level}</h3>
                    <p className='wla'>
                      درآمد از یک بازی: <span>+{stadium.productionRate * 10}</span>
                    </p>
                    <p className='wla'>
                      تولید سکه در ساعت: <span>+{stadium.productionRate}</span>
                    </p>
                    {stadium.collectableCoins > 0 && (
                      <button
                        onClick={() => handleCollect('stadium')}
                        disabled={collecting}
                        style={{
                          padding: '0.5rem 1rem',
                          backgroundColor: collecting ? '#ccc' : '#007bff',
                          color: 'white',
                          border: 'none',
                          borderRadius: '4px',
                          cursor: collecting ? 'not-allowed' : 'pointer',
                          marginTop: '1rem',
                          width: '100%'
                        }}
                      >
                        {collecting ? 'در حال برداشت...' : `برداشت ${stadium.collectableCoins} سکه`}
                      </button>
                    )}
                  </div>

                  {!stadium.maxLevel && (
                    <div className="dccdcdas">
                      <h3>سطح {stadium.level + 1}</h3>
                      <p className='wla'>
                        درآمد از یک بازی: <span>+{stadium.productionRate * 10 + 50}</span>
                      </p>
                      <p className='wla'>
                        تولید سکه در ساعت: <span>+{stadium.productionRate + 15}</span>
                      </p>
                    </div>
                  )}
                </div>
              </div>

              <div className="paeen">
                <h6>هر ۱۰ ساعت مخزن استادیوم پر می‌شود. قبل از آن سکه‌های ذخیره شده را برداشت کنید.</h6>
              </div>
            </div>

            <div className="leftt">
              <div className="balach">
                <img src={image7} alt="استادیوم"/>
              </div>
              <div className="paeench">
                <h3>اسم ورزشگاه خانگی</h3>
                <div className='sjjsqq'>
                  <h3 className='sdqsd'>آشیانه گرگ‌ها</h3>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Camp;
