import api from './api';

/** نرمال‌سازی _id بازیکنان برای مقایسه در UI */
export function normalizePlayers(players = []) {
  return (players || []).map((p, index) => ({
    ...p,
    _id: p._id ? String(p._id) : `player-${index}`,
    name: p.name || `بازیکن ${index + 1}`,
    position: p.position || 'MF',
    overall: p.overall ?? 50,
    skills: p.skills || {}
  }));
}

export const squadService = {
  /** اطلاعات تمرین + لیست بازیکنان */
  getTrainingInfo: async () => {
    const response = await api.get('/squad/training-info');
    return response.data;
  },

  /** تیم جاری (بازیکنان + مربی) */
  getMySquad: async () => {
    const response = await api.get('/squad/my-squad');
    return response.data;
  },

  /** بارگذاری بازیکنان: اول پروفایل، در صورت خالی بودن از squad */
  getPlayers: async () => {
    try {
      const profileRes = await api.get('/auth/profile');
      const raw = profileRes.data?.user || profileRes.data;
      let players = normalizePlayers(raw?.players);

      if (players.length === 0) {
        const trainingRes = await api.get('/squad/training-info').catch(() => null);
        if (trainingRes?.data?.players?.length) {
          players = normalizePlayers(trainingRes.data.players);
        } else {
          const squadRes = await api.get('/squad/my-squad').catch(() => null);
          if (squadRes?.data?.squad?.players?.length) {
            players = normalizePlayers(squadRes.data.squad.players);
          }
        }
      }

      return {
        players,
        teamName: raw?.teamName || raw?.username || '',
        coins: raw?.coins ?? 0,
        banknotes: raw?.banknotes ?? 0,
        coach: raw?.coach || null,
        league: raw?.league || {},
        teamPower: raw?.teamPower ?? 0,
        username: raw?.username || ''
      };
    } catch (err) {
      console.error('getPlayers error:', err);
      return { players: [], teamName: '', coins: 0, banknotes: 0 };
    }
  }
};
