import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import '../styles/coatch.css';
import '../styles/shop.css';
import image1 from '../کارت ها/کارت شجاع خلیل زاده.png';
import image2 from '../کارت ها/کارت-آرمین-سهرابیان.png';
import image3 from '../کارت ها/کارت-احسان-حاج-صفی.png';
import Image5 from '../کارت ها/کارت-داریوش-شجاعیان.png';
import image6 from '../images/cash.png';
import image7 from '../images/pngimg.com - coin_PNG36871.png';
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image100 from '../images/98.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import image32 from '../images/pngimg.com - coin_PNG36871.png';
import image33 from '../images/W1fs6vDMTXnivl431Y50atqMx2kyTCJc5kTmy6hF (1)/اریک-تن-هاخ.png';
import image34 from '../images/W1fs6vDMTXnivl431Y50atqMx2kyTCJc5kTmy6hF (1)/حسین فرکی.png';
import image35 from '../images/W1fs6vDMTXnivl431Y50atqMx2kyTCJc5kTmy6hF (1)/ماسیمیلیانو آلگری.png';
import image36 from '../images/W1fs6vDMTXnivl431Y50atqMx2kyTCJc5kTmy6hF (1)/پرویز-مظلومی.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg';
import api from '../services/api';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import "../styles/shop.css"

// ========== آدرس سرور تصاویر ==========
const IMAGE_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5003';

const buildPlayerImageUrl = (player, fallback) => {
  if (player.imageUrl) return player.imageUrl;
  if (player.images && player.images.length > 0) {
    const img = player.images[0];
    if (img.startsWith('http://') || img.startsWith('https://')) return img;
    if (img.startsWith('/uploads/')) return `${IMAGE_BASE_URL}${img}`;
    return `${IMAGE_BASE_URL}/uploads/players/${img}`;
  }
  return fallback;
};

function Shop() {
  const [activeTab, setActiveTab] = useState('coaches');
  const [sortPrice, setSortPrice] = useState('');
  const [playerPosition, setPlayerPosition] = useState('');
  const [paymentType, setPaymentType] = useState(null);
  const navigate = useNavigate();

  const [coachCards, setCoachCards] = useState([]);
  const [playerCards, setPlayerCards] = useState([]);
  const [message, setMessage] = useState('');
  const [purchasing, setPurchasing] = useState(false);

  const localFallbackPlayers = [
    { id: 1, name: 'شجاع خلیل زاده', image: image1, position: 'forward', priceCash: 100, priceCoin: null },
    { id: 2, name: 'آرمین سهرابیان', image: image2, position: 'midfielder', priceCash: null, priceCoin: 150 },
    { id: 3, name: 'احسان حاج صفی', image: image3, position: 'defender', priceCash: 120, priceCoin: null },
    { id: 5, name: 'داریوش شجاعیان', image: Image5, position: 'goalkeeper', priceCash: null, priceCoin: 200 },
  ];

  const getCardsToDisplay = () => {
    const cards = activeTab === 'players' ? playerCards : coachCards;
    let filtered = cards.filter(item => {
      if (activeTab === 'players' && playerPosition && item.position !== playerPosition) return false;
      return true;
    });
    if (sortPrice) {
      filtered.sort((a, b) => {
        let priceA, priceB;
        if (paymentType === 'cash') {
          priceA = a.priceCash;
          priceB = b.priceCash;
        } else if (paymentType === 'coin') {
          priceA = a.priceCoin;
          priceB = b.priceCoin;
        } else {
          priceA = a.priceCash != null ? a.priceCash : a.priceCoin;
          priceB = b.priceCash != null ? b.priceCash : b.priceCoin;
        }
        if (priceA == null) priceA = sortPrice === 'asc' ? Infinity : -Infinity;
        if (priceB == null) priceB = sortPrice === 'asc' ? Infinity : -Infinity;
        if (sortPrice === 'asc') return priceA - priceB;
        if (sortPrice === 'desc') return priceB - priceA;
        return 0;
      });
    }
    return filtered;
  };

  const filteredCards = getCardsToDisplay();

  // fetch players/coaches from server
  const fetchPlayers = async () => {
    try {
      const res = await api.get('/player');
      const data = res.data;
      if (data && data.success && Array.isArray(data.players)) {
        const mapped = data.players.map(p => ({
          id: p._id,
          name: p.name,
          image: buildPlayerImageUrl(p, image1),
          position: p.position,
          priceCash: p.priceCash != null ? Number(p.priceCash) : null,
          priceCoin: p.priceCoin != null ? Number(p.priceCoin) : null
        }));
        setPlayerCards(mapped);
      } else {
        setPlayerCards(localFallbackPlayers);
      }
    } catch (err) {
      console.error('fetchPlayers error', err);
      setPlayerCards(localFallbackPlayers);
    }
  };

  const fetchCoaches = async () => {
    try {
      const res = await api.get('/coach');
      const data = res.data;
      if (data && data.success && Array.isArray(data.coaches)) {
        const mapped = data.coaches.map(c => ({
          id: c._id,
          name: c.name || 'مربی',
          image: c.imageUrl || (c.image
            ? (c.image.startsWith('http') ? c.image : `${IMAGE_BASE_URL}${c.image.startsWith('/') ? c.image : `/uploads/coaches/${c.image}`}`)
            : image33),
          priceCash: c.priceCash != null ? Number(c.priceCash) : null,
          priceCoin: c.priceCoin != null ? Number(c.priceCoin) : null
        }));
        setCoachCards(mapped);
      }
    } catch (err) {
      console.error('fetchCoaches error', err);
    }
  };

  React.useEffect(() => {
    fetchPlayers();
    fetchCoaches();
    const id = setInterval(() => {
      fetchPlayers();
      fetchCoaches();
    }, 10000);
    return () => clearInterval(id);
  }, []);

  const handleBuyPlayer = () => {
    setActiveTab('players');
    setPlayerPosition('');
    setSortPrice('');
  };

  const handleBuyCoach = () => {
    setActiveTab('coaches');
  };

  const handlePurchase = async (item) => {
    const typeLabel = activeTab === 'players' ? 'بازیکن' : 'مربی';
    const chosen = paymentType || (item.priceCash ? 'cash' : 'coin');
    const price = chosen === 'cash' ? item.priceCash : item.priceCoin;
    const priceTypeLabel = chosen === 'cash' ? 'اسکناس' : 'سکه';
    
    if (!price) {
      setMessage('❌ این مورد قیمت مورد نظر را ندارد.');
      return;
    }
    if (!window.confirm(`خریداری ${item.name} به عنوان ${typeLabel}\nقیمت: ${price} ${priceTypeLabel}\n\nمطمئن هستید؟`)) {
      return;
    }

    setPurchasing(true);
    setMessage('');
    
    try {
      let endpoint, payload;
      if (activeTab === 'players') {
        endpoint = '/squad/buy-player';
        payload = {
          playerId: item.id,
          paymentType: chosen === 'cash' ? 'banknotes' : 'coins'
        };
      } else {
        endpoint = '/squad/buy-coach';
        payload = {
          coachId: item.id,
          paymentType: chosen === 'cash' ? 'banknotes' : 'coins'
        };
      }

      const res = await api.post(endpoint, payload);
      if (res.data.success) {
        setMessage(`✅ ${res.data.message}`);
        setTimeout(() => {
          fetchPlayers();
          fetchCoaches();
        }, 500);
      } else {
        setMessage(`❌ ${res.data.message}`);
      }
    } catch (err) {
      setMessage(`❌ خطا: ${err.response?.data?.message || err.message}`);
    } finally {
      setPurchasing(false);
    }
  };

  const handleSortChange = (e) => {
    setSortPrice(e.target.value);
  };

  const handlePositionChange = (e) => {
    setPlayerPosition(e.target.value);
  };

  const handlePaymentTypeChange = (type) => {
    if (paymentType === type) {
      setPaymentType(null);
    } else {
      setPaymentType(type);
    }
  };

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        <div className="main1">
          <SlamHeader/>
          <div className="card28">
            <div className="sas">
              <div className="sds">
                <div 
                  className={`sscdee ${paymentType === 'cash' ? 'cash' : ''}`}
                  onClick={() => handlePaymentTypeChange('cash')}
                > 
                  <img src={image6} alt='اسکناس' /> 
                  <h2>خرید با اسکناس</h2>
                </div>
                <div 
                  className='sscdee1' 
                  onClick={() => handlePaymentTypeChange('coin')}
                  style={{
                    cursor: 'pointer',
                    opacity: paymentType === 'coin' ? 1 : 0.6,
                    border: paymentType === 'coin' ? '3px solid gold' : 'none',
                    borderRadius: '8px',
                    padding: '5px',
                    transition: 'all 0.3s'
                  }}
                > 
                  <img src={image7} alt='سکه'></img> 
                  <h2>خرید با سکه </h2>
                </div>
              </div>

              <div className="sdjdja">
                <div style={{ display: 'flex', width: 'fit-content', borderRadius: '8px', overflow: 'hidden' }}>
                  <button 
                    onClick={handleBuyPlayer}
                    style={{
                      backgroundColor: activeTab === 'players' ? '#cc0000' : '#ff6666',
                      color: 'white',
                      padding: '5px 10px',
                      border: 'none',
                      borderTopLeftRadius: '8px',
                      borderBottomLeftRadius: '8px',
                      fontWeight: 'bold',
                      cursor: 'pointer',
                    }}
                  >
                    خرید بازیکن
                  </button>
                  <button 
                    onClick={handleBuyCoach}
                    style={{
                      backgroundColor: activeTab === 'coaches' ? '#0000cc' : '#6666ff',
                      color: 'white',
                      padding: '10px 20px',
                      border: 'none',
                      borderTopRightRadius: '8px',
                      borderBottomRightRadius: '8px',
                      fontWeight: 'bold',
                      cursor: 'pointer',
                      marginLeft: '-1px',
                    }}
                  >
                    خرید مربی
                  </button>
                </div>

                {activeTab === 'players' && (
                  <>
                    <div>
                      <label className='wes'>
                        مرتب‌سازی بر اساس قیمت:
                        <select 
                          value={sortPrice}
                          onChange={handleSortChange}
                        >
                          <option value="">انتخاب کنید</option>
                          <option value="asc">از کم به زیاد</option>
                          <option value="desc">از زیاد به کم</option>
                        </select>
                      </label>
                    </div>
                    <div>
                      <label className='wes'>
                        انتخاب پست بازیکن:
                        <select 
                          value={playerPosition}
                          onChange={handlePositionChange}
                        >
                          <option value="">انتخاب کنید</option>
                          <option value="forward">مهاجم</option>
                          <option value="midfielder">هافبک</option>
                          <option value="defender">مدافع</option>
                          <option value="goalkeeper">دروازه‌بان</option>
                        </select>
                      </label>
                    </div>
                  </>
                )}
              </div>

              <div className="iwew">  
                {message && (
                  <div style={{
                    padding: '10px 15px',
                    marginBottom: '15px',
                    borderRadius: '5px',
                    backgroundColor: message.includes('❌') ? '#ffebee' : '#e8f5e9',
                    color: message.includes('❌') ? '#c62828' : '#1b5e20',
                    border: message.includes('❌') ? '1px solid #ef5350' : '1px solid #4caf50'
                  }}>
                    {message}
                  </div>
                )}
                <h6>توجه بازیکنان و سرمربیانی که از فروشگاه خریداری می شوند و قرارادشان پایان فصل نیاز به تمدید دارد یک سوم قیمت اصلی می باشد</h6>  
              </div>
            </div>

            <div className="pa2">
              {filteredCards.length > 0 ? (
                filteredCards.map((item) => (
                  <div 
                    key={item.id} 
                    className="pra"
                    style={{ 
                      cursor: purchasing ? 'not-allowed' : 'pointer', 
                      transition: 'transform 0.2s',
                      opacity: purchasing ? 0.6 : 1
                    }}
                    onMouseEnter={(e) => !purchasing && (e.currentTarget.style.transform = 'scale(1.05)')}
                    onMouseLeave={(e) => !purchasing && (e.currentTarget.style.transform = 'scale(1)')}
                    onClick={() => !purchasing && handlePurchase(item)}
                  >
                    <img
                      src={item.image}
                      alt={item.name}
                      style={{ width: '100%', objectFit: 'cover', minHeight: '120px' }}
                      onError={(e) => {
                        e.target.onerror = null;
                        e.target.src = image1;
                      }}
                    />
                    <h5>{item.name}</h5>
                    <div style={{ fontSize: '0.9rem', color: '#555', marginTop: '5px' }}>
                      {paymentType === 'cash' ? (
                        item.priceCash ? <p>خرید با اسکناس: {item.priceCash}</p> : <p style={{color:'#999'}}>قیمت اسکناس: ندارد</p>
                      ) : paymentType === 'coin' ? (
                        item.priceCoin ? <p>خرید با سکه: {item.priceCoin}</p> : <p style={{color:'#999'}}>قیمت سکه: ندارد</p>
                      ) : (
                        <>
                          {item.priceCash ? <p>خرید با اسکناس: {item.priceCash}</p> : <p style={{color:'#999'}}>قیمت اسکناس: ندارد</p>}
                          {item.priceCoin ? <p>خرید با سکه: {item.priceCoin}</p> : <p style={{color:'#999'}}>قیمت سکه: ندارد</p>}
                        </>
                      )}
                    </div>
                  </div>
                ))
              ) : (
                <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: '20px', color: '#999' }}>
                  <p>موردی برای نمایش وجود ندارد</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Shop;
