import React, { useState, useEffect, useCallback, useRef } from 'react';
import '../styles/coatch.css';
import '../styles/onlineplay.css';
import image1 from '../images/soccer-field-in-flat-style-football-stadium-illustration-on-isolated-background-sport-plan-sign-business-concept-vector.jpg';
import image2 from '../images/98.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg';
import imagees from '../images/esteghlal-min.jpg';
import imageprc from '../images/perspolis-min.jpg';
import imageFcb from '../images/FCB.svg.png';
import "../styles/risponsive.css";
import { facilityService } from '../services/facilityService';
import { youthCampService } from '../services/youthCampService';
import { paymentService } from '../services/payment';
import { userService } from '../services/userService';
import { formationService } from '../services/formationService';
import { socket } from '../socket';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';

const FORMATION_POSITIONS = {
  '4-4-2': [
    { id: 'GK', x: 50, y: 95 }, { id: 'LB', x: 20, y: 80 }, { id: 'CB1', x: 40, y: 80 },
    { id: 'CB2', x: 60, y: 80 }, { id: 'RB', x: 80, y: 80 }, { id: 'LM', x: 20, y: 60 },
    { id: 'CM1', x: 40, y: 60 }, { id: 'CM2', x: 60, y: 60 }, { id: 'RM', x: 80, y: 60 },
    { id: 'ST1', x: 40, y: 30 }, { id: 'ST2', x: 60, y: 30 }
  ],
  '4-3-3': [
    { id: 'GK', x: 50, y: 95 }, { id: 'LB', x: 20, y: 80 }, { id: 'CB1', x: 40, y: 80 },
    { id: 'CB2', x: 60, y: 80 }, { id: 'RB', x: 80, y: 80 }, { id: 'CM1', x: 30, y: 60 },
    { id: 'CM2', x: 50, y: 60 }, { id: 'CM3', x: 70, y: 60 }, { id: 'LW', x: 20, y: 30 },
    { id: 'ST', x: 50, y: 25 }, { id: 'RW', x: 80, y: 30 }
  ],
  '3-5-2': [
    { id: 'GK', x: 50, y: 95 }, { id: 'CB1', x: 30, y: 80 }, { id: 'CB2', x: 50, y: 80 },
    { id: 'CB3', x: 70, y: 80 }, { id: 'LWB', x: 15, y: 60 }, { id: 'CM1', x: 40, y: 60 },
    { id: 'CM2', x: 50, y: 60 }, { id: 'CM3', x: 60, y: 60 }, { id: 'RWB', x: 85, y: 60 },
    { id: 'ST1', x: 40, y: 30 }, { id: 'ST2', x: 60, y: 30 }
  ],
  '4-2-3-1': [
    { id: 'GK', x: 50, y: 95 }, { id: 'LB', x: 20, y: 80 }, { id: 'CB1', x: 40, y: 80 },
    { id: 'CB2', x: 60, y: 80 }, { id: 'RB', x: 80, y: 80 }, { id: 'CDM1', x: 40, y: 70 },
    { id: 'CDM2', x: 60, y: 70 }, { id: 'CAM', x: 50, y: 50 }, { id: 'LW', x: 20, y: 40 },
    { id: 'RW', x: 80, y: 40 }, { id: 'ST', x: 50, y: 25 }
  ]
};

function WeekTable() {
  const [userData, setUserData] = useState(null);
  const [facilities, setFacilities] = useState(null);
  const [liveMatches, setLiveMatches] = useState([]);
  const [activeCup, setActiveCup] = useState(null);
  const [cupMessage, setCupMessage] = useState('');
  const [leagueTable, setLeagueTable] = useState([]);
  const [teamStats, setTeamStats] = useState(null);
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [collectableCoins, setCollectableCoins] = useState({ total: 0, breakdown: {} });
  const [contractAlerts, setContractAlerts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [matchEvents, setMatchEvents] = useState([]);
  const [currentFormation, setCurrentFormation] = useState(null);
  const [matchFormations, setMatchFormations] = useState({ home: null, away: null });
  const [ballPosition, setBallPosition] = useState({ x: 50, y: 50 });
  const [matchFilter, setMatchFilter] = useState('all');
  const [paymentPackages, setPaymentPackages] = useState([]);
  const userRef = useRef(null);
  const selectedMatchRef = useRef(null);

  const getTeamLogo = (teamName) => {
    const map = {
      'پرسپولیس': imageprc,
      'استقلال': imagees,
      'PSG': imagePcg,
      'FC Barcelona': imageFcb
    };
    return map[teamName] || image2;
  };

  const mapMatchFromApi = (m, leagueLabel, week) => {
    const now = new Date();
    const start = new Date(m.startTime);
    const isLive = !m.isFinished && (m.simulationStarted || start <= now);
    return {
      homeTeam: m.homeTeamName,
      awayTeam: m.awayTeamName,
      league: m.league || leagueLabel,
      week: week || m.week,
      startTime: start,
      isLive,
      isFinished: m.isFinished,
      time: m.matchTime ? `${m.matchTime}'` : '۰\'',
      matchTime: m.matchTime || 0,
      scoreObj: m.score || { home: 0, away: 0 },
      score: m.score ? `${m.score.home} - ${m.score.away}` : '0 - 0',
      homeLogo: m.homeTeamLogo || getTeamLogo(m.homeTeamName),
      awayLogo: m.awayTeamLogo || getTeamLogo(m.awayTeamName),
      _id: m._id,
      events: m.events || [],
      matchType: m.matchType || 'league',
      cupRound: m.cupRound,
      ballPosition: m.ballPosition,
      possession: m.possession
    };
  };

  const fetchLeagueTable = async (leagueName, userTeamName) => {
    try {
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const token = localStorage.getItem('token');
      const res = await fetch(`${apiUrl}/api/league/standings?league=${encodeURIComponent(leagueName || 'لیگ محلات دسته 3')}`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {}
      }).then(r => r.json()).catch(() => ({}));
      if (res.success && Array.isArray(res.standings)) {
        setLeagueTable(res.standings.map(s => ({
          teamName: s.team,
          points: s.points,
          goalsFor: (s.goalDiff || 0) + (s.goalsAgainst || 0),
          goalsAgainst: s.goalsAgainst || 0,
          isUserTeam: s.team === (userTeamName || userData?.teamName || '')
        })).sort((a, b) => b.points - a.points));
      }
    } catch (error) {
      console.error('Error fetching league table:', error);
    }
  };

  const fetchWeekMatches = useCallback(async (userProfileData) => {
    try {
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const token = localStorage.getItem('token');
      const res = await fetch(`${apiUrl}/api/league/week-matches`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {}
      }).then(r => r.json()).catch(() => ({}));

      if (res.success) {
        const leagueMatches = (res.currentWeekMatches || []).map(m =>
          mapMatchFromApi(m, res.league, res.week)
        );
        const cupMatches = (res.cupMatches || []).map(m =>
          mapMatchFromApi(m, m.league, 0)
        );
        const allMatches = [...leagueMatches];
        cupMatches.forEach(cm => {
          if (!allMatches.find(lm => lm._id === cm._id)) allMatches.push(cm);
        });
        allMatches.sort((a, b) => a.startTime - b.startTime);
        setLiveMatches(allMatches);

        const teamName = userProfileData?.teamName || userRef.current?.teamName;
        if (res.league && teamName) {
          fetchLeagueTable(res.league, teamName);
        }
      } else {
        setLiveMatches([]);
      }
    } catch (error) {
      console.error('Error fetching week matches:', error);
      setLiveMatches([]);
    }
  }, []);

  const loadMatchDetails = async (match) => {
    if (!match?._id) return;
    try {
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const token = localStorage.getItem('token');
      const res = await fetch(`${apiUrl}/api/match/${match._id}`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {}
      }).then(r => r.json()).catch(() => ({}));

      if (res.success) {
        setMatchFormations(res.formations || { home: null, away: null });
        if (res.match?.ballPosition) setBallPosition(res.match.ballPosition);
        if (res.match?.events) {
          setMatchEvents(res.match.events.slice(-10));
        }
      }
    } catch (error) {
      console.error('Error loading match details:', error);
    }
  };

  const handleMatchClick = (match) => {
    selectedMatchRef.current = match;
    setSelectedMatch(match);
    setMatchEvents(match.events ? [...match.events].slice(-10) : []);
    if (match.ballPosition) setBallPosition(match.ballPosition);

    const userId = userRef.current?._id || userRef.current?.id;
    if (socket.connected && match._id) {
      socket.emit('leave_match', { matchId: match._id, userId });
      socket.emit('join_match', { matchId: match._id, userId });
    }
    loadMatchDetails(match);
  };

  const calculateCollectableCoins = (facilitiesData) => {
    let total = 0;
    const breakdown = {};
    if (facilitiesData) {
      Object.keys(facilitiesData).forEach(facility => {
        if (facilitiesData[facility]?.collectableCoins) {
          breakdown[facility] = facilitiesData[facility].collectableCoins;
          total += facilitiesData[facility].collectableCoins;
        }
      });
    }
    setCollectableCoins({ total, breakdown });
  };

  const checkContractAlerts = (user) => {
    const alerts = [];
    const now = new Date();
    const sevenDaysFromNow = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000);
    if (user.players?.length) {
      user.players.forEach(player => {
        if (player.contract?.expiresAt) {
          const expiryDate = new Date(player.contract.expiresAt);
          if (expiryDate < sevenDaysFromNow && expiryDate > now) {
            alerts.push({
              type: 'player',
              name: player.name,
              daysLeft: Math.ceil((expiryDate - now) / (1000 * 60 * 60 * 24)),
              playerId: player._id
            });
          }
        }
      });
    }
    if (user.coach?.contract?.expiresAt) {
      const coachExpiry = new Date(user.coach.contract.expiresAt);
      if (coachExpiry < sevenDaysFromNow && coachExpiry > now) {
        alerts.push({
          type: 'coach',
          name: user.coach.name,
          daysLeft: Math.ceil((coachExpiry - now) / (1000 * 60 * 60 * 24))
        });
      }
    }
    setContractAlerts(alerts);
  };

  const calculateTeamStats = (user) => {
    if (!user) return;
    const stats = {
      totalPlayers: user.players?.length || 0,
      avgOverall: 0,
      totalGoals: user.league?.goalsFor || 0,
      totalConceded: user.league?.goalsAgainst || 0,
      matchesPlayed: user.league?.matchesPlayed || 0,
      winRate: 0
    };
    if (user.players?.length) {
      stats.avgOverall = Math.round(
        user.players.reduce((sum, p) => sum + (p.overall || 0), 0) / user.players.length
      );
    }
    if (stats.matchesPlayed > 0) {
      stats.winRate = Math.round((Math.floor((user.league?.points || 0) / 3) / stats.matchesPlayed) * 100);
    }
    setTeamStats(stats);
  };

  const handleScheduleLeague = async () => {
    try {
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const token = localStorage.getItem('token');
      await fetch(`${apiUrl}/api/league/generate-week`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {})
        }
      });
      await fetchWeekMatches(userRef.current);
    } catch (err) {
      console.error('schedule error', err);
    }
  };

  const handleCollectCoins = async (facilityType) => {
    try {
      const result = await facilityService.collectCoins(facilityType);
      if (result.success) {
        const facilitiesData = await facilityService.getFacilities();
        setFacilities(facilitiesData.facilities || {});
        calculateCollectableCoins(facilitiesData.facilities || {});
        if (userData) {
          setUserData(prev => ({ ...prev, coins: (prev.coins || 0) + result.collectedCoins }));
        }
      }
    } catch (error) {
      console.error('Error collecting coins:', error);
    }
  };

  const handleCupRegistration = async () => {
    if (!activeCup) return;
    setCupMessage('');
    try {
      const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
      const token = localStorage.getItem('token');
      const res = await fetch(`${apiUrl}/api/cup/${activeCup._id}/register`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          ...(token ? { Authorization: `Bearer ${token}` } : {})
        }
      });
      const data = await res.json();
      if (data.success) {
        setCupMessage(data.message || 'ثبت‌نام انجام شد');
        await fetchWeekMatches(userRef.current);
      } else {
        setCupMessage(data.message || 'خطا در ثبت‌نام');
      }
    } catch (error) {
      setCupMessage('خطا در ثبت‌نام');
    }
  };

  const getPlayersOnField = (squad, side) => {
    if (!squad?.fieldPlayers?.length) return [];
    const formationName = squad.formation || '4-4-2';
    const positions = FORMATION_POSITIONS[formationName] || FORMATION_POSITIONS['4-4-2'];
    const playersObj = {};
    squad.fieldPlayers.forEach(fp => {
      playersObj[fp.positionId] = fp.playerData || fp;
    });
    return positions.map(pos => {
      const player = playersObj[pos.id];
      const xOffset = side === 'away' ? 100 - pos.x : pos.x;
      const yOffset = side === 'away' ? 100 - pos.y : pos.y;
      return {
        ...pos,
        x: xOffset,
        y: yOffset,
        name: player?.name || pos.id,
        number: player?.number || ''
      };
    });
  };

  const filteredMatches = liveMatches.filter(m => {
    if (matchFilter === 'league') return m.matchType === 'league';
    if (matchFilter === 'cup') return m.matchType === 'cup';
    return true;
  });

  const homePlayers = matchFormations.home?.squad
    ? getPlayersOnField(matchFormations.home.squad, 'home')
    : (currentFormation ? getPlayersOnField(currentFormation, 'home') : []);
  const awayPlayers = matchFormations.away?.squad
    ? getPlayersOnField(matchFormations.away.squad, 'away')
    : [];

  useEffect(() => {
    selectedMatchRef.current = selectedMatch;
  }, [selectedMatch]);

  useEffect(() => {
    if (selectedMatchRef.current || !liveMatches.length || !userRef.current?.teamName) return;
    const userTeam = userRef.current.teamName;
    const userLive = liveMatches.find(m =>
      m.isLive && !m.isFinished &&
      (m.homeTeam === userTeam || m.awayTeam === userTeam)
    );
    if (userLive) handleMatchClick(userLive);
  }, [liveMatches]);

  useEffect(() => {
    const onMatchUpdate = (data) => {
      if (!data?.matchId) return;

      setLiveMatches(prev => prev.map(m => {
        if (m._id !== data.matchId && m._id?.toString() !== data.matchId) return m;
        return {
          ...m,
          score: `${data.score.home} - ${data.score.away}`,
          scoreObj: data.score,
          time: `${data.matchTime}'`,
          matchTime: data.matchTime,
          isLive: !data.isFinished,
          isFinished: data.isFinished,
          events: data.events || m.events,
          ballPosition: data.ballPosition || m.ballPosition,
          possession: data.possession
        };
      }));

      const selId = selectedMatchRef.current?._id?.toString();
      if (selId && selId === data.matchId.toString()) {
        setSelectedMatch(prev => prev ? {
          ...prev,
          score: `${data.score.home} - ${data.score.away}`,
          scoreObj: data.score,
          time: `${data.matchTime}'`,
          matchTime: data.matchTime,
          isLive: !data.isFinished,
          isFinished: data.isFinished
        } : prev);
        if (data.events?.length) {
          setMatchEvents(data.events.slice(-10));
        }
        if (data.ballPosition) setBallPosition(data.ballPosition);
      }
    };

    if (!socket.connected) socket.connect();
    socket.on('matchUpdate', onMatchUpdate);

    return () => {
      socket.off('matchUpdate', onMatchUpdate);
    };
  }, []);

  useEffect(() => {
    const fetchInitialData = async () => {
      setLoading(true);
      try {
        const userProfile = await userService.getProfile().catch(() => null);
        if (userProfile) {
          userRef.current = userProfile;
          setUserData(userProfile);
          checkContractAlerts(userProfile);
          calculateTeamStats(userProfile);
        }

        const facilitiesData = await facilityService.getFacilities().catch(() => ({ facilities: {} }));
        setFacilities(facilitiesData.facilities || {});
        calculateCollectableCoins(facilitiesData.facilities || {});

        const formationData = await formationService.getCurrentFormation().catch(() => null);
        if (formationData) {
          setCurrentFormation({
            formation: formationData.formation || '4-4-2',
            fieldPlayers: Object.entries(formationData.players || {}).map(([positionId, player]) => ({
              positionId,
              playerData: player
            }))
          });
        }

        if (userProfile) {
          await fetchWeekMatches(userProfile);
        }

        await paymentService.getPackages().catch(() => []).then(p => {
          setPaymentPackages(Array.isArray(p) ? p : []);
        });

        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
        const token = localStorage.getItem('token');
        const cupRes = await fetch(`${apiUrl}/api/cup/active`, {
          headers: token ? { Authorization: `Bearer ${token}` } : {}
        }).then(r => r.json()).catch(() => ({}));
        if (cupRes.success) setActiveCup(cupRes.cup);
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchInitialData();

    const pollInterval = setInterval(() => {
      fetchWeekMatches(userRef.current);
    }, 30000);

    const cupInterval = setInterval(async () => {
      try {
        const apiUrl = process.env.REACT_APP_API_URL || 'http://localhost:5003';
        const token = localStorage.getItem('token');
        const cupRes = await fetch(`${apiUrl}/api/cup/active`, {
          headers: token ? { Authorization: `Bearer ${token}` } : {}
        });
        const cupData = await cupRes.json();
        if (cupData.success) setActiveCup(cupData.cup);
      } catch (e) { /* ignore */ }
    }, 15000);

    return () => {
      clearInterval(pollInterval);
      clearInterval(cupInterval);
    };
  }, [fetchWeekMatches]);

  if (loading) {
    return <div className="loading">در حال بارگذاری...</div>;
  }

  const displayEvents = matchEvents.length > 0
    ? matchEvents
    : (selectedMatch?.events?.length ? selectedMatch.events.slice(-10) : null);

  return (
    <div className="container1">
      <div className="con1">
        <Sidebar />
        <div className="main1">
          <SlamHeader />
          <div className="cardd21">
            <div className="sfsrvsv">
              <div className="ssk">
                <h3>🎮 بازی‌های زنده</h3>
                <h4>لیگ و جام حذفی | زمان‌بندی واقعی</h4>

               

          

                {filteredMatches.length > 0 ? (
                  <div className="match-schedule-container">
                    {filteredMatches.map((match) => (
                      <div
                        key={match._id}
                        className={`match-card ${match.isLive ? 'live' : 'upcoming'} ${selectedMatch?._id === match._id ? 'selected' : ''}`}
                        onClick={() => handleMatchClick(match)}
                      >
                        <div className="team-circle">
                          <img src={match.homeLogo} alt={match.homeTeam} />
                        </div>
                        <div className="match-info">
                          <div className="teams">
                            <span className="home">{match.homeTeam}</span>
                            <span className="vs">{match.isLive ? match.score : 'vs'}</span>
                            <span className="away">{match.awayTeam}</span>
                          </div>
                          <div className="details">
                            <span className="league">
                              {match.matchType === 'cup' ? `🏆 ${match.cupRound || 'جام'}` : match.league}
                            </span>
                            <span className="start-time">
                              {match.isFinished ? 'پایان' :
                                match.isLive ? `دقیقه ${match.time}` :
                                  match.startTime.toLocaleString('fa-IR', { weekday: 'short', hour: '2-digit', minute: '2-digit' })}
                            </span>
                          </div>
                        </div>
                        <div className="team-circle">
                          <img src={match.awayLogo} alt={match.awayTeam} />
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <p>هیچ بازی برنامه‌ریزی‌شده یا زنده‌ای نداریم</p>
                )}

               
              </div>

              <hr />

              <div className="eiked">
                <h1>
                  📊 گزارش زنده {selectedMatch ? `${selectedMatch.homeTeam} ${selectedMatch.score} ${selectedMatch.awayTeam}` : ''}
                </h1>
                {selectedMatch?.isLive && (
                  <p style={{ margin: '4px 0' }}>⏱️ دقیقه {selectedMatch.time} | مالکیت: {selectedMatch.possession === 'home' ? selectedMatch.homeTeam : selectedMatch.awayTeam}</p>
                )}

                {displayEvents ? (
                  [...displayEvents].reverse().map((event, index) => (
                    <div key={`${event.minute}-${index}`} className={`match-event ${event.type}`}>
                      <img src={image2} alt="Event" />
                      <div>
                        <h5>{event.description}</h5>
                        <small>دقیقه {event.minute}</small>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className='sadds1'>
                    <img src={image2} alt="Event" />
                    <h5>{selectedMatch ? 'منتظر رویداد بعدی...' : 'یک بازی را انتخاب کنید'}</h5>
                  </div>
                )}

             
              </div>

              <hr />

              <div className='sasdfdfewqq'>
                <p>🏟️ ورزشگاه: {userData?.facilities?.stadium?.level ? `آشیانه عقاب (سطح ${userData.facilities.stadium.level})` : 'آشیانه عقاب'}</p>
                <p>💰 درآمد استادیوم: {facilities?.stadium?.productionRate ? `${facilities.stadium.productionRate} سکه/ساعت` : 'در حال بارگذاری...'}</p>
              </div>
            </div>

            <div className="dsddssew" style={{ position: 'relative' }}>
              <img src={image1} alt="Football Field" style={{ width: '100%', display: 'block' }} />

              {selectedMatch && (
                <div style={{
                  position: 'absolute', top: '8px', left: '50%', transform: 'translateX(-50%)',
                  background: 'rgba(0,0,0,0.75)', color: '#fff', padding: '6px 14px',
                  borderRadius: '8px', fontSize: '14px', zIndex: 5, textAlign: 'center', minWidth: '180px'
                }}>
                  <div>{selectedMatch.homeTeam} {selectedMatch.score} {selectedMatch.awayTeam}</div>
                  <div style={{ fontSize: '12px', opacity: 0.9 }}>
                    {selectedMatch.isFinished ? 'پایان بازی' : selectedMatch.isLive ? `دقیقه ${selectedMatch.time}` : 'قبل از شروع'}
                  </div>
                </div>
              )}

              {homePlayers.map((p, i) => (
                <div key={`h-${p.id}`} style={{
                  position: 'absolute', left: `${p.x}%`, top: `${p.y}%`,
                  transform: 'translate(-50%, -50%)', width: '22px', height: '22px',
                  borderRadius: '50%', background: '#1565c0', border: '2px solid #fff',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: '9px', color: '#fff', fontWeight: 'bold', zIndex: 3
                }} title={p.name}>
                  {p.number || i + 1}
                </div>
              ))}

              {awayPlayers.map((p, i) => (
                <div key={`a-${p.id}`} style={{
                  position: 'absolute', left: `${p.x}%`, top: `${p.y}%`,
                  transform: 'translate(-50%, -50%)', width: '22px', height: '22px',
                  borderRadius: '50%', background: '#c62828', border: '2px solid #fff',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  fontSize: '9px', color: '#fff', fontWeight: 'bold', zIndex: 3
                }} title={p.name}>
                  {p.number || i + 1}
                </div>
              ))}

              {selectedMatch?.isLive && (
                <div style={{
                  position: 'absolute', left: `${ballPosition.x}%`, top: `${ballPosition.y}%`,
                  transform: 'translate(-50%, -50%)', width: '14px', height: '14px',
                  borderRadius: '50%', background: '#fff', border: '2px solid #333',
                  boxShadow: '0 0 6px rgba(255,255,255,0.8)', zIndex: 4,
                  transition: 'left 1.5s ease, top 1.5s ease'
                }} />
              )}

              {currentFormation && !selectedMatch && (
                <div className="formation-overlay">
                  <h5>ترکیب فعلی: {currentFormation.formation}</h5>
                  <p>بازیکنان: {teamStats?.totalPlayers || 0} نفر</p>
                  <p>میانگین قدرت: {teamStats?.avgOverall || 0}</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default WeekTable;

