// src/services/api.js
import axios from 'axios';

// ایجاد instance پایه axios
const api = axios.create({
  baseURL: (process.env.REACT_APP_API_URL || 'http://localhost:5003') + '/api',
  timeout: 30000,  // از 10 به 30 ثانیه افزایش
});

// Interceptor برای اضافه کردن توکن به هدرها
api.interceptors.request.use(
  (config) => {
    const token = localStorage.getItem('token');
    if (token) {
      config.headers.Authorization = `Bearer ${token}`;
    }
    console.log('📤 API Request:', config.method.toUpperCase(), config.url);
    return config;
  },
  (error) => {
    return Promise.reject(error);
  }
);

// Interceptor برای مدیریت خطاها
api.interceptors.response.use(
  (response) => {
    console.log('✅ API Response:', response.status, response.config.url);
    return response;
  },
  (error) => {
    console.error('❌ API Error:', error.response?.status, error.config?.url, error.message);
    if (error.code === 'ECONNABORTED') {
      console.error('⏰ Timeout! سرور پاسخ نداد.');
    }
    if (error.response?.status === 401) {
      localStorage.removeItem('token');
      window.location.href = '/login';
    }
    return Promise.reject(error);
  }
);

export default api;
