import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import '../styles/coatch.css';
import '../styles/poshtibani.css'
import { FaHome, FaUser, FaChartBar, FaClipboardList, FaDumbbell, FaUsers, FaChalkboardTeacher, FaShoppingCart, FaComments } from 'react-icons/fa';
import cashImage from '../images/cash.png';
import Image200 from '../images/pngimg.com - coin_PNG36871.png';
import Image300 from '../images/pie-chart.png';
import Image400 from '../images/private-account.png';
import imagePcg from '../images/4photoshop-psg-vector-logo-لوگو-پاری-سن-ژرمن.jpg'
import { userService } from '../services/userService';
import Sidebar from '../compoenents/Sidebar';
import SlamHeader from '../compoenents/SlamHeader';
import api from '../services/api';

function Poshtibani() {
  const [loading, setLoading] = useState(false);
  const [userData, setUserData] = useState({
    coins: 0,
    teamName: 'سی تی',
    role: 'user'
  });
  const [tickets, setTickets] = useState([]);
  const [newTicket, setNewTicket] = useState({
    subject: '',
    department: 'پشتیبانی',
    message: ''
  });
  const [showNewTicket, setShowNewTicket] = useState(false);
  const [message, setMessage] = useState('');
  const [isAdmin, setIsAdmin] = useState(false);
  const [selectedTicket, setSelectedTicket] = useState(null);
  const [replyMessage, setReplyMessage] = useState('');
  const [replying, setReplying] = useState(false);
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterDepartment, setFilterDepartment] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [pagination, setPagination] = useState({ page: 1, totalPages: 1, total: 0 });
  const [ticketStats, setTicketStats] = useState({ total: 0, open: 0, byStatus: {}, byDepartment: {} });

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      const profileRes = await userService.getProfile().catch(() => null);
      if (profileRes) {
        setUserData({
          coins: profileRes.coins || 0,
          teamName: profileRes.teamName || profileRes.username || 'سی تی',
          role: profileRes.role || 'user'
        });
        setIsAdmin(profileRes.role === 'admin');
      }
      loadTickets();
    } catch (error) {
      console.error('Error loading data:', error);
    }
  };

  const loadTickets = async () => {
    try {
      if (isAdmin) {
        loadAdminTickets();
      } else {
        loadUserTickets();
      }
    } catch (error) {
      console.error('Error loading tickets:', error);
    }
  };

  const loadUserTickets = async () => {
    try {
      const res = await api.get('/ticket/my-tickets').catch(() => null);
      if (res?.data) {
        setTickets(res.data.tickets || []);
      }
    } catch (error) {
      console.error('Error loading user tickets:', error);
    }
  };

  const loadAdminTickets = async () => {
    try {
      const params = new URLSearchParams({
        page: pagination.page,
        limit: 20
      });
      if (filterStatus !== 'all') params.append('status', filterStatus);
      if (filterDepartment !== 'all') params.append('department', filterDepartment);
      if (searchTerm) params.append('search', searchTerm);

      const res = await api.get(`/ticket/admin/all?${params}`).catch(() => null);
      if (res?.data) {
        setTickets(res.data.tickets || []);
        setPagination(res.data.pagination || { page: 1, totalPages: 1, total: 0 });
      }

      const statsRes = await api.get('/ticket/admin/stats').catch(() => null);
      if (statsRes?.data) {
        setTicketStats(statsRes.data.stats || {});
      }
    } catch (error) {
      console.error('Error loading admin tickets:', error);
    }
  };

  const handleSubmitTicket = async (e) => {
    e.preventDefault();
    try {
      setLoading(true);
      setMessage('');
      const res = await api.post('/ticket/create', newTicket).catch(() => null);
      if (res?.data) {
        setMessage('✅ تیکت با موفقیت ارسال شد');
        setNewTicket({ subject: '', department: 'پشتیبانی', message: '' });
        setShowNewTicket(false);
        loadTickets();
      }
    } catch (error) {
      setMessage('❌ خطا در ارسال تیکت');
    } finally {
      setLoading(false);
    }
  };

  const handleReply = async (ticketId) => {
    if (!replyMessage.trim()) {
      setMessage('⚠️ پیام نمی‌تواند خالی باشد');
      return;
    }
    try {
      setReplying(true);
      const res = await api.post(`/ticket/${ticketId}/reply`, { message: replyMessage }).catch(() => null);
      if (res?.data) {
        setMessage('✅ پاسخ ارسال شد');
        setReplyMessage('');
        setSelectedTicket(null);
        loadTickets();
      }
    } catch (error) {
      setMessage('❌ خطا در ارسال پاسخ');
    } finally {
      setReplying(false);
    }
  };

  const handleDeleteTicket = async (ticketId) => {
    if (!window.confirm('آیا مطمئن هستید که می‌خواهید این تیکت را حذف کنید؟')) {
      return;
    }
    try {
      const res = await api.delete(`/ticket/admin/${ticketId}`).catch(() => null);
      if (res?.data) {
        setMessage('✅ تیکت حذف شد');
        loadTickets();
      }
    } catch (error) {
      setMessage('❌ خطا در حذف تیکت');
    }
  };

  const handleStatusChange = async (ticketId, status) => {
    try {
      await api.put(`/ticket/admin/${ticketId}`, { status }).catch(() => null);
      setMessage('✅ وضعیت تیکت آپدیت شد');
      loadTickets();
    } catch (error) {
      setMessage('❌ خطا در آپدیت وضعیت');
    }
  };

  const getStatusInfo = (status) => {
    switch (status) {
      case 'answered':
        return { text: 'پاسخ داده شده', color: '#27ae60' };
      case 'pending':
        return { text: 'در انتظار پاسخ', color: '#e67e22' };
      case 'closed':
        return { text: 'بسته شده', color: '#95a5a6' };
      default:
        return { text: status, color: '#6c757d' };
    }
  };

  const getStatusCounts = () => {
    if (isAdmin) {
      return {
        answered: ticketStats.byStatus?.answered || 0,
        pending: ticketStats.byStatus?.pending || 0,
        closed: ticketStats.byStatus?.closed || 0
      };
    }
    return {
      answered: tickets.filter(t => t.status === 'answered').length,
      pending: tickets.filter(t => t.status === 'pending').length,
      closed: tickets.filter(t => t.status === 'closed').length
    };
  };

  const statusCounts = getStatusCounts();

  if (isAdmin) {
    return (
      <div className="container1">
        <div className="con1">
          <Sidebar/>
          <div className="main1">
            <SlamHeader/>

            {message && (
              <div style={{
                padding: '1rem', margin: '1rem',
                backgroundColor: message.includes('✅') ? '#d4edda' : message.includes('⚠️') ? '#fff3cd' : '#f8d7da',
                color: message.includes('✅') ? '#155724' : message.includes('⚠️') ? '#856404' : '#721c24',
                borderRadius: '4px', textAlign: 'center'
              }}>
                {message}
              </div>
            )}

            <div className="card23">
              <div className="table-container" style={{
                display: 'flex',
                flexDirection: 'column',
                direction: "rtl",
                fontFamily: "Tahoma, sans-serif",
                maxWidth: "90%",
                margin: "auto",
                paddingBottom: "300px",
                backgroundColor: "#fff",
                borderRadius: "8px",
              }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem', flexWrap: 'wrap', gap: '10px' }}>
                  <h2 style={{ textAlign: "right", marginBottom: "8px", fontWeight: 'bolder' }}>📋 تیکت‌ها (ادمین)</h2>
                  <div style={{ display: 'flex', gap: '10px', alignItems: 'center', flexWrap: 'wrap' }}>
                    <input
                      type="text"
                      placeholder="جستجو..."
                      value={searchTerm}
                      onChange={(e) => { setSearchTerm(e.target.value); setPagination(p => ({ ...p, page: 1 })); }}
                      style={{ padding: '0.5rem', borderRadius: '4px', border: '1px solid #ddd' }}
                    />
                    <select
                      value={filterStatus}
                      onChange={(e) => { setFilterStatus(e.target.value); setPagination(p => ({ ...p, page: 1 })); }}
                      style={{ padding: '0.5rem', borderRadius: '4px', border: '1px solid #ddd' }}
                    >
                      <option value="all">همه وضعیت‌ها</option>
                      <option value="pending">در انتظار پاسخ</option>
                      <option value="answered">پاسخ داده شده</option>
                      <option value="closed">بسته شده</option>
                    </select>
                    <select
                      value={filterDepartment}
                      onChange={(e) => { setFilterDepartment(e.target.value); setPagination(p => ({ ...p, page: 1 })); }}
                      style={{ padding: '0.5rem', borderRadius: '4px', border: '1px solid #ddd' }}
                    >
                      <option value="all">همه دپارتمان‌ها</option>
                      <option value="پشتیبانی">پشتیبانی</option>
                      <option value="مالی">مالی</option>
                      <option value="فروش">فروش</option>
                      <option value="مدیریت">مدیریت</option>
                    </select>
                  </div>
                </div>

                {/* آمار */}
                <div style={{
                  display: 'flex', gap: '15px', marginBottom: '1rem', flexWrap: 'wrap',
                  padding: '10px', backgroundColor: '#f8f9fa', borderRadius: '8px'
                }}>
                  <div style={{ textAlign: 'center', padding: '10px', backgroundColor: '#e3f2fd', borderRadius: '8px', flex: 1 }}>
                    <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#1976d2' }}>{ticketStats.total || 0}</div>
                    <div style={{ fontSize: '12px' }}>کل تیکت‌ها</div>
                  </div>
                  <div style={{ textAlign: 'center', padding: '10px', backgroundColor: '#fff3e0', borderRadius: '8px', flex: 1 }}>
                    <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#f57c00' }}>{ticketStats.open || 0}</div>
                    <div style={{ fontSize: '12px' }}>باز</div>
                  </div>
                  <div style={{ textAlign: 'center', padding: '10px', backgroundColor: '#e8f5e9', borderRadius: '8px', flex: 1 }}>
                    <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#388e3c' }}>{statusCounts.answered}</div>
                    <div style={{ fontSize: '12px' }}>پاسخ داده شده</div>
                  </div>
                  <div style={{ textAlign: 'center', padding: '10px', backgroundColor: '#ffebee', borderRadius: '8px', flex: 1 }}>
                    <div style={{ fontSize: '24px', fontWeight: 'bold', color: '#d32f2f' }}>{statusCounts.closed}</div>
                    <div style={{ fontSize: '12px' }}>بسته شده</div>
                  </div>
                </div>

                <div style={{
                  display: "flex",
                  justifyContent: "flex-end",
                  gap: "20px",
                  color: "#40E0D0",
                  marginBottom: "16px",
                  fontWeight: "bold",
                  fontSize: "14px",
                }}>
                  <div style={{ fontWeight: 'bolder' }}>({statusCounts.answered}) پاسخ داده شده</div>
                  <div>({statusCounts.pending}) در انتظار پاسخ</div>
                  <div>({statusCounts.closed}) بسته شده</div>
                </div>

                <table style={{
                  width: "100%",
                  borderCollapse: "collapse",
                  textAlign: "center",
                  fontSize: "14px",
                  boxShadow: "0 0 8px rgba(0,0,0,0.1)",
                }}>
                  <thead>
                    <tr style={{ borderBottom: "2px solid black", backgroundColor: "#e0e0e0" }}>
                      <th style={{ borderLeft: "1px solid black", padding: "8px" }}>موضوع</th>
                      <th style={{ borderLeft: "1px solid black", padding: "8px" }}>وضعیت</th>
                      <th style={{ borderLeft: "1px solid black", padding: "8px" }}>اولویت</th>
                      <th style={{ borderLeft: "1px solid black", padding: "8px" }}>دپارتمان</th>
                      <th style={{ borderLeft: "1px solid black", padding: "8px" }}>ارسال کننده</th>
                      <th style={{ borderLeft: "1px solid black", padding: "8px" }}>تاریخ</th>
                      <th style={{ borderLeft: "1px solid black", padding: "8px", borderRight: "1px solid black" }}>عملیات</th>
                    </tr>
                  </thead>
                  <tbody>
                    {tickets.map((ticket) => {
                      const statusInfo = getStatusInfo(ticket.status);
                      return (
                        <tr key={ticket._id} style={{ backgroundColor: ticket._id % 2 === 0 ? "#f0f0f0" : "#fff" }}>
                          <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>{ticket.subject}</td>
                          <td style={{ padding: "8px", color: statusInfo.color, borderBottom: "1px solid #ddd" }}>
                            {statusInfo.text}
                          </td>
                          <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>
                            <span style={{
                              backgroundColor: ticket.priority === 'high' ? '#f44336' : ticket.priority === 'medium' ? '#ff9800' : '#4caf50',
                              color: 'white',
                              padding: '2px 8px',
                              borderRadius: '4px',
                              fontSize: '12px'
                            }}>
                              {ticket.priorityText}
                            </span>
                          </td>
                          <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>{ticket.department}</td>
                          <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>{ticket.username}</td>
                          <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>{ticket.date?.split('T')[0] || ''}</td>
                          <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>
                            <div style={{ display: "flex", flexDirection: "row", alignItems: 'center', justifyContent: 'center', gap: '5px' }}>
                              <button
                                onClick={() => handleStatusChange(ticket._id, 'answered')}
                                style={{
                                  padding: "4px 8px",
                                  backgroundColor: '#28a745',
                                  color: "white",
                                  border: "none",
                                  borderRadius: "4px",
                                  cursor: "pointer",
                                  fontSize: '11px'
                                }}
                              >
                                پاسخ
                              </button>
                              <button
                                onClick={() => handleStatusChange(ticket._id, 'closed')}
                                style={{
                                  padding: "4px 8px",
                                  backgroundColor: '#6c757d',
                                  color: "white",
                                  border: "none",
                                  borderRadius: "4px",
                                  cursor: "pointer",
                                  fontSize: '11px'
                                }}
                              >
                                بستن
                              </button>
                              <button
                                onClick={() => handleDeleteTicket(ticket._id)}
                                style={{
                                  padding: "4px 8px",
                                  backgroundColor: '#dc3545',
                                  color: "white",
                                  border: "none",
                                  borderRadius: "4px",
                                  cursor: "pointer",
                                  fontSize: '11px'
                                }}
                              >
                                حذف
                              </button>
                            </div>
                          </td>
                        </tr>
                      );
                    })}
                  </tbody>
                </table>

                {/* Pagination */}
                {pagination.totalPages > 1 && (
                  <div style={{ display: 'flex', justifyContent: 'center', gap: '5px', marginTop: '1rem' }}>
                    <button
                      onClick={() => setPagination(p => ({ ...p, page: Math.max(1, p.page - 1) }))}
                      disabled={pagination.page <= 1}
                      style={{
                        padding: '5px 10px',
                        backgroundColor: pagination.page <= 1 ? '#ccc' : '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: pagination.page <= 1 ? 'not-allowed' : 'pointer'
                      }}
                    >
                      قبلی
                    </button>
                    <span style={{ padding: '5px 10px' }}>
                      صفحه {pagination.page} از {pagination.totalPages}
                    </span>
                    <button
                      onClick={() => setPagination(p => ({ ...p, page: Math.min(pagination.totalPages, p.page + 1) }))}
                      disabled={pagination.page >= pagination.totalPages}
                      style={{
                        padding: '5px 10px',
                        backgroundColor: pagination.page >= pagination.totalPages ? '#ccc' : '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: pagination.page >= pagination.totalPages ? 'not-allowed' : 'pointer'
                      }}
                    >
                      بعدی
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>
    );
  }

  // --- کاربر عادی ---
  return (
    <div className="container1">
      <div className="con1">
        <Sidebar/>
        <div className="main1">
          <SlamHeader/>

          {message && (
            <div style={{
              padding: '1rem', margin: '1rem',
              backgroundColor: message.includes('✅') ? '#d4edda' : message.includes('⚠️') ? '#fff3cd' : '#f8d7da',
              color: message.includes('✅') ? '#155724' : message.includes('⚠️') ? '#856404' : '#721c24',
              borderRadius: '4px', textAlign: 'center'
            }}>
              {message}
            </div>
          )}

          <div className="card23">
            <div className="table-container" style={{
              display: 'flex',
              flexDirection: 'column',
              direction: "rtl",
              fontFamily: "Tahoma, sans-serif",
              maxWidth: "90%",
              margin: "auto",
              paddingBottom: "300px",
              backgroundColor: "#fff",
              borderRadius: "8px",
            }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>
                <h2 style={{ textAlign: "right", marginBottom: "8px", fontWeight: 'bolder' }}>تیکت کاربران</h2>
                <button
                  onClick={() => setShowNewTicket(!showNewTicket)}
                  style={{
                    padding: '0.5rem 1rem',
                    backgroundColor: '#007bff',
                    color: 'white',
                    border: 'none',
                    borderRadius: '4px',
                    cursor: 'pointer'
                  }}
                >
                  {showNewTicket ? '❌ بستن' : '➕ تیکت جدید'}
                </button>
              </div>

              {showNewTicket && (
                <div style={{
                  padding: '1.5rem',
                  backgroundColor: '#f8f9fa',
                  borderRadius: '8px',
                  marginBottom: '2rem'
                }}>
                  <h3>ایجاد تیکت جدید</h3>
                  <form onSubmit={handleSubmitTicket}>
                    <div style={{ marginBottom: '1rem' }}>
                      <label style={{ display: 'block', marginBottom: '0.5rem' }}>موضوع:</label>
                      <input
                        type="text"
                        value={newTicket.subject}
                        onChange={(e) => setNewTicket(prev => ({ ...prev, subject: e.target.value }))}
                        required
                        style={{ width: '100%', padding: '0.5rem', borderRadius: '4px', border: '1px solid #ddd' }}
                      />
                    </div>
                    <div style={{ marginBottom: '1rem' }}>
                      <label style={{ display: 'block', marginBottom: '0.5rem' }}>دپارتمان:</label>
                      <select
                        value={newTicket.department}
                        onChange={(e) => setNewTicket(prev => ({ ...prev, department: e.target.value }))}
                        style={{ width: '100%', padding: '0.5rem', borderRadius: '4px', border: '1px solid #ddd' }}
                      >
                        <option value="پشتیبانی">پشتیبانی</option>
                        <option value="مالی">مالی</option>
                        <option value="فروش">فروش</option>
                        <option value="مدیریت">مدیریت</option>
                      </select>
                    </div>
                    <div style={{ marginBottom: '1rem' }}>
                      <label style={{ display: 'block', marginBottom: '0.5rem' }}>پیام:</label>
                      <textarea
                        value={newTicket.message}
                        onChange={(e) => setNewTicket(prev => ({ ...prev, message: e.target.value }))}
                        required
                        rows="5"
                        style={{ width: '100%', padding: '0.5rem', borderRadius: '4px', border: '1px solid #ddd' }}
                      />
                    </div>
                    <button
                      type="submit"
                      disabled={loading}
                      style={{
                        padding: '0.75rem 1.5rem',
                        backgroundColor: loading ? '#ccc' : '#28a745',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: loading ? 'not-allowed' : 'pointer'
                      }}
                    >
                      {loading ? 'در حال ارسال...' : 'ارسال تیکت'}
                    </button>
                  </form>
                </div>
              )}

              <div style={{
                display: "flex",
                justifyContent: "flex-end",
                gap: "20px",
                color: "#40E0D0",
                marginBottom: "16px",
                fontWeight: "bold",
                fontSize: "14px",
              }}>
                <div style={{ fontWeight: 'bolder' }}>({statusCounts.answered}) پاسخ داده شده</div>
                <div>({statusCounts.pending}) در انتظار پاسخ</div>
                <div>({statusCounts.closed}) بسته شده</div>
              </div>

              <table style={{
                width: "100%",
                borderCollapse: "collapse",
                textAlign: "center",
                fontSize: "14px",
                boxShadow: "0 0 8px rgba(0,0,0,0.1)",
              }}>
                <thead>
                  <tr style={{ borderBottom: "2px solid black", backgroundColor: "#e0e0e0" }}>
                    <th style={{ borderLeft: "1px solid black", padding: "8px" }}>موضوع</th>
                    <th style={{ borderLeft: "1px solid black", padding: "8px" }}>وضعیت</th>
                    <th style={{ borderLeft: "1px solid black", padding: "8px" }}>دپارتمان</th>
                    <th style={{ borderLeft: "1px solid black", padding: "8px" }}>تاریخ</th>
                    <th style={{ borderLeft: "1px solid black", padding: "8px", borderRight: "1px solid black" }}>عملیات</th>
                  </tr>
                </thead>
                <tbody>
                  {tickets.map((ticket) => {
                    const statusInfo = getStatusInfo(ticket.status);
                    return (
                      <tr key={ticket._id} style={{ backgroundColor: ticket._id % 2 === 0 ? "#f0f0f0" : "#fff" }}>
                        <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>{ticket.subject}</td>
                        <td style={{ padding: "8px", color: statusInfo.color, borderBottom: "1px solid #ddd" }}>
                          {statusInfo.text}
                        </td>
                        <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>{ticket.department}</td>
                        <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>
                          {ticket.date?.split('T')[0] || ''}
                        </td>
                        <td style={{ padding: "8px", borderBottom: "1px solid #ddd" }}>
                          <div style={{ display: "flex", flexDirection: "row", alignItems: 'center', justifyContent: 'center' }}>
                            <button
                              onClick={() => {
                                setSelectedTicket(ticket);
                                setReplyMessage('');
                              }}
                              style={{
                                padding: "6px 12px",
                                backgroundColor: "#28a745",
                                color: "white",
                                border: "none",
                                borderRadius: "4px",
                                cursor: "pointer",
                                fontSize: '12px'
                              }}
                            >
                              پاسخ
                            </button>
                          </div>
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
            </div>
          </div>

          {/* مودال پاسخ به تیکت */}
          {selectedTicket && (
            <div style={{
              position: 'fixed',
              top: 0, left: 0, right: 0, bottom: 0,
              backgroundColor: 'rgba(0,0,0,0.5)',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              zIndex: 9999
            }} onClick={() => setSelectedTicket(null)}>
              <div style={{
                backgroundColor: 'white',
                borderRadius: '10px',
                padding: '20px',
                maxWidth: '600px',
                width: '90%',
                maxHeight: '80vh',
                overflow: 'auto'
              }} onClick={e => e.stopPropagation()}>
                <h3 style={{ marginBottom: '15px' }}>💬 گفتگو: {selectedTicket.subject}</h3>
                
                {/* پیام‌ها */}
                <div style={{ maxHeight: '300px', overflow: 'auto', marginBottom: '15px' }}>
                  {selectedTicket.messages && selectedTicket.messages.map((msg, idx) => (
                    <div key={idx} style={{
                      padding: '10px',
                      marginBottom: '8px',
                      backgroundColor: msg.sender === 'admin' ? '#e3f2fd' : '#f8f9fa',
                      borderRadius: '8px',
                      borderRight: msg.sender === 'admin' ? '4px solid #2196f3' : '4px solid #666'
                    }}>
                      <div style={{ fontSize: '12px', color: '#666', marginBottom: '5px' }}>
                        {msg.sender === 'admin' ? '👨‍💼 ادمین' : '👤 شما'} - {new Date(msg.createdAt).toLocaleString('fa-IR')}
                      </div>
                      <div>{msg.message}</div>
                    </div>
                  ))}
                </div>

                {/* ارسال پاسخ */}
                <div style={{ display: 'flex', gap: '10px' }}>
                  <input
                    type="text"
                    value={replyMessage}
                    onChange={(e) => setReplyMessage(e.target.value)}
                    placeholder="پاسخ خود را بنویسید..."
                    style={{ flex: 1, padding: '10px', borderRadius: '4px', border: '1px solid #ddd' }}
                    onKeyDown={(e) => { if (e.key === 'Enter') handleReply(selectedTicket._id); }}
                  />
                  <button
                    onClick={() => handleReply(selectedTicket._id)}
                    disabled={replying}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: replying ? '#ccc' : '#28a745',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: replying ? 'not-allowed' : 'pointer'
                    }}
                  >
                    {replying ? '...' : 'ارسال'}
                  </button>
                  <button
                    onClick={() => setSelectedTicket(null)}
                    style={{
                      padding: '10px 20px',
                      backgroundColor: '#6c757d',
                      color: 'white',
                      border: 'none',
                      borderRadius: '4px',
                      cursor: 'pointer'
                    }}
                  >
                    بستن
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Poshtibani;
