import api from './api';

export const facilityService = {
  // دریافت وضعیت امکانات
  getFacilities: async () => {
    const response = await api.get('/facilities');
    return response.data;
  },

  // برداشت سکه از یک facility
  collectCoins: async (facilityType) => {
    const response = await api.post(`/facilities/collect/${facilityType}`);
    return response.data;
  },

  // ارتقاء facility
  upgradeFacility: async (facilityType) => {
    const response = await api.post(`/facilities/upgrade/${facilityType}`);
    return response.data;
  }
};



