import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { useUser } from '../contexts/UserContext';
import { socket } from '../socket';
import api from '../services/api';
import LogoImage from '../images/favicon.png'
import '../styles/register.css';

const Register = () => {
  const [formData, setFormData] = useState({ username: '', email: '', password: '', role: 'user' });
  const [message, setMessage] = useState('');
  const { setUser } = useUser();
  const { username, email, password, role } = formData;
  const navigate = useNavigate();

  const onChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const onSubmit = async (e) => {
    e.preventDefault();
    setMessage('');

    try {
      const res = await api.post('/auth/register', formData);

      if (res.data.success) {
        const { token, user: userData } = res.data;

        if (token) {
          localStorage.setItem('token', token);
        }
        if (userData) {
          localStorage.setItem('user', JSON.stringify(userData));
          setUser(userData);
          if (token) {
            socket.auth = { token };
            socket.connect();
          }
        }
        if (res.data.role) {
          localStorage.setItem('role', res.data.role);
        } else {
          localStorage.setItem('role', role);
        }

        setMessage(res.data.message || res.data.msg || 'ثبت‌نام موفقیت‌آمیز بود!');
        navigate('/TeamSetupWizard');
      } else {
        setMessage(res.data.message || res.data.msg || 'خطا در ثبت‌نام');
      }
    } catch (err) {
      console.error('Registration error:', err);
      if (err.response) {
        setMessage(err.response.data?.msg || 'خطا در ثبت‌نام');
      } else {
        setMessage('خطا: پاسخ از سرور دریافت نشد');
      }
    }
  };

  return (
    <div className="register-container d-flex justify-content-center align-items-center" style={{ minHeight: "80vh" }} dir="rtl">
      <div className="register-box bg-white p-4 rounded-lg shadow-sm border border-light" style={{ maxWidth: '400px', width: '90%' }}>
        <div className="text-center mb-3">
          <img 
            src={LogoImage}
            alt="لوگو" 
            className="img-fluid rounded-circle mb-2" 
            style={{ width: '70px', height: '70px', objectFit: 'cover' }} 
          />
          <h4 className="fw-bold text-primary">ثبت‌نام</h4>
        </div>
        
        <form onSubmit={onSubmit} className="register-form">
          <div className="form-group mb-2">
            <div className="input-group">
              <input
                type="text"
                name="username"
                value={username}
                onChange={onChange}
                placeholder="نام خود را وارد کنید"
                required
                className="form-control"
              />
            </div>
          </div>

          <div className="form-group mb-2">
            <div className="input-group">
              <input
                type="email"
                name="email"
                value={email}
                onChange={onChange}
                placeholder="ایمیل خود را وارد کنید"
                required
                className="form-control"
              />
            </div>
          </div>

          <div className="form-group mb-2">
            <div className="input-group">
              <input
                type="password"
                name="password"
                value={password}
                onChange={onChange}
                placeholder="رمز عبور خود را وارد کنید"
                required
                className="form-control"
              />
            </div>
          </div>

          <button 
            type="submit" 
            className="submit-btn btn btn-primary w-100 fw-semibold py-2 mb-2"
          >
            ثبت‌نام
          </button>
        </form>

        {message && <p className="message text-center mt-2 text-danger small alert alert-danger py-1">{message}</p>}

        <p className="text-center mt-2 text-muted small">
          حساب کاربری دارید؟ <a href="/login" className="text-primary">ورود</a>
        </p>
      </div>
    </div>
  );
};

export default Register;
